import type { Prompt } from "../prompt-types";

export const SCIENCE_PROMPTS: Prompt[] = [
  // ---- Science Explained (1025) ----
  { id: "science-1", title: "Why a fan makes us feel cool", category: "science", text: "Explain in simple words why a ceiling fan makes us feel cool on a hot day in [your city]. Say what the moving air does to the sweat on our skin, and why the fan does not cool the room itself. Use short sentences and one everyday example." },
  { id: "science-2", title: "Why the sky looks blue", category: "science", text: "Explain in simple words why the sky looks blue during the day and orange-red at sunset. Describe how sunlight meets tiny bits in the air, and why the colours change when the sun is low. Give one simple example a school child in [your city] can picture." },
  { id: "science-3", title: "How electricity reaches your home", category: "science", text: "Explain in simple words how electricity travels from a power station to a house in [your city]. Name each step in order, from the wires on tall towers to the switchboard at home. Say why the voltage is lowered before it enters a house." },
  { id: "science-4", title: "Why we hear an echo", category: "science", text: "Explain in simple words why we hear an echo when we shout near a big empty wall or in a large hall. Describe how sound travels, bounces back, and reaches our ears a little late. Say why we do not hear an echo in a small room in [your home] full of furniture." },
  { id: "science-5", title: "Why things fall to the ground", category: "science", text: "Explain in simple words why a ball dropped from a hand always falls to the ground and never floats away. Describe the pull of the Earth in plain language, and say why a feather falls more slowly than a stone. Give two everyday examples from [your home]." },
  { id: "science-6", title: "Baking soda and vinegar fizz experiment", category: "science", text: "Explain in simple words why baking soda and vinegar fizz and bubble when they are mixed in a glass. Name the gas that forms, and say why the mixture rises up. Add safety tips for doing this small experiment at home with [a child aged 8-10]." },
  { id: "science-7", title: "Why iron gates get rusty", category: "science", text: "Explain in simple words why an iron gate or a bicycle left in the rain gets rusty in [your city]. Describe what happens when iron meets water and air, and why paint or oil slows the rust down. Give three easy ways to protect iron at home." },
  { id: "science-8", title: "How soap cleans dirty hands", category: "science", text: "Explain in simple words how soap cleans dirty hands and oily plates. Describe how soap loosens dirt and oil so water can wash them away, and why rubbing for twenty seconds matters. Explain why plain water alone does not clean grease well when you wash up in [your kitchen]." },
  { id: "science-9", title: "Why lemon juice stops apple browning", category: "science", text: "Explain in simple words why cut apple slices turn brown in the air and why squeezing lemon juice on them keeps them fresh-looking. Describe the simple change that happens on the apple surface, and say how long the lemon juice trick usually works for [your lunchbox]." },
  { id: "science-10", title: "How milk turns into curd", category: "science", text: "Explain in simple words how warm milk turns into curd when a spoon of old curd is added and left overnight in [your kitchen]. Describe what the tiny helpful germs in the curd do to the milk, and why the milk must be warm, not hot, for the curd to set well." },
  { id: "science-11", title: "How your heart pumps blood", category: "science", text: "Explain in simple words how the heart works as a pump, in general terms only. Describe how blood carries oxygen and food to every part of the body, and why the heart beats faster when we run or play [your favourite game]. This is general information, not medical advice." },
  { id: "science-12", title: "Why sleep helps your body", category: "science", text: "Explain in simple words why sleep is important for the body and the mind, in general terms only. Describe what the body does while we sleep, such as resting muscles and sorting memories. Say how many hours of sleep a [school child / adult] usually needs each night." },
  { id: "science-13", title: "How food travels through your body", category: "science", text: "Explain in simple words, in general terms only, how food travels from the mouth through the stomach and intestines. Describe how the body takes useful parts from food and removes the waste. Use a simple journey story a school child in [your class] can follow easily." },
  { id: "science-14", title: "Why we blink and tear up", category: "science", text: "Explain in simple words why we blink many times every minute and why our eyes water when dust or smoke gets in on a [dusty road]. Describe how blinking spreads a thin wet layer over the eye to keep it clean. This is general information, not medical advice." },
  { id: "science-15", title: "How bones stay strong", category: "science", text: "Explain in simple words, in general terms only, how bones stay strong as we grow. Describe how food with calcium, sunlight, and daily movement such as walking in [your park] help bones, and why children and older people both need to care for their bones." },
  { id: "science-16", title: "Why the moon changes shape", category: "science", text: "Explain in simple words why the moon looks different on different nights, from a thin crescent to a full round moon over [one month]. Describe how sunlight falls on the moon as it moves around the Earth, and why we sometimes see only part of the lit side." },
  { id: "science-17", title: "Why India has hot and cold seasons", category: "science", text: "Explain in simple words why [your city] has a hot summer, a rainy season, and a cooler winter. Describe how the tilt of the Earth changes how much sunlight each part of India gets through the year. Give one example of how people change food or clothes with the season." },
  { id: "science-18", title: "How rain and monsoon form", category: "science", text: "Explain in simple words how rain forms and why the monsoon brings heavy rain to India every year. Describe how water rises from the sea, cools into clouds, and falls as rain. Say why farmers in [your state] wait for the monsoon before sowing." },
  { id: "science-19", title: "Why earthquakes happen", category: "science", text: "Explain in simple words why earthquakes happen and why some places in India feel them more often. Describe how big slabs of rock under the ground move slowly and sometimes slip suddenly. Say what people in [your city] should do, in general, to stay safe during a tremor." },
  { id: "science-20", title: "What happens during a solar eclipse", category: "science", text: "Explain in simple words what happens during a solar eclipse, when the moon passes between the sun and the Earth. Describe why the sky darkens for a short time, and why we must never look at the sun directly, even during an eclipse. Give safe ways to watch it from [your home]." },
  { id: "science-21", title: "How plants make their own food", category: "science", text: "Explain in simple words how a green plant makes its own food from sunlight, water, and air. Describe what the leaves do with sunlight, and why plants give out oxygen. Use a tulsi or money plant in [your home] as the example, and keep the words very simple." },
  { id: "science-22", title: "How birds fly in the sky", category: "science", text: "Explain in simple words how a bird flies, using a [crow / pigeon] seen in [your city] as the example. Describe how the shape of the wings pushes air down and lifts the bird up, and why big birds flap less than small birds. Keep the words very simple." },
  { id: "science-23", title: "Simple magnet experiment at home", category: "science", text: "Plan a simple magnet experiment a child can do at home with a fridge magnet from [your kitchen], a spoon, a coin, a nail, and a pencil. List what to test, what to record, and what the child will learn about which things a magnet pulls. Add one safety tip for small children." },
  { id: "science-24", title: "Grow a plant from a seed", category: "science", text: "Plan a simple week-long experiment for a child in [Class 4] to grow a moong or chana seed in a wet cotton cloth. Say what to do each day, what to watch for, and what the child will learn about roots, shoots, and sunlight. Add what to do if the seed does not sprout." },
  { id: "science-25", title: "Make a rainbow in a glass", category: "science", text: "Plan a simple home experiment to make layers of coloured water in a glass using sugar, water, and food colour from [your kitchen]. Give the steps in order, say why the layers stay separate, and what a child learns about how heavy each layer is. Add one safety tip." },
  { id: "science-26", title: "Why the night sky looks dark", category: "science", text: "Explain in simple words why the sky looks dark at night even though the sun is still shining somewhere else. Use the spinning Earth and [your city] at night as an example, and say why we can see the moon and stars then." },
  { id: "science-27", title: "How a mirror forms an image", category: "science", text: "Explain how a flat mirror forms an image of a person standing in front of it. Tell me why the image looks the same size, why left and right seem swapped, and what happens when [two mirrors] face each other." },
  { id: "science-28", title: "Why shadows change during the day", category: "science", text: "Explain why our shadows are long in the morning, short at noon and long again in the evening. Use the example of a tree in [your school ground] and tell me what causes the change in shadow length." },
  { id: "science-29", title: "How a rainbow is formed", category: "science", text: "Explain how a rainbow forms after rain in simple words. Tell me what sunlight, raindrops and our eyes do to make the colours appear, and why we see a bow shape. Give one example from [a rainy day in your town]." },
  { id: "science-30", title: "Why we see lightning before thunder", category: "science", text: "Explain why we see lightning first and hear thunder later during a storm. Compare the speed of light and sound in simple words, and tell me how to guess how far away the storm is in [your area]." },
  { id: "science-31", title: "How a magnifying glass works", category: "science", text: "Explain how a magnifying glass makes small print look bigger. Tell me what the curved glass does to light, why we must hold it at the right distance, and how people use it to read [a newspaper] at home." },
  { id: "science-32", title: "Why a spoon looks bent in water", category: "science", text: "Explain why a spoon in a glass of water looks bent at the surface. Tell me how light changes direction when it moves from air into water, and give two more daily examples of this effect in [your kitchen]." },
  { id: "science-33", title: "White light and seven colours", category: "science", text: "Explain how white sunlight is made of seven colours. Tell me what happens when sunlight passes through a prism or raindrops, name the colours in order, and give a simple way to show this to a child at [home]." },
  { id: "science-34", title: "Why the moon shines at night", category: "science", text: "Explain why the moon shines at night even though it makes no light of its own. Tell me where its light comes from, why its shape seems to change, and why we cannot see it clearly on [a cloudy night]." },
  { id: "science-35", title: "How our eyes see colours", category: "science", text: "Explain in simple words how our eyes see different colours. Tell me what happens when light enters the eye, why a red shirt looks red, and why some people find it hard to tell [two colours] apart." },
  { id: "science-36", title: "Why objects look black or white", category: "science", text: "Explain why a black shirt feels hotter in the sun than a white shirt. Tell me how different colours absorb or reflect light, and give practical advice for choosing clothes on a hot day in [your city]." },
  { id: "science-37", title: "How a torch makes a beam", category: "science", text: "Explain how a torch makes a bright beam of light in the dark. Tell me what the bulb, battery and shiny reflector inside do, and why the beam spreads out as it travels farther from [the torch]." },
  { id: "science-38", title: "Why we need light to see", category: "science", text: "Explain why we cannot see anything in a fully dark room. Tell me how light travels from a lamp to an object and then to our eyes, and what happens when there is no light source in [the room]." },
  { id: "science-39", title: "How light travels in straight lines", category: "science", text: "Explain with daily examples that light travels in straight lines. Tell me why a wall blocks light, how a pinhole makes an upside-down image, and how this idea helps us understand shadows in [your home]." },
  { id: "science-40", title: "Why the sun feels hot", category: "science", text: "Explain why sunlight feels hot on our skin even though the sun is very far away. Tell me how light carries heat, why midday sun feels stronger than morning sun, and how to stay safe in [summer]." },
  { id: "science-41", title: "How a periscope lets us see over walls", category: "science", text: "Explain how a periscope helps a person see over a wall or around a corner. Tell me how mirrors inside it bounce light, and give one use for it in [a submarine or a school science room]." },
  { id: "science-42", title: "Why water in a pool looks shallow", category: "science", text: "Explain why a swimming pool looks less deep than it really is. Tell me how light bending in water tricks our eyes, and why this matters for safety when a child steps into [a pool]." },
  { id: "science-43", title: "How a camera focuses light", category: "science", text: "Explain in simple words how a phone camera focuses light to take a clear photo. Tell me what the lens does, why a photo goes blurry when the subject moves, and how to take a sharp photo in [low light]." },
  { id: "science-44", title: "Why street lights glow at night", category: "science", text: "Explain how a street light spreads light over a road at night. Tell me why the ground near the pole is brightest, why the light fades farther away, and how this helps drivers on [a road near you]." },
  { id: "science-45", title: "How a rainbow colours a soap bubble", category: "science", text: "Explain why a soap bubble shows rainbow colours in sunlight. Tell me how the thin soap film splits light into colours, why the colours keep changing, and how to show this to children using [soap water]." },
  { id: "science-46", title: "Why we see our face in still water", category: "science", text: "Explain why we can see our face in still water but not in rough water. Tell me how a smooth surface reflects light clearly, why waves break the image, and where you can see this in [a lake or a bucket]." },
  { id: "science-47", title: "How a solar cooker uses sunlight", category: "science", text: "Explain how a solar cooker uses sunlight to cook food without fire or gas. Tell me how mirrors or a shiny box collect heat, what foods cook well in it, and why it works best on [a sunny day]." },
  { id: "science-48", title: "Why a prism splits white light", category: "science", text: "Explain why a glass prism splits white light into a band of colours. Tell me how each colour bends by a different amount, which colour bends most, and how to remember the colour order with [a simple trick]." },
  { id: "science-49", title: "How sunglasses protect our eyes", category: "science", text: "Explain how sunglasses protect our eyes from bright sunlight. Tell me what the dark lens does to light, why cheap glasses can still harm the eyes, and how to choose safe sunglasses in [your town]." },
  { id: "science-50", title: "Why the evening sky turns red", category: "science", text: "Explain why the sky turns red or orange in the evening. Tell me how sunlight travels a longer path through the air at sunset, which colours scatter away, and why dusty days in [your city] make it redder." },
  { id: "science-51", title: "How a laser pointer makes a dot", category: "science", text: "Explain how a laser pointer makes a small bright dot far away. Tell me how its light stays in a narrow beam, why it looks brighter than a torch, and why we must never point it at [a person's eyes]." },
  { id: "science-52", title: "Why headlights dazzle at night", category: "science", text: "Explain why bright headlights dazzle us when we drive at night. Tell me how strong light affects our eyes, why it takes time to see clearly again, and what drivers should do on [a busy road]." },
  { id: "science-53", title: "How a lighthouse guides ships", category: "science", text: "Explain how a lighthouse guides ships safely at night. Tell me how its strong rotating light travels over the sea, why ships can see it from far away, and how sailors in [a coastal town] use it." },
  { id: "science-54", title: "Why a diamond sparkles in light", category: "science", text: "Explain why a diamond sparkles more than a plain piece of glass. Tell me how its cut faces bend and reflect light many times, why it flashes different colours, and what makes a stone look bright in [a jewellery shop]." },
  { id: "science-55", title: "How fireflies glow without heat", category: "science", text: "Explain how a firefly glows at night without a bulb or fire. Tell me in simple words how it makes its own cold light, why it flashes, and where people in [your village] can see fireflies after rain." },
  { id: "science-56", title: "Why sound travels through air", category: "science", text: "Explain in simple words how sound travels through air to reach our ears. Tell me what happens when a drum is hit, how air particles carry the sound, and why we hear nothing in [an empty space]." },
  { id: "science-57", title: "How an echo is formed", category: "science", text: "Explain how an echo forms when we shout near a hill or a large empty building. Tell me how sound bounces back, why the echo comes late, and how to hear a clear echo in [a place near you]." },
  { id: "science-58", title: "Why a whisper is hard to hear", category: "science", text: "Explain why a whisper is hard to hear from far away. Tell me how sound gets weaker as it spreads out, what makes a voice louder, and why a quiet classroom in [your school] helps everyone hear better." },
  { id: "science-59", title: "How a guitar makes different notes", category: "science", text: "Explain how a guitar makes high and low notes. Tell me how the length, thickness and tightness of a string change its sound, and how a player in [your town] tunes the strings before playing." },
  { id: "science-60", title: "Why we hear thunder after lightning", category: "science", text: "Explain why thunder comes after lightning even though both start together in a storm cloud. Compare light and sound speeds in simple words, and tell me how children in [your home] can count the gap." },
  { id: "science-61", title: "How our ears hear sound", category: "science", text: "Explain in simple words how our ears turn sound waves into what we hear. Tell me what the eardrum does, why loud music can hurt our ears, and how to protect hearing at [a loud function]." },
  { id: "science-62", title: "Why sound is louder in a hall", category: "science", text: "Explain why a voice sounds louder in an empty hall than in an open ground. Tell me how walls reflect sound, what echo does to speech, and why curtains and chairs in [a marriage hall] reduce the echo." },
  { id: "science-63", title: "How a whistle makes a sharp sound", category: "science", text: "Explain how a whistle makes a sharp, high sound when we blow into it. Tell me how fast-moving air vibrates inside the whistle, why a small whistle sounds higher, and how a referee uses it in [a football match]." },
  { id: "science-64", title: "Why a bell rings when struck", category: "science", text: "Explain why a temple bell rings loudly when struck and keeps ringing for a while. Tell me how the metal vibrates, why the sound slowly fades, and what makes a big bell in [a temple] sound deeper." },
  { id: "science-65", title: "How sound travels through water", category: "science", text: "Explain how sound travels through water faster than through air. Tell me why a swimmer can hear a splash underwater, how whales use sound in the sea, and why shouting underwater in [a pool] sounds dull." },
  { id: "science-66", title: "Why a drum sounds different sizes", category: "science", text: "Explain why a big drum sounds deeper than a small drum. Tell me how the size of the drum skin changes the vibration, why a tight skin sounds higher, and how a dhol player in [your town] changes the tone." },
  { id: "science-67", title: "How a loudspeaker makes sound louder", category: "science", text: "Explain how a loudspeaker makes a small sound much louder. Tell me what the cone inside does, how electricity makes it vibrate, and why a big speaker at [a school function] can be heard far away." },
  { id: "science-68", title: "Why we hear our own voice differently", category: "science", text: "Explain why our own voice sounds different in a recording. Tell me how we hear ourselves through bone as well as air, why a recording sounds strange at first, and how singers in [your city] get used to it." },
  { id: "science-69", title: "How a microphone picks up sound", category: "science", text: "Explain in simple words how a microphone picks up our voice. Tell me how sound waves move a thin part inside it, how that becomes an electric signal, and why we must speak close to [the microphone]." },
  { id: "science-70", title: "Why dogs hear sounds we cannot", category: "science", text: "Explain why dogs can hear sounds that humans cannot hear. Tell me about high sounds beyond our hearing range, why a dog reacts to a whistle we cannot hear, and how this helps a pet owner in [your home]." },
  { id: "science-71", title: "How sound helps blind people move", category: "science", text: "Explain how some blind people use sound and echoes to move around safely. Tell me how clicking sounds bounce off walls and objects, what the echo tells them, and how this skill helps in [a familiar street]." },
  { id: "science-72", title: "Why a train sounds louder at night", category: "science", text: "Explain why a train or a temple bell sounds louder at night than in the day. Tell me how cool night air carries sound better, why there is less background noise, and how people near [a railway track] notice this." },
  { id: "science-73", title: "How a flute makes sweet music", category: "science", text: "Explain how a flute makes sweet music when a player blows across its hole. Tell me how air vibrates inside the tube, why covering holes changes the note, and how a beginner in [your town] learns the first notes." },
  { id: "science-74", title: "Why a voice sounds different on phone", category: "science", text: "Explain why a familiar voice sounds a little different on a phone call. Tell me how a phone picks up only part of the sound, what gets lost, and why we still recognise our mother on [a mobile phone]." },
  { id: "science-75", title: "How noise harms our health", category: "science", text: "Explain how loud noise from traffic, crackers and machines can harm our health. Tell me what it does to our ears and sleep, and give five simple ways a family in [your area] can reduce noise at home." },
  { id: "science-76", title: "Why a tuning fork hums after striking", category: "science", text: "Explain why a tuning fork hums for a long time after we strike it. Tell me how its two arms vibrate, why the sound is a single clear note, and how music teachers use it to tune [an instrument]." },
  { id: "science-77", title: "How a veena string makes sound", category: "science", text: "Explain how plucking a veena string makes sound. Tell me how the string vibrates, how the wooden body makes the sound louder, and why pressing the string at different points in [a lesson] changes the note." },
  { id: "science-78", title: "Why sound fades with distance", category: "science", text: "Explain why a sound gets fainter as we move farther from its source. Tell me how sound spreads out in all directions, why it loses energy, and how this affects calling a friend across [a large ground]." },
  { id: "science-79", title: "How a stethoscope helps a doctor hear", category: "science", text: "Explain how a doctor uses a stethoscope to hear a heartbeat clearly. Tell me how the tube carries sound from the chest to the ears, why it blocks outside noise, and how it helps in [a clinic]." },
  { id: "science-80", title: "Why we clap to check a hall", category: "science", text: "Explain why people clap once to check how a hall sounds before a function. Tell me what the echo tells them about the walls and size, and how organisers in [a marriage hall] use this simple test." },
  { id: "science-81", title: "How a siren sound reaches far", category: "science", text: "Explain how an ambulance siren reaches far and warns people on the road. Tell me why its sound rises and falls, how it cuts through traffic noise, and what drivers should do when they hear it in [your city]." },
  { id: "science-82", title: "Why a glass breaks with high sound", category: "science", text: "Explain in simple words why a very high, loud sound can crack a thin glass. Tell me how matching vibrations shake the glass, why only some glasses break, and why this does not happen with [a normal voice]." },
  { id: "science-83", title: "How bats find their way in darkness", category: "science", text: "Explain how bats find their way and catch insects in complete darkness. Tell me how they send out sounds and listen for echoes, what the echo tells them, and why they do not need light in [a dark cave]." },
  { id: "science-84", title: "Why a fan hums when it runs", category: "science", text: "Explain why a ceiling fan sometimes hums or makes a buzzing sound when it runs. Tell me what causes the hum, why it gets louder at high speed, and when a family in [your home] should call an electrician." },
  { id: "science-85", title: "How a school bell sound spreads", category: "science", text: "Explain how the sound of a school bell reaches every classroom in a school. Tell me how sound travels through air and corridors, why it is louder near the bell, and how a school in [your town] chooses its bell." },
  { id: "science-86", title: "Why a moving car seems faster", category: "science", text: "Explain why a car looks faster when it passes close to us than when it is far away. Tell me how distance changes what our eyes see, why a train seems slow from far, and how this affects crossing [a road]." },
  { id: "science-87", title: "How speed is measured simply", category: "science", text: "Explain in simple words what speed means and how to measure it. Tell me how to find the speed of a bicycle using distance and time, and work out one example for a ride from [your home] to [your school]." },
  { id: "science-88", title: "Why a ball rolls downhill", category: "science", text: "Explain why a ball rolls down a slope but stays still on flat ground. Tell me how a slope gives the ball a push, why a steeper slope makes it faster, and how children see this on [a playground slide]." },
  { id: "science-89", title: "How a bicycle stays balanced", category: "science", text: "Explain in simple words how a moving bicycle stays balanced. Tell me how the turning wheels help, why it is hard to balance when still, and what a beginner in [your town] should practise first." },
  { id: "science-90", title: "Why we lean forward when running", category: "science", text: "Explain why runners lean forward when they start a race. Tell me how leaning helps them push off the ground, why it keeps them balanced, and what a school athlete in [your town] should remember at the start." },
  { id: "science-91", title: "How a swing moves back and forth", category: "science", text: "Explain how a swing moves back and forth without a motor. Tell me how pushing at the right time adds energy, why the swing slows down, and how a child in [a park] can keep swinging for longer." },
  { id: "science-92", title: "Why a car needs brakes", category: "science", text: "Explain why a moving car needs brakes to stop safely. Tell me how brakes turn motion into heat through friction, why a fast car needs more distance to stop, and how drivers on [a wet road] should brake." },
  { id: "science-93", title: "How a train moves so fast", category: "science", text: "Explain how a train moves so fast and stays on its tracks. Tell me what the engine does, why steel wheels on steel rails roll smoothly, and how a fast train in [India] keeps passengers safe and comfortable." },
  { id: "science-94", title: "Why we feel a jerk in a bus", category: "science", text: "Explain why we feel a jerk when a bus suddenly starts or stops. Tell me how our body tries to stay in its old state of motion, why holding a rail helps, and how passengers in [a city bus] can stay safe." },
  { id: "science-95", title: "How a rocket leaves the ground", category: "science", text: "Explain in simple words how a rocket lifts off the ground. Tell me how hot gases push down and lift the rocket up, why it needs so much fuel, and how Indian rockets carry satellites from [Sriharikota]." },
  { id: "science-96", title: "Why a kite flies in wind", category: "science", text: "Explain why a kite flies when the wind blows. Tell me how wind pushes on the kite surface, why the string holds it steady, and what makes a kite in [your town] fly high on a windy evening." },
  { id: "science-97", title: "How a lift moves up and down", category: "science", text: "Explain how a lift moves up and down in a building. Tell me what the motor, cables and counterweight do, why the counterweight saves energy, and how a lift in [an apartment block] stays safe if power fails." },
  { id: "science-98", title: "Why a boat floats on water", category: "science", text: "Explain why a heavy iron boat floats while a small iron nail sinks. Tell me how the shape of the boat pushes water aside, what upward push water gives, and how fishermen in [a coastal town] use this idea." },
  { id: "science-99", title: "How a plane stays in the air", category: "science", text: "Explain in simple words how a plane stays in the air. Tell me how its wings push air down and lift the plane up, why it needs speed, and how a flight from [Chennai] to [Delhi] takes off and lands." },
  { id: "science-100", title: "Why we slip on a wet floor", category: "science", text: "Explain why we slip more easily on a wet floor than on a dry floor. Tell me how water reduces friction between our feet and the floor, why bathroom tiles are risky, and how to stay safe in [your home]." },
  { id: "science-101", title: "How a pulley lifts heavy loads", category: "science", text: "Explain how a pulley helps a worker lift a heavy load with less effort. Tell me how the rope and wheel change the direction of the pull, and where pulleys are used at [a construction site] near you." },
  { id: "science-102", title: "Why a cricket ball swings in air", category: "science", text: "Explain in simple words why a cricket ball swings in the air. Tell me how the shiny and rough sides push air differently, why bowlers polish one side, and how this helps a bowler in [a local match]." },
  { id: "science-103", title: "How a fan makes us feel cool", category: "science", text: "Explain how a ceiling fan makes us feel cool even though it does not cool the air. Tell me how moving air dries sweat from our skin, why it feels cooler in [a hot room], and when a fan wastes electricity." },
  { id: "science-104", title: "Why a door swings on hinges", category: "science", text: "Explain why a door swings easily on its hinges but is hard to push near the hinge. Tell me how pushing far from the hinge gives more turning power, and how this helps us open a heavy door in [your home]." },
  { id: "science-105", title: "How a seesaw balances two children", category: "science", text: "Explain how a seesaw balances two children of different weights. Tell me why the heavier child must sit closer to the middle, how distance changes the balance, and how children in [a school playground] can balance it." },
  { id: "science-106", title: "Why a rolling ball slows down", category: "science", text: "Explain why a ball rolling on the ground slowly stops. Tell me how friction between the ball and the ground takes away its motion, why it rolls farther on a smooth floor, and how this works on [a cricket ground]." },
  { id: "science-107", title: "How a car turns a corner safely", category: "science", text: "Explain how a car turns a corner without skidding. Tell me how friction between tyres and the road holds the car, why speed matters on a bend, and what drivers should do on [a sharp turn]." },
  { id: "science-108", title: "Why we wear seat belts in cars", category: "science", text: "Explain why wearing a seat belt keeps us safe in a sudden stop. Tell me how our body keeps moving forward, how the belt spreads the force, and why every passenger in [a car] must wear one." },
  { id: "science-109", title: "How a clock pendulum keeps time", category: "science", text: "Explain how the swinging pendulum in an old clock keeps time. Tell me why each swing takes the same time, how the length of the pendulum changes the speed, and how clock makers in [your town] set it right." },
  { id: "science-110", title: "Why a paper plane glides far", category: "science", text: "Explain why a well-folded paper plane glides far through the air. Tell me how its wings give lift, why a sharp nose helps, and how a student can fold a plane that flies across [a classroom]." },
  { id: "science-111", title: "How a bicycle brake stops wheels", category: "science", text: "Explain how a bicycle brake stops the wheels. Tell me how squeezing the lever presses pads against the rim, how friction slows the wheel, and why wet brakes in [the rain] work less well." },
  { id: "science-112", title: "Why a lift feels heavier going up", category: "science", text: "Explain why we feel heavier when a lift starts going up and lighter when it starts going down. Tell me how the lift pushes on our feet, and how passengers in [an office building] feel this change." },
  { id: "science-113", title: "How a merry-go-round spins safely", category: "science", text: "Explain how a merry-go-round spins children around safely. Tell me what force pulls them towards the centre, why holding the bar matters, and how a fair in [your town] keeps the ride speed safe." },
  { id: "science-114", title: "Why a football curves in air", category: "science", text: "Explain why a football curves in the air when kicked with spin. Tell me how spinning pushes air differently on each side, why the ball bends, and how players in [a school match] use this to score goals." },
  { id: "science-115", title: "How a boat oar pushes water back", category: "science", text: "Explain how rowing a boat works. Tell me how the oar pushes water backwards and the water pushes the boat forwards, why two oars balance the boat, and how fishermen in [a river town] row together." },
  { id: "science-116", title: "What electricity is in simple words", category: "science", text: "Explain what electricity is in very simple words for a beginner. Tell me how tiny charged particles move through a wire, what a battery does, and how electricity reaches homes in [your town] from a power station." },
  { id: "science-117", title: "How a battery powers a torch", category: "science", text: "Explain how a battery powers a torch. Tell me how the battery pushes electric current through the bulb, why the bulb glows, and what happens when the battery in [your torch] runs out of charge." },
  { id: "science-118", title: "Why we use switches at home", category: "science", text: "Explain why every light and fan at home has a switch. Tell me how a switch opens or closes the electric path, why the light goes off when the path breaks, and how a switch in [your room] works." },
  { id: "science-119", title: "How a fuse protects our home", category: "science", text: "Explain how a fuse protects our home from too much electric current. Tell me how the thin wire inside melts when current is too high, why the power stops, and when a family in [your home] should call an electrician." },
  { id: "science-120", title: "Why a bulb glows when switched on", category: "science", text: "Explain why an electric bulb glows when we switch it on. Tell me how current heats the thin wire inside, why the wire glows without burning, and how an LED bulb in [your home] gives light differently." },
  { id: "science-121", title: "How a fan motor spins blades", category: "science", text: "Explain how the motor inside a ceiling fan spins its blades. Tell me how electricity makes a magnet turn inside the motor, why the blades push air down, and how a fan in [your bedroom] gives cool air." },
  { id: "science-122", title: "Why metal wires carry current", category: "science", text: "Explain why copper wires carry electric current so well. Tell me how free particles inside metal move easily, why plastic covers the wire, and how electricians in [your town] choose safe wires for homes." },
  { id: "science-123", title: "How a circuit is completed", category: "science", text: "Explain what a complete electric circuit is, using a battery, a wire and a bulb. Tell me why the bulb stays dark when the wire is broken, and how a student can show this with [a simple torch battery]." },
  { id: "science-124", title: "Why we should not touch wet switches", category: "science", text: "Explain why we must never touch a switch or plug with wet hands. Tell me how water helps electricity pass through our body, what harm it can do, and what safe habit every family in [your home] should follow." },
  { id: "science-125", title: "How a refrigerator uses electricity", category: "science", text: "Explain how a refrigerator uses electricity to keep food cold. Tell me how the motor moves a cooling liquid around, why the back feels warm, and how to save power with a fridge in [your kitchen]." },
  { id: "science-126", title: "Why LED bulbs save electricity", category: "science", text: "Explain why an LED bulb uses less electricity than an old bulb. Tell me how it makes light without much heat, why it lasts longer, and how much a family in [your home] can save by changing five bulbs." },
  { id: "science-127", title: "How a mobile phone charges", category: "science", text: "Explain how a mobile phone charges when we plug it in. Tell me how the charger changes wall electricity into a safe low current, why the phone gets warm, and how to charge a phone safely in [your home]." },
  { id: "science-128", title: "Why birds sit safely on wires", category: "science", text: "Explain why a bird can sit safely on a high electric wire. Tell me how current needs two points to flow through a body, why the bird is safe on one wire, and why humans must never touch [a live wire]." },
  { id: "science-129", title: "How an electric iron heats up", category: "science", text: "Explain how an electric iron heats up to press clothes. Tell me how current heats a coil inside, why the metal base spreads the heat, and how to use an iron safely at [home] without burning clothes." },
  { id: "science-130", title: "Why a fan has different speeds", category: "science", text: "Explain why a ceiling fan has slow, medium and fast speeds. Tell me how the regulator changes the current to the motor, why slow speed uses less power, and how to choose the right speed in [summer]." },
  { id: "science-131", title: "How a doorbell rings with electricity", category: "science", text: "Explain how an electric doorbell rings when a visitor presses the button. Tell me how the button completes a circuit, what makes the bell sound, and why a doorbell in [your home] stops working sometimes." },
  { id: "science-132", title: "Why we use earthing at home", category: "science", text: "Explain why houses have earthing for electric safety. Tell me how a wire carries extra current safely into the ground, why it protects us from shocks, and how an electrician in [your town] checks earthing." },
  { id: "science-133", title: "How a washing machine spins clothes", category: "science", text: "Explain how a washing machine uses electricity to wash and spin clothes. Tell me how the motor turns the drum, why fast spinning removes water, and how to save water and power with [your machine]." },
  { id: "science-134", title: "Why a short circuit causes fire", category: "science", text: "Explain what a short circuit is and why it can cause a fire. Tell me how two bare wires touching let too much current flow, why the wires heat up, and how families in [your area] can prevent it." },
  { id: "science-135", title: "How a solar panel makes electricity", category: "science", text: "Explain how a solar panel on a roof makes electricity from sunlight. Tell me how sunlight pushes particles inside the panel, why it works best in bright sun, and how homes in [your town] use solar power." },
  { id: "science-136", title: "Why a mixer grinder needs a motor", category: "science", text: "Explain how a mixer grinder uses a motor to grind food. Tell me how electricity spins the blades very fast, why the jar must be locked, and how to use a mixer safely in [your kitchen]." },
  { id: "science-137", title: "How a street light turns on itself", category: "science", text: "Explain how some street lights turn on by themselves in the evening. Tell me how a light sensor sees darkness, why the light switches on without a person, and how this saves power on [a road near you]." },
  { id: "science-138", title: "Why a battery gets hot while charging", category: "science", text: "Explain why a phone battery gets warm while charging. Tell me how charging moves energy into the battery, why some heat is normal, and when a hot battery in [your phone] means we should stop using it." },
  { id: "science-139", title: "How an inverter gives power backup", category: "science", text: "Explain how a home inverter gives power during a power cut. Tell me how it stores electricity in a battery, how it changes it back for fans and lights, and how long an inverter in [your home] can run." },
  { id: "science-140", title: "Why we use different plugs for appliances", category: "science", text: "Explain why a fridge plug is bigger than a phone charger plug. Tell me how big appliances need more current, why thin wires would overheat, and how to choose the right socket in [your kitchen]." },
  { id: "science-141", title: "How a tubelight starts glowing", category: "science", text: "Explain how a tubelight starts glowing when we switch it on. Tell me what the starter and the gas inside do, why it flickers before glowing, and how a tubelight in [a classroom] lights a whole room." },
  { id: "science-142", title: "Why electric shocks are dangerous", category: "science", text: "Explain why an electric shock is dangerous for the human body. Tell me how current disturbs the heart and muscles, why we must switch off power first, and what to do if someone in [your home] gets a shock." },
  { id: "science-143", title: "How a heater warms a room", category: "science", text: "Explain how a room heater warms the air in winter. Tell me how current heats a coil, why the warm air rises and spreads, and how to use a heater safely in [a cold hill town]." },
  { id: "science-144", title: "Why power cuts happen in summer", category: "science", text: "Explain why power cuts happen more often in hot summer months. Tell me how many fans, coolers and air conditioners overload the lines, why transformers trip, and how people in [your city] can cope with cuts." },
  { id: "science-145", title: "How a TV remote uses invisible light", category: "science", text: "Explain how a TV remote changes channels without a wire. Tell me how it sends invisible light signals to the TV, why we must point it at the set, and what to do when a remote in [your home] stops working." },
  { id: "science-146", title: "What a magnet is in simple words", category: "science", text: "Explain what a magnet is in very simple words for a beginner. Tell me how it pulls iron things towards itself, what its two ends are called, and where we see magnets in [your home] every day." },
  { id: "science-147", title: "Why magnets attract iron only", category: "science", text: "Explain why a magnet pulls an iron nail but not a wooden stick or a plastic bottle. Tell me which materials a magnet attracts, why iron is special, and how to test objects in [your kitchen] with a magnet." },
  { id: "science-148", title: "How a compass points north", category: "science", text: "Explain how a compass needle always points north. Tell me how the earth acts like a giant magnet, why the needle turns, and how a traveller in [a forest] can use a compass to find the way." },
  { id: "science-149", title: "Why like poles of magnets repel", category: "science", text: "Explain why two north poles of magnets push each other away. Tell me what happens when north meets south, how to feel the push with two magnets, and why this rule matters in [a fridge magnet]." },
  { id: "science-150", title: "How a magnet holds notes on fridge", category: "science", text: "Explain how a small magnet holds a paper note on a fridge door. Tell me how the magnet pulls through the paper to the steel door, why it falls when the paper is thick, and how families in [your home] use this." },
  { id: "science-151", title: "Why a magnet loses its power", category: "science", text: "Explain why a magnet can lose its power over time. Tell me how dropping it, heating it or hitting it hard weakens it, and how to store magnets safely in [a school science room]." },
  { id: "science-152", title: "How magnets are used in a door", category: "science", text: "Explain how a magnet keeps a cupboard door closed. Tell me where the magnet and the metal plate sit, why the door clicks shut, and how a carpenter in [your town] fits a magnetic catch." },
  { id: "science-153", title: "Why earth is like a magnet", category: "science", text: "Explain why scientists say the earth acts like a huge magnet. Tell me what is inside the earth that makes this happen, how it protects us, and how birds in [your area] use it to find their way." },
  { id: "science-154", title: "How a magnetic train floats above track", category: "science", text: "Explain in simple words how a magnetic train floats above its track. Tell me how magnets push the train up and pull it forward, why there is no friction, and how this makes the train in [a fast city] so smooth." },
  { id: "science-155", title: "Why magnets stick to a steel almirah", category: "science", text: "Explain why a magnet sticks to a steel almirah but falls off a wooden door. Tell me how steel contains iron, why wood has nothing for a magnet to pull, and how to check metals at [home] with a magnet." },
  { id: "science-156", title: "How a magnet separates iron filings", category: "science", text: "Explain how a magnet can separate iron filings from sand. Tell me how the magnet pulls only the iron pieces, why the sand stays behind, and where workers use this idea in [a scrap shop]." },
  { id: "science-157", title: "Why a horseshoe magnet has two ends", category: "science", text: "Explain why a horseshoe magnet is bent into a U shape. Tell me how both ends sit close together, why this makes it stronger, and how teachers in [a school] use it to lift iron nails." },
  { id: "science-158", title: "How magnets help in a speaker", category: "science", text: "Explain how a magnet inside a speaker helps make sound. Tell me how electricity and the magnet move a coil, why the cone vibrates, and how this makes music loud at [a school function]." },
  { id: "science-159", title: "Why a magnet cannot attract through thick wood", category: "science", text: "Explain why a magnet pulls weakly through a thick wooden board. Tell me how distance weakens the pull, why a thin paper does not block it, and how to show this to a child using [a fridge magnet]." },
  { id: "science-160", title: "How a magnetic lock keeps a gate shut", category: "science", text: "Explain how a magnetic lock keeps a gate or a shop shutter shut. Tell me how an electric magnet holds the metal plate, why it opens when power stops, and where shops in [your town] use such locks." },
  { id: "science-161", title: "Why compass needles wobble near iron", category: "science", text: "Explain why a compass needle wobbles when we hold it near an iron gate. Tell me how nearby iron pulls the needle away from north, why this confuses travellers, and how to use a compass away from [iron objects]." },
  { id: "science-162", title: "How magnets are made in a factory", category: "science", text: "Explain in simple words how a strong magnet is made in a factory. Tell me how a piece of steel is rubbed or charged with electricity, why it keeps its power, and how workers in [a factory] test each magnet." },
  { id: "science-163", title: "Why a magnet lifts a needle", category: "science", text: "Explain why a magnet can lift a sewing needle from a table. Tell me how the pull of the magnet is stronger than the weight of the needle, why it drops when we pull it away, and how tailors in [your town] use this." },
  { id: "science-164", title: "How a magnetic strip stores card data", category: "science", text: "Explain in simple words how the dark strip on a bank card stores data. Tell me how tiny magnetic parts hold information, why a strong magnet can damage it, and how to keep a card safe in [your wallet]." },
  { id: "science-165", title: "Why magnets are used in toys", category: "science", text: "Explain why many children's toys use magnets. Tell me how magnets let parts join and pull apart safely, what makes a magnetic building toy fun, and what parents in [your home] should check before buying one." },
  { id: "science-166", title: "How a crane lifts scrap iron", category: "science", text: "Explain how a big crane with an electric magnet lifts heavy scrap iron. Tell me how switching on the current makes it magnetic, why the iron drops when current stops, and how scrap yards in [your city] use this." },
  { id: "science-167", title: "Why two magnets snap together fast", category: "science", text: "Explain why two magnets snap together quickly when they get close. Tell me how the pull grows stronger as the gap shrinks, why fingers can get pinched, and how to handle strong magnets safely in [a classroom]." },
  { id: "science-168", title: "How a magnet finds north without a compass", category: "science", text: "Explain how a bar magnet hung by a thread points north and south. Tell me how to hang it so it turns freely, why it settles in one direction, and how a student can try this with [a magnet and thread]." },
  { id: "science-169", title: "Why a magnet does not work on gold", category: "science", text: "Explain why a magnet does not attract a gold chain or a silver coin. Tell me which metals magnets ignore, why jewellers use this test, and how a buyer in [a jewellery shop] can spot fake gold simply." },
  { id: "science-170", title: "How magnets keep a purse closed", category: "science", text: "Explain how a small magnet keeps a handbag or purse closed. Tell me where the two magnetic parts sit, why the flap clicks shut, and how a tailor in [your town] fixes a purse when the magnet weakens." },
  { id: "science-171", title: "Why a feather falls slowly down", category: "science", text: "Explain in simple words why a feather falls slowly while a stone drops fast. Tell me about air pushing against light things, what happens if we drop both in [a vacuum jar], and a simple activity with a paper and a coin." },
  { id: "science-172", title: "How gravity keeps us on earth", category: "science", text: "Explain how gravity keeps us standing on the earth and stops us floating into the sky. Tell me how the earth pulls everything towards its centre, and why we do not feel this pull in [daily life]." },
  { id: "science-173", title: "Why a feather falls slowly", category: "science", text: "Explain why a feather falls slowly while a stone falls fast. Tell me how air pushes against the feather, why a stone cuts through air easily, and what would happen if both fell in [a place with no air]." },
  { id: "science-174", title: "Why the moon does not fall down", category: "science", text: "Explain why the moon does not fall to the earth even though gravity pulls it. Tell me how the moon keeps moving forward while falling, why this makes it circle the earth, and how this helps people in [your town]." },
  { id: "science-175", title: "How weight changes on the moon", category: "science", text: "Explain why a person weighs less on the moon than on the earth. Tell me how the moon pulls more weakly, why the person stays the same size, and how much a [70 kg] person would weigh there." },
  { id: "science-176", title: "Why water falls from a tap", category: "science", text: "Explain why water falls down from a tap instead of rising up. Tell me how gravity pulls the water down, why it flows faster from a high tank, and how homes in [your town] store water on rooftops." },
  { id: "science-177", title: "How a parachute slows a fall", category: "science", text: "Explain how a parachute slows a person falling from the sky. Tell me how the wide cloth catches air, why the fall becomes slow and safe, and how soldiers in [India] train with parachutes before jumping." },
  { id: "science-178", title: "Why a ball bounces back up", category: "science", text: "Explain why a ball bounces back up after hitting the ground. Tell me how the ball squashes a little, how it pushes back, and why a ball on [a hard floor] bounces higher than on soft sand." },
  { id: "science-179", title: "How gravity holds water in a dam", category: "science", text: "Explain how gravity helps a dam store water and make electricity. Tell me how water stored high up flows down with force, why this turns turbines, and how a dam in [your state] supplies power to homes." },
  { id: "science-180", title: "Why we feel weightless in a falling lift", category: "science", text: "Explain why people feel weightless for a moment in a lift that drops quickly. Tell me how the floor stops pushing on their feet, why their stomach feels strange, and how a lift in [a tall building] avoids this." },
  { id: "science-181", title: "How a dropped stone gains speed", category: "science", text: "Explain why a stone dropped from a height falls faster and faster. Tell me how gravity keeps pulling it, why it hits the ground hard, and how this idea helps builders keep workers safe at [a construction site]." },
  { id: "science-182", title: "Why rain falls down not up", category: "science", text: "Explain why rain falls down from clouds instead of rising into the sky. Tell me how gravity pulls each drop, why wind can slant the rain, and how farmers in [your village] wait for rain in summer." },
  { id: "science-183", title: "How a see-saw uses gravity to move", category: "science", text: "Explain how gravity helps a see-saw move up and down in a playground. Tell me how the heavier side goes down, why pushing with feet adds motion, and how children in [a school playground] play safely on it." },
  { id: "science-184", title: "Why a ripe mango falls from tree", category: "science", text: "Explain why a ripe mango falls from its tree while an unripe one stays. Tell me how the stalk weakens as the fruit ripens, why gravity then pulls it down, and how farmers in [your area] pick mangoes in season." },
  { id: "science-185", title: "How gravity keeps the sea in place", category: "science", text: "Explain how gravity keeps the sea water on the earth instead of spilling into space. Tell me how the earth pulls the water down, why waves still move, and how fishermen in [a coastal town] read the tides." },
  { id: "science-186", title: "How a ceiling fan moves air", category: "science", text: "Explain how a ceiling fan moves air around a room. Tell me how its tilted blades push air downwards, why the air feels cool on our skin, and how a fan in [a classroom] helps thirty students feel comfortable." },
  { id: "science-187", title: "Why a fan has three blades", category: "science", text: "Explain why most ceiling fans have three blades. Tell me how three blades balance the fan, why more blades would use more power, and how a fan maker in [India] chooses the blade shape and size." },
  { id: "science-188", title: "How a table fan gives breeze", category: "science", text: "Explain how a table fan gives a cool breeze on a hot day. Tell me how its small blades spin fast, why it turns from side to side, and how a student in [your home] can place it for best cooling." },
  { id: "science-189", title: "Why a fan wobbles when it runs", category: "science", text: "Explain why a ceiling fan wobbles when it runs at high speed. Tell me how a loose rod or bent blade unbalances it, why it makes noise, and when a family in [your home] should get it fixed." },
  { id: "science-190", title: "How a fan regulator controls speed", category: "science", text: "Explain how a fan regulator on the wall controls the fan speed. Tell me how it changes the electric current to the motor, why low speed saves power, and how to use it wisely in [your bedroom]." },
  { id: "science-191", title: "Why a fan does not cool a room", category: "science", text: "Explain why a ceiling fan does not actually cool the air in a room. Tell me how it only moves air over our skin, why an empty room with a fan on wastes power, and how people in [your town] should use fans." },
  { id: "science-192", title: "How an exhaust fan removes smoke", category: "science", text: "Explain how an exhaust fan removes smoke and steam from a kitchen. Tell me how its blades push stale air outside, why fresh air comes in, and how a family in [your home] can keep the kitchen fresh." },
  { id: "science-193", title: "Why a fan makes a humming noise", category: "science", text: "Explain why a ceiling fan makes a humming noise sometimes. Tell me how a loose screw, dry bearing or old capacitor causes the hum, and what a family in [your home] should check before calling an electrician." },
  { id: "science-194", title: "How a cooler differs from a fan", category: "science", text: "Explain how an air cooler differs from a ceiling fan. Tell me how a cooler adds moist cool air, why it needs water and ventilation, and when a family in [a dry town] should choose a cooler over a fan." },
  { id: "science-195", title: "Why fan blades are tilted", category: "science", text: "Explain why ceiling fan blades are tilted and not flat. Tell me how the tilt scoops air and pushes it down, what happens if blades are flat, and how a shopkeeper in [your town] explains this to buyers." },
  { id: "science-196", title: "How a lift knows which floor", category: "science", text: "Explain how a lift knows which floor to stop at. Tell me how buttons, sensors and a control box work together, why the lift slows near the floor, and how passengers in [an apartment block] use it safely." },
  { id: "science-197", title: "Why a lift has a counterweight", category: "science", text: "Explain why a lift has a heavy counterweight on the other side of its cable. Tell me how it balances the lift car, why the motor uses less power, and how a lift in [a tall building] moves smoothly." },
  { id: "science-198", title: "How a lift door opens safely", category: "science", text: "Explain how a lift door opens and closes safely. Tell me how sensors stop the door when a hand is in the way, why the door waits a few seconds, and what children in [an apartment block] must never do near it." },
  { id: "science-199", title: "Why lifts stop during power cuts", category: "science", text: "Explain why a lift stops when the power goes off. Tell me how brakes hold it in place, why it does not fall, and what passengers in [your building] should do calmly if the lift stops." },
  { id: "science-200", title: "How an escalator moves people up", category: "science", text: "Explain how an escalator moves people up and down in a mall. Tell me how moving steps on a chain carry shoppers, why the handrail moves at the same speed, and how to ride one safely in [a shopping mall]." },
  { id: "science-201", title: "Why a lift cable is so strong", category: "science", text: "Explain why the steel cable of a lift is so strong. Tell me how many steel wires are twisted together, why several cables share the load, and how engineers in [your city] test lift cables for safety." },
  { id: "science-202", title: "How a lift button calls the car", category: "science", text: "Explain how pressing a lift button on any floor calls the lift car. Tell me how the signal reaches the control box, why the nearest lift comes first, and how people in [an office building] share lifts politely." },
  { id: "science-203", title: "Why we should not overload a lift", category: "science", text: "Explain why we must never overload a lift with too many people. Tell me how the weight limit protects the motor and cable, why the alarm rings, and how residents in [an apartment block] should follow the limit." },
  { id: "science-204", title: "How a hospital lift differs from home lift", category: "science", text: "Explain how a hospital lift differs from a lift in a home. Tell me why it is bigger, how it carries a stretcher, why it moves gently, and how staff in [a hospital] use it during an emergency." },
  { id: "science-205", title: "Why a lift moves smoothly not jerky", category: "science", text: "Explain why a modern lift starts and stops smoothly instead of jerking. Tell me how the motor speeds up and slows down gently, why this comforts passengers, and how a lift in [a hotel] feels so smooth." },
  { id: "science-206", title: "How a fan and a lift use motors", category: "science", text: "Compare how a ceiling fan motor and a lift motor use electricity. Tell me how each motor turns electric energy into motion, why the lift motor is much bigger, and how both help people in [a tall building]." },
  { id: "science-207", title: "Why a pedestal fan can be moved", category: "science", text: "Explain why a pedestal fan can be moved from room to room while a ceiling fan cannot. Tell me how its stand and base work, why it plugs into any socket, and how a family in [your home] uses it in summer." },
  { id: "science-208", title: "How a lift alarm helps trapped people", category: "science", text: "Explain how the alarm button in a lift helps people trapped inside. Tell me how it alerts the guard or control room, why passengers should stay calm, and how a building in [your area] keeps its lift alarm working." },
  { id: "science-209", title: "Why a fan spins faster with clean blades", category: "science", text: "Explain why a ceiling fan spins better when its blades are clean. Tell me how dust adds weight and drag, why cleaning improves the breeze, and how often a family in [your home] should clean fan blades." },
  { id: "science-210", title: "How a goods lift carries heavy loads", category: "science", text: "Explain how a goods lift carries heavy loads in a shop or warehouse. Tell me how its strong motor, wide doors and flat floor help, why it moves slowly, and how workers in [a market] load it safely." },
  { id: "science-211", title: "Why a lift mirror makes it feel bigger", category: "science", text: "Explain why a mirror inside a lift makes the small cabin feel bigger. Tell me how the mirror reflects light and space, why it helps passengers see the door, and how a lift in [a hotel] uses this trick." },
  { id: "science-212", title: "How a fan helps dry washed clothes", category: "science", text: "Explain how a ceiling fan helps washed clothes dry faster indoors. Tell me how moving air carries moisture away, why it works best with a window open, and how families in [your home] dry clothes during rain." },
  { id: "science-213", title: "Why lifts have emergency lights inside", category: "science", text: "Explain why lifts have emergency lights inside the cabin. Tell me how a small battery keeps the light on during a power cut, why it calms passengers, and how a building in [your town] tests these lights." },
  { id: "science-214", title: "How a fan speed changes the breeze", category: "science", text: "Explain how changing a fan speed changes the breeze we feel. Tell me how faster blades push more air, why high speed is noisy, and how to pick a comfortable speed on [a warm night]." },
  { id: "science-215", title: "Why a lift needs regular servicing", category: "science", text: "Explain why a lift needs regular servicing by a trained worker. Tell me what is checked in the motor, cables and brakes, why small faults grow dangerous, and how often a building in [your area] should service its lift." },
  { id: "science-216", title: "How a tower fan gives cool air", category: "science", text: "Explain how a tall tower fan gives cool air in a small room. Tell me how its long vent spreads air widely, why it takes little floor space, and how a student in [a hostel room] can use it well." },
  { id: "science-217", title: "Why children must not play in lifts", category: "science", text: "Explain why children must never play with lift buttons or doors. Tell me how pressing buttons can send the lift to many floors, why doors can trap fingers, and how parents in [an apartment block] can teach lift safety." },
  { id: "science-218", title: "How a fan motor starts spinning", category: "science", text: "Explain how a ceiling fan motor starts spinning when we switch it on. Tell me how electricity creates a turning force, why a small capacitor helps it start, and what happens when the capacitor in [your fan] fails." },
  { id: "science-219", title: "Why a lift floor matches the landing", category: "science", text: "Explain why a lift floor stops level with the floor outside. Tell me how sensors guide the car to the exact height, why a gap is dangerous, and how a lift in [an office building] keeps passengers safe." },
  { id: "science-220", title: "How a fan cools a crowded classroom", category: "science", text: "Explain how ceiling fans cool a crowded classroom on a hot day. Tell me how several fans move air over many students, why open windows help, and how a school in [your town] places fans for best comfort." },
  { id: "science-221", title: "Why a lift uses steel ropes not chains", category: "science", text: "Explain why lifts use strong steel ropes instead of chains. Tell me how ropes bend smoothly over pulleys, why they are quieter, and how engineers in [your city] choose ropes that can carry many people safely." },
  { id: "science-222", title: "How a hand fan moves air too", category: "science", text: "Explain how a simple hand fan moves air and cools us. Tell me how waving it pushes air over our skin, why it helps when power fails, and how people in [your village] use hand fans during summer power cuts." },
  { id: "science-223", title: "Why a lift beeps when it arrives", category: "science", text: "Explain why a lift beeps when it arrives at our floor. Tell me how the sound tells waiting passengers the door will open, why it helps blind people, and how a lift in [a hospital] uses sound and light together." },
  { id: "science-224", title: "How a fan and a cooler work together", category: "science", text: "Explain how a ceiling fan and an air cooler can work together in a hot room. Tell me how the cooler makes cool air and the fan spreads it, and how a family in [your home] can save power using both." },
  { id: "science-225", title: "Why lifts are better than stairs daily", category: "science", text: "Explain why lifts help old people, patients and heavy loads more than stairs. Tell me how a lift saves energy and time, why stairs still matter for health, and how people in [a tall building] choose between them." },
  { id: "science-226", title: "Why baking soda makes cakes rise", category: "science", text: "Explain in simple words why baking soda makes [cake / idli batter] rise. Describe the gas it releases when it meets heat and acid, why the batter must be baked soon after mixing, and what happens if I add too much." },
  { id: "science-227", title: "Baking soda and vinegar fizz explained", category: "science", text: "Explain in simple words why baking soda and vinegar fizz when they are mixed. Name the gas that forms, say whether the mixture cleans better after the fizz stops, and give one safe kitchen use for [a sink / a steel vessel]." },
  { id: "science-228", title: "Baking soda for cleaning the fridge", category: "science", text: "Explain how baking soda helps remove smells from a fridge in [my home]. Describe how to place an open bowl inside, how long to leave it, when to replace it, and why it works on smells without adding a strong fragrance." },
  { id: "science-229", title: "Baking soda versus baking powder difference", category: "science", text: "Explain the difference between baking soda and baking powder for a beginner cook in [your city]. Say when each one works best, whether I can swap one for the other, and what happens to [a cake / a dosa batter] if I choose wrongly." },
  { id: "science-230", title: "Why baking soda removes tea stains", category: "science", text: "Explain in simple words why baking soda helps remove tea and coffee stains from [a steel cup / a flask]. Describe the gentle scrubbing action, how to make a paste with water, and why I should rinse well after cleaning." },
  { id: "science-231", title: "Baking soda in idli and dhokla batter", category: "science", text: "Explain why a pinch of baking soda makes idli and dhokla soft and spongy. Describe how it works with sour curd or lemon juice, how much is enough for [4 people], and what happens if the batter rests too long." },
  { id: "science-232", title: "Baking soda for smelly shoes and cupboards", category: "science", text: "Explain how baking soda reduces smells in shoes and cupboards in a humid home in [your city]. Tell me how to use it safely, how long to leave it, and when to throw it away and use a fresh pack." },
  { id: "science-233", title: "Why baking soda water soothes a burn", category: "science", text: "Explain in simple words what baking soda does when it is mixed with water for [a mild kitchen burn / an insect bite]. Give general information only, explain when home care is not enough, and say when to see a doctor quickly." },
  { id: "science-234", title: "Baking soda and lemon for cleaning steel", category: "science", text: "Explain why baking soda and lemon juice help clean steel vessels in [my kitchen]. Describe the mild acid and gentle scrubbing action, how to apply the paste, and why I should avoid using it on [aluminium / non-stick pans]." },
  { id: "science-235", title: "How much baking soda is safe", category: "science", text: "Explain how much baking soda is normally used in cooking for [a cake / a batch of pakoras]. Say why a small pinch is enough, what taste too much leaves behind, and why I should follow the recipe amount instead of adding extra." },
  { id: "science-236", title: "Baking soda for cleaning a microwave", category: "science", text: "Explain how baking soda helps clean food smells and stains inside a microwave in [my home]. Describe a simple method using warm water, how long to leave it, and how to wipe the inside safely after the power is off." },
  { id: "science-237", title: "Baking soda and curd in cooking", category: "science", text: "Explain why baking soda works well with sour curd in Indian cooking. Describe the reaction between the soda and the acid in curd, why it makes [dhokla / handvo] light, and how to mix it just before cooking." },
  { id: "science-238", title: "Baking soda for washing vegetables safely", category: "science", text: "Explain whether baking soda water helps wash vegetables like [tomatoes / spinach] in [your city]. Describe a simple rinse method, how long to soak them, and why clean running water is still the most important step." },
  { id: "science-239", title: "Why baking soda stops onion smells", category: "science", text: "Explain in simple words why rubbing baking soda on [my hands] helps reduce onion and garlic smells. Describe how it works on smell particles, how to use a small amount with water, and why washing with soap afterwards is still useful." },
  { id: "science-240", title: "Baking soda in water for acidity", category: "science", text: "Explain in simple words why some people mix a pinch of baking soda in water for acidity after [a heavy meal]. Give general information only, explain the risks of using it often, and say when to ask a doctor instead." },
  { id: "science-241", title: "Baking soda for cleaning burnt vessels", category: "science", text: "Explain how baking soda helps loosen burnt food from a steel vessel in [my kitchen]. Describe soaking it in warm water with soda, how long to wait, and how to scrub gently without scratching the surface." },
  { id: "science-242", title: "Baking soda and salt for cleaning", category: "science", text: "Explain what baking soda and salt do together when cleaning [a chopping board / a sink]. Describe the gentle scrubbing action, how to make the mixture, and why I should rinse the surface well with clean water afterwards." },
  { id: "science-243", title: "Why old baking soda stops working", category: "science", text: "Explain why old baking soda stops making cakes rise. Describe how it loses strength when it absorbs moisture and smells, how to test it with [vinegar / lemon juice], and how to store a new pack in [my kitchen]." },
  { id: "science-244", title: "Baking soda for cleaning a water bottle", category: "science", text: "Explain how baking soda helps clean smells from a steel water bottle used for [school / office]. Describe how to shake warm soda water inside, how long to leave it, and how to rinse and dry the bottle fully." },
  { id: "science-245", title: "Baking soda in bread and biscuits", category: "science", text: "Explain why baking soda is used in some breads and biscuits but not in others. Describe how it needs acid and heat to work, why [banana bread / cookies] suit it, and what happens when a recipe has no sour ingredient." },
  { id: "science-246", title: "Baking soda for cleaning tiles and grout", category: "science", text: "Explain how baking soda paste helps clean tiles and grout lines in [my bathroom / kitchen]. Describe how to apply it, how long to leave it, and how to scrub and rinse so the surface looks clean without harsh chemicals." },
  { id: "science-247", title: "Baking soda and vinegar for drains", category: "science", text: "Explain what really happens when baking soda and vinegar are poured into a slow drain in [my home]. Say whether the fizz clears a blockage, what it can and cannot do, and when I should call a plumber instead." },
  { id: "science-248", title: "Baking soda for fresh laundry smells", category: "science", text: "Explain how a spoon of baking soda in the wash helps clothes smell fresher in [your city]. Describe how it works on sweat smells, whether it softens water, and why it does not replace detergent for dirty clothes." },
  { id: "science-249", title: "Baking soda for cleaning a gas stove", category: "science", text: "Explain how baking soda helps clean grease from a gas stove in [my kitchen]. Describe how to make a paste, where to apply it safely, how long to leave it, and why the burners must be fully dry before use." },
  { id: "science-250", title: "Baking soda in pickles and papads", category: "science", text: "Explain why a tiny amount of baking soda is sometimes used in papads and pickles in [your region]. Describe what it does to texture and colour, why the amount must stay small, and what happens if too much is added." },
  { id: "science-251", title: "Baking soda for cleaning silver vessels", category: "science", text: "Explain how baking soda helps clean dull silver vessels and puja items in [my home]. Describe a gentle method with warm water, how to rub softly, and why harsh scrubbing can damage the shine and fine details." },
  { id: "science-252", title: "Why baking soda tastes bitter alone", category: "science", text: "Explain in simple words why baking soda tastes bitter and soapy when tasted alone in [a small spoon]. Describe its alkaline nature, why cooking acids balance it, and why a cake tastes strange when the soda is not mixed well." },
  { id: "science-253", title: "Baking soda for cleaning a dustbin", category: "science", text: "Explain how baking soda helps reduce smells in a kitchen dustbin in [my home]. Describe how to sprinkle it at the bottom, how often to repeat it, and why washing the bin with soap and water still matters most." },
  { id: "science-254", title: "Baking soda and milk in baking", category: "science", text: "Explain how baking soda works with sour milk or buttermilk in baking [a cake / muffins]. Describe the acid reaction, why the batter rises quickly, and why I should put the tray in the oven without waiting too long." },
  { id: "science-255", title: "Baking soda for cleaning a cutting board", category: "science", text: "Explain how baking soda helps clean a wooden chopping board after cutting [onion / garlic / fish]. Describe how to scrub it with soda and water, how to rinse it, and how to dry it so it does not smell or crack." },
  { id: "science-256", title: "Baking soda storage in Indian kitchens", category: "science", text: "Explain the best way to store baking soda in a hot and humid kitchen in [your city]. Describe a dry airtight container, where to keep it away from heat, and how to tell when the pack is too old to use." },
  { id: "science-257", title: "Baking soda for cleaning a kettle", category: "science", text: "Explain how baking soda helps clean a kettle with white scale inside in [your city]. Describe a simple method with warm water, how long to soak it, and how to rinse several times before boiling water again." },
  { id: "science-258", title: "Baking soda versus washing soda explained", category: "science", text: "Explain the difference between baking soda and washing soda for a beginner in [your city]. Say which one is safe for cooking, which one is only for cleaning, and why washing soda should never be added to food." },
  { id: "science-259", title: "Baking soda for cleaning a lunch box", category: "science", text: "Explain how baking soda helps remove food smells from a steel lunch box used for [school / office]. Describe soaking it in warm soda water, how long to leave it, and how to dry it fully before packing food again." },
  { id: "science-260", title: "Baking soda and honey in cooking", category: "science", text: "Explain why baking soda reacts with honey in some cakes and biscuits. Describe the mild acid in honey, how the mixture helps the batter rise, and why the cake can turn brown faster in [a hot oven]." },
  { id: "science-261", title: "Why vinegar tastes sour and sharp", category: "science", text: "Explain in simple words why vinegar tastes sour and sharp. Describe the acid it contains, how it is made from [sugarcane / grapes / apples], and why a small amount adds flavour while too much makes food unpleasant." },
  { id: "science-262", title: "Vinegar for cleaning glass windows", category: "science", text: "Explain how vinegar helps clean glass windows and mirrors in [my home]. Describe how to mix it with water, why it cuts grease and water marks, and how to wipe the glass so it dries clear without streaks." },
  { id: "science-263", title: "Vinegar in pickles and food safety", category: "science", text: "Explain why vinegar helps keep pickles safe for longer in [your region]. Describe how its acid slows down germs, why the pickle must stay covered in the liquid, and how to store the jar in a cool dry place." },
  { id: "science-264", title: "White vinegar versus apple cider vinegar", category: "science", text: "Explain the difference between white vinegar and apple cider vinegar for cooking and cleaning in [my home]. Say which one suits salads and pickles, which one suits cleaning glass, and why they should not always be swapped." },
  { id: "science-265", title: "Vinegar for removing limescale from taps", category: "science", text: "Explain how vinegar helps remove white limescale from taps and shower heads in [your city]. Describe how to soak a cloth in vinegar, how long to leave it, and why I should rinse well and avoid using it on [marble / stone]." },
  { id: "science-266", title: "Vinegar for cleaning a steel sink", category: "science", text: "Explain how vinegar helps clean water marks and dull patches from a steel sink in [my kitchen]. Describe how to wipe it with diluted vinegar, how long to leave it, and how to rinse and dry the sink for a clear shine." },
  { id: "science-267", title: "Why vinegar keeps salads fresh", category: "science", text: "Explain why a little vinegar in a salad dressing helps vegetables stay fresh for [a lunch box / a family meal]. Describe how its acid slows down germs, why the dressing should be mixed just before eating, and how much to use." },
  { id: "science-268", title: "Vinegar for cleaning a washing machine", category: "science", text: "Explain how vinegar helps clean smells and soap marks inside a washing machine in [my home]. Describe a simple empty wash method, how much vinegar to use, and why I should check the machine manual before trying it." },
  { id: "science-269", title: "Vinegar and oil in salad dressing", category: "science", text: "Explain in simple words why vinegar and oil do not mix in a salad dressing. Describe how shaking or whisking breaks the oil into tiny drops, why the mixture separates again, and how [mustard / honey] helps it stay mixed longer." },
  { id: "science-270", title: "Vinegar for removing sticker marks", category: "science", text: "Explain how vinegar helps remove sticky marks left by price labels on [a steel dabba / a glass jar]. Describe how to dab vinegar on the mark, how long to wait, and how to wipe it clean without scratching the surface." },
  { id: "science-271", title: "Vinegar in dosa and idli batter", category: "science", text: "Explain why some cooks add a few drops of vinegar to dosa or idli batter in [your region]. Describe how the acid helps the batter rise and turn crisp, how much is enough, and what happens if too much is added." },
  { id: "science-272", title: "Vinegar for cleaning a fridge shelf", category: "science", text: "Explain how diluted vinegar helps clean fridge shelves and door seals in [my home]. Describe how to wipe away food marks and smells, how long to leave it, and why I should rinse with clean water and dry fully." },
  { id: "science-273", title: "Why vinegar preserves onions and chillies", category: "science", text: "Explain why onions and green chillies kept in vinegar last longer in [my kitchen]. Describe how the acid slows down germs, why the jar must be clean and dry, and how to store it safely in the fridge." },
  { id: "science-274", title: "Vinegar for cleaning burnt milk vessels", category: "science", text: "Explain how vinegar helps loosen burnt milk from a steel vessel in [my kitchen]. Describe soaking it in warm vinegar water, how long to wait, and how to scrub gently and rinse well before using the vessel again." },
  { id: "science-275", title: "Vinegar and baking soda cleaning myth", category: "science", text: "Explain the common myth that baking soda and vinegar together make a strong cleaner. Describe what the fizz really does, why the mixture becomes mostly salty water, and when each one works better alone in [my home]." },
  { id: "science-276", title: "Vinegar for washing new clothes", category: "science", text: "Explain why some people add vinegar when washing new coloured clothes in [your city]. Describe whether it really stops colour from running, how much to use in a bucket, and why I should test one small corner first." },
  { id: "science-277", title: "Vinegar for cleaning a gas burner", category: "science", text: "Explain how vinegar helps clean grease and food marks from gas burner parts in [my kitchen]. Describe soaking the cool parts in vinegar water, how long to leave them, and why they must be fully dry before lighting the stove." },
  { id: "science-278", title: "Vinegar in Chinese and Indo-Chinese food", category: "science", text: "Explain why vinegar is important in Indo-Chinese dishes like [hakka noodles / chilli paneer]. Describe how its sour taste balances spicy and salty flavours, how much to add, and when to add it during cooking for the best taste." },
  { id: "science-279", title: "Vinegar for removing rust from tools", category: "science", text: "Explain how vinegar helps remove light rust from small tools in [my home]. Describe soaking the rusted part, how long to leave it, and how to scrub, rinse, dry and oil it so the rust does not return quickly." },
  { id: "science-280", title: "Vinegar for cleaning a kettle safely", category: "science", text: "Explain how vinegar helps remove white scale from an electric kettle in [your city]. Describe a simple method with equal parts vinegar and water, how long to boil and soak, and how to rinse several times before use." },
  { id: "science-281", title: "Why vinegar stings a small cut", category: "science", text: "Explain in simple words why vinegar stings when it touches a small cut on [my finger]. Describe how its acid irritates open skin, why it is not a medicine, and when I should wash the cut with clean water and see a doctor." },
  { id: "science-282", title: "Vinegar for cleaning a chopping board", category: "science", text: "Explain how vinegar helps clean a chopping board after cutting [raw chicken / fish] in [my kitchen]. Describe wiping it with diluted vinegar, how long to leave it, and why washing with soap and hot water is still needed." },
  { id: "science-283", title: "Vinegar for softening hard water", category: "science", text: "Explain whether vinegar can soften hard water for cleaning in [your city]. Describe how its acid reacts with minerals in the water, what it can help with, and why it does not make hard water safe to drink." },
  { id: "science-284", title: "Vinegar for cleaning a toilet stain", category: "science", text: "Explain how vinegar helps clean hard water stains in a toilet in [my home]. Describe pouring it around the stain, how long to leave it, and how to scrub safely with gloves and rinse well afterwards." },
  { id: "science-285", title: "Vinegar in raita and curd dishes", category: "science", text: "Explain why a few drops of vinegar are sometimes added to raita or curd dishes in [your region]. Describe how it adds a light sour taste, when it helps on a hot day, and why too much can split the curd." },
  { id: "science-286", title: "Vinegar for cleaning a microwave smell", category: "science", text: "Explain how a bowl of vinegar water helps remove strong food smells from a microwave in [my home]. Describe heating it for a few minutes, how the steam loosens marks, and how to wipe the inside safely afterwards." },
  { id: "science-287", title: "Vinegar and salt for cleaning copper", category: "science", text: "Explain why vinegar and salt help clean dull copper vessels in [my home]. Describe how the acid and salt remove the dark layer, how to rub gently, and how to rinse and dry the vessel so it keeps its shine." },
  { id: "science-288", title: "Vinegar storage and expiry at home", category: "science", text: "Explain how to store vinegar safely in a kitchen in [your city]. Describe keeping it in a cool dark place with the cap tight, whether it really expires, and how to tell when a bottle has gone cloudy or smells wrong." },
  { id: "science-289", title: "Vinegar for cleaning a school water bottle", category: "science", text: "Explain how diluted vinegar helps clean smells from a steel school water bottle in [your city]. Describe shaking it inside, how long to leave it, and how to rinse with clean water and dry it fully before filling again." },
  { id: "science-290", title: "Why vinegar makes red cabbage change colour", category: "science", text: "Explain in simple words why red cabbage turns pink when vinegar is added to [a salad / a pickle]. Describe how its natural colour reacts to acid, why lemon juice does the same, and what happens when baking soda is added instead." },
  { id: "science-291", title: "Why iron rusts in rainy season", category: "science", text: "Explain in simple words why iron gates and tools rust faster during the monsoon in [your city]. Describe how water and air work together on iron, why salty air near the coast makes it worse, and how paint helps protect it." },
  { id: "science-292", title: "Rust on steel vessels explained simply", category: "science", text: "Explain why some steel vessels get rust spots in [my kitchen]. Describe the difference between good steel and cheap steel, how water left on the surface starts rust, and how drying vessels quickly helps prevent it." },
  { id: "science-293", title: "How to stop a bicycle rusting", category: "science", text: "Explain how to stop a bicycle from rusting in rainy weather in [your city]. Describe wiping it dry after rain, where to apply oil, and how covering it or keeping it under a shed slows down rust on the chain and frame." },
  { id: "science-294", title: "Rust on kitchen knives and care", category: "science", text: "Explain why kitchen knives get rust spots even when they look like steel. Describe how water and food acids start rust, why I should wash and dry a knife at once, and how to store it safely in [my kitchen]." },
  { id: "science-295", title: "Why rust weakens iron over time", category: "science", text: "Explain in simple words why rust makes iron weak over time. Describe how rust flakes away and exposes fresh iron below, why a rusted [gate / rod / tool] becomes thin, and when it is no longer safe to use." },
  { id: "science-296", title: "Rust proofing iron gates at home", category: "science", text: "Explain how to protect an iron gate from rust in [your city]. Describe cleaning off old rust, applying primer and paint, how often to repaint it, and why the bottom edge near rain water needs extra care." },
  { id: "science-297", title: "Why aluminium does not rust like iron", category: "science", text: "Explain in simple words why aluminium vessels do not rust like iron. Describe the thin layer that forms on aluminium, how it protects the metal below, and why harsh scrubbing can damage that layer in [my kitchen]." },
  { id: "science-298", title: "Rust in water tanks and pipes", category: "science", text: "Explain why old iron water tanks and pipes rust in [your city]. Describe how water and air slowly eat the metal, why rusty water looks brown, and when I should ask a plumber to check the tank or pipe." },
  { id: "science-299", title: "Removing rust from a steel tawa", category: "science", text: "Explain how to remove light rust from a steel tawa in [my kitchen]. Describe scrubbing gently with [salt and lemon / baking soda], how to rinse and dry it, and how a thin layer of oil helps stop rust returning." },
  { id: "science-300", title: "Why stainless steel resists rust", category: "science", text: "Explain in simple words why stainless steel resists rust better than plain iron. Describe the special metal mixed into it, how it forms a protective layer, and why even steel can rust if it stays wet with salt water near [the sea]." },
  { id: "science-301", title: "Rust on scissors and sewing tools", category: "science", text: "Explain why scissors and sewing tools rust in a humid home in [your city]. Describe how to wipe them dry after use, where to apply a drop of oil, and how to store them in a dry box away from the bathroom." },
  { id: "science-302", title: "Why cars rust near the sea", category: "science", text: "Explain why cars rust faster in coastal cities like [Chennai / Kochi / Mumbai]. Describe how salty air speeds up rust, which parts rust first, and how regular washing and waxing help protect the body and underparts." },
  { id: "science-303", title: "Rust and tetanus safety at home", category: "science", text: "Explain in simple words why a cut from a rusty nail in [my garden] needs quick care. Give general information only, describe washing the cut with clean water, and say when to see a doctor and check whether a tetanus injection is due." },
  { id: "science-304", title: "Cleaning rust from bathroom fittings", category: "science", text: "Explain how to clean light rust marks from bathroom taps and fittings in [my home]. Describe a gentle method with [lemon and salt / vinegar], how long to leave it, and how to rinse and dry the fitting afterwards." },
  { id: "science-305", title: "Why iron nails rust in water", category: "science", text: "Explain in simple words why an iron nail left in [a glass of water] turns brown and rough. Describe how water and air react with iron, why a nail in oil stays bright, and why a nail in salty water rusts even faster." },
  { id: "science-306", title: "Rust on iron kadai and seasoning", category: "science", text: "Explain why an iron kadai rusts when it is left wet in [my kitchen]. Describe how to dry it on low heat, why a thin layer of oil protects it, and how regular use keeps the surface smooth and rust-free." },
  { id: "science-307", title: "Why copper vessels turn green", category: "science", text: "Explain in simple words why copper vessels turn green in a humid kitchen in [your city]. Describe the layer that forms when copper meets air and water, whether it is safe to cook in, and how to clean it gently." },
  { id: "science-308", title: "Galvanised iron and rust protection", category: "science", text: "Explain in simple words what galvanised iron is and why it rusts slowly. Describe the zinc coating on the surface, how it protects the iron below, and why a deep scratch can let rust start in [a gate / a bucket]." },
  { id: "science-309", title: "Rust on terrace railings and grills", category: "science", text: "Explain why terrace railings and window grills rust in [your city]. Describe how rain and sun damage old paint, how to clean and repaint the metal, and how often to check the joints and corners for rust." },
  { id: "science-310", title: "Why brass vessels lose their shine", category: "science", text: "Explain in simple words why brass vessels lose their shine in [my home]. Describe how air and water form a dull layer on the surface, how [tamarind / lemon] helps clean it, and how to dry brass after washing." },
  { id: "science-311", title: "Rust in old pressure cooker parts", category: "science", text: "Explain why old pressure cooker parts can rust in [my kitchen]. Describe which parts rust first, how to clean and dry them after washing, and when a rusted safety part should be replaced by a trained worker." },
  { id: "science-312", title: "How salt water speeds up rust", category: "science", text: "Explain in simple words why salt water makes iron rust faster than plain water. Describe how salt helps the reaction along, why tools near the sea need extra care, and how rinsing with fresh water helps in [your city]." },
  { id: "science-313", title: "Rust on keys and locks in monsoon", category: "science", text: "Explain why keys and locks rust during the monsoon in [your city]. Describe how to dry them, where to apply a drop of oil, and how keeping them away from damp walls helps them work smoothly for longer." },
  { id: "science-314", title: "Why silver turns black over time", category: "science", text: "Explain in simple words why silver vessels and jewellery turn black over time in [my home]. Describe how air and sulphur form a dark layer, how gentle cleaning restores shine, and how to store silver in a dry cloth bag." },
  { id: "science-315", title: "Rust proofing a water pump at home", category: "science", text: "Explain how to protect a home water pump from rust in [your city]. Describe keeping it dry and covered, checking for leaks, and why painting exposed iron parts helps it last longer through the rainy season." },
  { id: "science-316", title: "How soap removes dirt and oil", category: "science", text: "Explain in simple words how soap removes dirt and oil from [hands and clothes]. Describe how one end of a soap molecule holds oil and the other holds water, why rubbing helps, and why rinsing washes the dirt away." },
  { id: "science-317", title: "Why soap makes bubbles and foam", category: "science", text: "Explain in simple words why soap makes bubbles when I rub it with water in [a bucket]. Describe how soap lowers the surface tension of water, why air gets trapped in thin films, and why more foam does not always mean better cleaning." },
  { id: "science-318", title: "Soap versus detergent for laundry", category: "science", text: "Explain the difference between soap and detergent for washing clothes in [your city]. Say which one works better in hard water, why detergent suits machine washing, and when a simple soap bar is enough for [hand washing]." },
  { id: "science-319", title: "Why soap works better with warm water", category: "science", text: "Explain in simple words why soap cleans better with warm water than with cold water. Describe how warm water melts grease faster, helps soap spread, and why very hot water can damage [delicate clothes / skin]." },
  { id: "science-320", title: "How handwash kills germs on hands", category: "science", text: "Explain in simple words how handwash helps remove germs from [my hands]. Describe how soap lifts germs and dirt off the skin, why rubbing for 20 seconds matters, and why rinsing under clean running water completes the job." },
  { id: "science-321", title: "Why soap leaves white marks in hard water", category: "science", text: "Explain why soap leaves white marks and scum in hard water in [your city]. Describe how soap reacts with minerals in the water, why the marks appear on [taps / buckets / clothes], and how detergent avoids this problem." },
  { id: "science-322", title: "Liquid soap versus bar soap", category: "science", text: "Explain the difference between liquid soap and bar soap for daily use in [my home]. Compare cost, hygiene, skin dryness and waste, and help me choose the better option for [a family of 4 / a small office]." },
  { id: "science-323", title: "Why soap dries out skin", category: "science", text: "Explain in simple words why strong soap can dry out skin in [your city]. Describe how soap removes natural oils along with dirt, why mild soap suits dry skin, and how applying moisturiser after washing helps." },
  { id: "science-324", title: "How detergent powder cleans clothes", category: "science", text: "Explain in simple words how detergent powder cleans clothes in a washing machine. Describe how it lifts oil and dirt, why enzymes help with food stains, and why using too much powder leaves white marks on [dark clothes]." },
  { id: "science-325", title: "Why soap does not work in salty water", category: "science", text: "Explain in simple words why soap forms less lather in salty or hard water. Describe how minerals in the water use up the soap, why clothes feel stiff, and what people in [a coastal town / a hard water area] can do." },
  { id: "science-326", title: "Soap for washing fruits and vegetables", category: "science", text: "Explain whether soap should be used to wash fruits and vegetables in [my kitchen]. Describe why soap can leave a taste and upset the stomach, and why rinsing under clean running water is the safer choice." },
  { id: "science-327", title: "How shampoo cleans hair and scalp", category: "science", text: "Explain in simple words how shampoo cleans hair and scalp. Describe how it lifts oil and dirt from the hair, why massaging the scalp helps, and why rinsing well matters for [oily hair / dry hair] in [your city]." },
  { id: "science-328", title: "Why dish soap cuts grease well", category: "science", text: "Explain in simple words why dish soap cuts grease from oily vessels in [my kitchen]. Describe how it breaks oil into tiny drops that wash away with water, and why a small drop is enough for [a sink full of vessels]." },
  { id: "science-329", title: "Soap making at home explained simply", category: "science", text: "Explain in simple words how soap is made from [coconut oil] and an alkaline liquid. Describe the basic change that turns oil into soap, why the mixture must rest and cure, and why home soap making needs care and safety steps." },
  { id: "science-330", title: "Why soap smells fade over time", category: "science", text: "Explain why the smell of a soap bar fades when it is kept open in [my bathroom]. Describe how fragrance slowly escapes into the air, why storing soap in a closed box keeps the smell longer, and when old soap is still safe." },
  { id: "science-331", title: "Antibacterial soap versus plain soap", category: "science", text: "Explain the difference between antibacterial soap and plain soap for daily hand washing in [my home]. Say whether antibacterial soap works better, when plain soap is enough, and why washing technique matters more than the label." },
  { id: "science-332", title: "Why soap slips from wet hands", category: "science", text: "Explain in simple words why a wet soap bar slips from my hands in [the shower]. Describe how water forms a smooth layer between the soap and skin, why a soap dish with drainage helps, and how a soap net can stop it slipping." },
  { id: "science-333", title: "How soap helps wash away chillies", category: "science", text: "Explain why soap and water help wash chilli oil from hands after cutting [green chillies / red chillies]. Describe how soap lifts the oily layer, why water alone is not enough, and why I should avoid touching my eyes afterwards." },
  { id: "science-334", title: "Detergent for baby clothes explained", category: "science", text: "Explain what makes a detergent suitable for baby clothes in [my home]. Describe mild formulas, why strong fragrance can irritate a baby, and how rinsing twice helps remove soap left in the cloth." },
  { id: "science-335", title: "Why soap curd forms in hard water", category: "science", text: "Explain in simple words what soap curd is and why it forms in hard water in [your city]. Describe the white sticky layer on [buckets / taps], why it makes cleaning harder, and how using detergent helps avoid it." },
  { id: "science-336", title: "Soap and water for cleaning wounds", category: "science", text: "Explain in simple words why washing a small cut on [my finger] with soap and clean water helps. Give general information only, describe how soap lifts dirt and germs, and say when a cut needs a doctor instead of home care." },
  { id: "science-337", title: "How much detergent for one wash", category: "science", text: "Explain how much detergent powder I need for one machine wash in [my home]. Describe how water hardness and load size change the amount, why too much leaves residue on clothes, and how to measure it with a [spoon / cap]." },
  { id: "science-338", title: "Why soap bubbles are colourful", category: "science", text: "Explain in simple words why soap bubbles show rainbow colours in sunlight in [my garden]. Describe how light reflects from the thin soap film, why the colours change as the bubble gets thinner, and why the bubble bursts at last." },
  { id: "science-339", title: "Soap for cleaning makeup brushes", category: "science", text: "Explain how mild soap helps clean makeup brushes in [my home]. Describe washing them gently with lukewarm water, how to rinse out all the soap, and how to dry them flat so the brush shape stays good." },
  { id: "science-340", title: "Why detergent smells stay on clothes", category: "science", text: "Explain why detergent fragrance stays on clothes after washing in [your city]. Describe how scent stays trapped in cloth fibres, why drying in shade keeps the smell longer, and how to reduce it with an extra rinse." },
  { id: "science-341", title: "Choosing soap for sensitive skin", category: "science", text: "Explain how to choose a soap for sensitive skin in [your city]. Describe mild, fragrance-free options, why I should test a new soap on a small patch first, and when to ask a doctor about [rashes / itching]." },
  { id: "science-342", title: "Soap in cold water for woollens", category: "science", text: "Explain why mild soap and cold water suit woollen clothes in [your city]. Describe how hot water can shrink wool, how to wash gently without rubbing hard, and how to dry woollens flat in the shade." },
  { id: "science-343", title: "How soap removes turmeric stains", category: "science", text: "Explain how soap helps remove fresh turmeric stains from [a cloth / a steel vessel]. Describe washing quickly with soap and water, why sunlight can fade the yellow mark, and why an old stain may not fully go away." },
  { id: "science-344", title: "Why liquid detergent suits front loaders", category: "science", text: "Explain why liquid detergent often suits a front load washing machine in [my home]. Describe how it dissolves quickly in less water, why powder can leave residue, and how to measure the right amount for [a full load]." },
  { id: "science-345", title: "Soap storage in humid bathrooms", category: "science", text: "Explain the best way to store soap bars in a humid bathroom in [your city]. Describe a draining soap dish, why keeping soap dry between uses makes it last longer, and how to store extra bars in a dry cupboard." },
  { id: "science-346", title: "Why bleach cleans white clothes", category: "science", text: "Explain in simple words how bleach makes white clothes look whiter. Describe how it breaks down colour particles in stains, why it must be diluted, and why it can damage [coloured clothes / delicate fabric] if used wrongly." },
  { id: "science-347", title: "Bleach safety at home explained", category: "science", text: "Explain how to use bleach safely at home in [my house]. Describe wearing gloves, keeping windows open, why bleach must never be mixed with [vinegar / toilet cleaner], and how to store the bottle away from children." },
  { id: "science-348", title: "Why lemon cleans grease and stains", category: "science", text: "Explain in simple words why lemon juice helps clean grease and stains in [my kitchen]. Describe its mild acid, how it cuts oil on steel and glass, and why I should rinse the surface after cleaning." },
  { id: "science-349", title: "How phenyl cleans floors at home", category: "science", text: "Explain how phenyl helps clean floors and reduce smells in [my home]. Describe diluting it in water, how to mop safely, and why the floor must dry fully before [children / elders] walk on it." },
  { id: "science-350", title: "Why hot water cleans oily vessels", category: "science", text: "Explain in simple words why hot water cleans oily vessels better than cold water in [my kitchen]. Describe how heat melts solid oil, helps soap work faster, and why I should still be careful not to burn my hands." },
  { id: "science-351", title: "Cleaning chemistry of tamarind water", category: "science", text: "Explain why tamarind water helps clean brass and copper vessels in [my home]. Describe its mild acid, how it removes the dull layer, and how to rinse and dry the vessel so it keeps its shine longer." },
  { id: "science-352", title: "Why salt helps clean burnt pans", category: "science", text: "Explain how salt helps clean burnt food from a pan in [my kitchen]. Describe its gentle scrubbing action, how to mix it with a little water, and why I should avoid harsh scrubbing on [non-stick / coated pans]." },
  { id: "science-353", title: "How to clean a mixer jar safely", category: "science", text: "Explain how to clean a mixer jar safely after grinding [turmeric / chutney] in [my kitchen]. Describe warm soapy water, why the blades need care, and how to dry the jar fully before storing it away." },
  { id: "science-354", title: "Why vinegar and bleach must never mix", category: "science", text: "Explain in simple words why vinegar and bleach must never be mixed at home. Describe the harmful gas that can form, what symptoms to watch for, and what to do at once if someone mixes them by mistake in [a bathroom]." },
  { id: "science-355", title: "Cleaning a chimney filter with soda", category: "science", text: "Explain how baking soda water helps clean grease from a kitchen chimney filter in [my home]. Describe soaking the filter, how long to leave it, and how to scrub, rinse and dry it before fixing it back." },
  { id: "science-356", title: "Why toothpaste cleans silver items", category: "science", text: "Explain why a little toothpaste helps clean dull silver items in [my home]. Describe its mild scrubbing particles, how to rub gently with a soft cloth, and why I should rinse well and dry the silver afterwards." },
  { id: "science-357", title: "How to remove oil stains from clothes", category: "science", text: "Explain how to remove a fresh oil stain from a shirt in [your city]. Describe blotting the oil first, applying dish soap, how long to leave it, and why hot water helps after the soap has loosened the stain." },
  { id: "science-358", title: "Why alcohol cleans phone screens", category: "science", text: "Explain how a little rubbing alcohol helps clean a phone screen in [my home]. Describe how it removes oil and germs, why I should use a soft cloth, and why I must never pour liquid directly on the phone." },
  { id: "science-359", title: "Cleaning chemistry of rice water", category: "science", text: "Explain whether rice water helps clean vessels in [my kitchen]. Describe its mild starch, what it can and cannot clean, and why soap and hot water are still better for oily vessels and food germs." },
  { id: "science-360", title: "Why soap and water beat sanitiser", category: "science", text: "Explain why washing with soap and water often beats hand sanitiser for dirty hands in [my home]. Describe how soap lifts dirt and germs away, when sanitiser is useful, and why it works poorly on [muddy / oily hands]." },
  { id: "science-361", title: "How to clean a gas stove burner", category: "science", text: "Explain how to clean a blocked gas stove burner safely in [my kitchen]. Describe removing the cool parts, soaking them in warm soapy water, and how to dry them fully before lighting the stove again." },
  { id: "science-362", title: "Why cleaning products need labels", category: "science", text: "Explain why cleaning product labels matter for safety at home in [your city]. Describe reading the use, warnings and first aid lines, why I should keep the bottle, and how to store products away from [children / food]." },
  { id: "science-363", title: "Cleaning a fridge with lemon water", category: "science", text: "Explain how lemon water helps clean a fridge in [my home]. Describe wiping shelves with diluted lemon water, how it cuts smells, and why I should switch off the fridge and dry the shelves before switching it on." },
  { id: "science-364", title: "Why hard water leaves white marks", category: "science", text: "Explain in simple words why hard water leaves white marks on taps and vessels in [your city]. Describe the minerals left behind when water dries, why vinegar helps remove them, and how wiping dry prevents new marks." },
  { id: "science-365", title: "How to clean a steel water filter", category: "science", text: "Explain how to clean a steel water filter at home in [your city]. Describe washing it with mild soap, why harsh chemicals must be avoided, and how to rinse and dry it before using it for drinking water again." },
  { id: "science-366", title: "Why baking soda freshens a carpet", category: "science", text: "Explain how baking soda helps freshen a carpet in [my home]. Describe sprinkling it evenly, how long to leave it before vacuuming, and why it helps with smells but does not remove deep stains or dirt." },
  { id: "science-367", title: "Cleaning chemistry of coconut coir scrub", category: "science", text: "Explain how a coconut coir scrub helps clean vessels in [my kitchen]. Describe its rough fibres, why it scrubs without scratching steel much, and how to wash and dry the scrubber so it does not smell." },
  { id: "science-368", title: "Why detergents need rinsing well", category: "science", text: "Explain why clothes and vessels must be rinsed well after detergent in [my home]. Describe the residue left behind, why it can irritate skin, and how an extra rinse helps for [baby clothes / steel vessels]." },
  { id: "science-369", title: "How to clean a tiffin box smell", category: "science", text: "Explain how to remove a strong food smell from a steel tiffin box in [my home]. Describe soaking it in warm water with [lemon / baking soda], how long to leave it, and how to dry it fully in sunlight." },
  { id: "science-370", title: "Why oil and water do not mix", category: "science", text: "Explain in simple words why oil and water do not mix in [my kitchen]. Describe how water molecules hold together tightly, why oil floats on top, and how soap helps them mix for a short time during cleaning." },
  { id: "science-371", title: "Cleaning a burnt pressure cooker", category: "science", text: "Explain how to clean a burnt pressure cooker safely in [my kitchen]. Describe soaking it in warm water with baking soda, how long to wait, and how to scrub gently without damaging the base or the safety valve." },
  { id: "science-372", title: "Why glass cleaner leaves no streaks", category: "science", text: "Explain in simple words why glass cleaner leaves glass clear without streaks. Describe how it dissolves grease and dries quickly, why a lint-free cloth helps, and how to clean [windows / mirrors] in [my home]." },
  { id: "science-373", title: "How to clean a wooden dining table", category: "science", text: "Explain how to clean a wooden dining table after a meal in [my home]. Describe wiping with a damp cloth, why too much water damages wood, and how to dry it at once so the surface stays smooth and clean." },
  { id: "science-374", title: "Why lemon removes fish smell", category: "science", text: "Explain in simple words why lemon juice helps remove fish smell from hands and vessels in [my kitchen]. Describe how its acid changes the smell chemicals, how to rub it on, and why washing with soap afterwards helps more." },
  { id: "science-375", title: "Cleaning chemistry of ash and sand", category: "science", text: "Explain why ash and sand were used to clean vessels in old Indian homes in [your village / town]. Describe their scrubbing action, what they can clean, and why soap and clean water are safer choices today." },
  { id: "science-376", title: "How to clean a lunch bag smell", category: "science", text: "Explain how to remove a food smell from a cloth lunch bag in [my home]. Describe washing it with mild soap, drying it fully in sunlight, and why storing it open helps stop the smell from returning." },
  { id: "science-377", title: "Why soap scum forms on bathroom tiles", category: "science", text: "Explain in simple words why soap scum forms on bathroom tiles in [your city]. Describe how soap reacts with hard water minerals, why the white layer builds up, and how regular wiping and rinsing keep tiles clean." },
  { id: "science-378", title: "Cleaning a kettle with lemon water", category: "science", text: "Explain how lemon water helps clean white scale from a kettle in [your city]. Describe boiling lemon slices in water, how long to leave it, and how to rinse several times before boiling drinking water again." },
  { id: "science-379", title: "Why gloves matter when cleaning", category: "science", text: "Explain why wearing gloves matters when using strong cleaners at home in [your city]. Describe how chemicals can dry and irritate skin, why gloves protect hands, and how to wash and dry gloves after cleaning." },
  { id: "science-380", title: "How to store cleaning products safely", category: "science", text: "Explain how to store cleaning products safely in a home with children in [your city]. Describe keeping them in original bottles, on a high shelf, away from food, and why I should never pour them into a [water / juice] bottle." },
  { id: "science-381", title: "Why milk curdles with lemon juice", category: "science", text: "Explain in simple words why milk curdles when lemon juice is added to make [paneer / chenna]. Describe how the acid changes milk protein, why the solid and water separate, and how to drain the solid with a clean cloth." },
  { id: "science-382", title: "Why onions make eyes water", category: "science", text: "Explain in simple words why cutting onions makes eyes water in [my kitchen]. Describe the gas released when onion cells break, why it irritates the eyes, and how chilling the onion or using a sharp knife helps." },
  { id: "science-383", title: "Why sugar dissolves faster in tea", category: "science", text: "Explain in simple words why sugar dissolves faster in hot tea than in cold water. Describe how heat moves sugar particles apart, why stirring helps, and why cold [lassi / juice] needs more stirring to dissolve sugar." },
  { id: "science-384", title: "Why rice turns soft when cooked", category: "science", text: "Explain in simple words why rice turns soft when it is cooked in water. Describe how starch grains absorb water and swell, why soaking rice first helps, and what happens if I add too much water to [a pot of rice]." },
  { id: "science-385", title: "Why oil smokes when heated too much", category: "science", text: "Explain in simple words why cooking oil starts smoking when it is heated too much in [my kitchen]. Describe the smoke point, why reused oil smokes sooner, and why I should turn off the heat and let it cool." },
  { id: "science-386", title: "Why bread turns brown in toaster", category: "science", text: "Explain in simple words why bread turns brown in a toaster. Describe how heat changes sugars and proteins on the surface, why the crust tastes different, and what happens when bread is toasted for too long in [my home]." },
  { id: "science-387", title: "Why salt makes ice melt faster", category: "science", text: "Explain in simple words why salt makes ice melt faster on [a road / a freezer tray]. Describe how salt lowers the freezing point of water, why the ice turns to water sooner, and where this idea is useful in winter." },
  { id: "science-388", title: "Why jaggery melts in hot milk", category: "science", text: "Explain in simple words why jaggery melts quickly in hot milk for [payasam / tea]. Describe how heat breaks the solid into syrup, why stirring helps it mix, and why adding jaggery to boiling milk can sometimes split it." },
  { id: "science-389", title: "Why green chillies turn red", category: "science", text: "Explain in simple words why green chillies turn red as they ripen in [my kitchen garden / the market]. Describe how the colour chemicals change, why red chillies taste hotter, and how to store both kinds so they stay fresh." },
  { id: "science-390", title: "Why curd sets faster in summer", category: "science", text: "Explain in simple words why curd sets faster in summer in [your city]. Describe how warm weather helps friendly bacteria turn milk sour, why winter needs more time, and how much starter curd to use for [1 litre of milk]." },
  { id: "science-391", title: "Why potatoes turn brown after cutting", category: "science", text: "Explain in simple words why cut potatoes turn brown in air. Describe how oxygen reacts with the potato surface, why keeping them in water stops the browning, and how to store cut potatoes before cooking [a curry / fries]." },
  { id: "science-392", title: "Why ghee smells nutty when heated", category: "science", text: "Explain in simple words why ghee smells nutty when it is heated in [my kitchen]. Describe how milk solids brown in the heat, why the smell changes with time, and how to stop heating before the ghee burns." },
  { id: "science-393", title: "Why salt preserves pickles and papads", category: "science", text: "Explain why salt helps preserve pickles and papads in [your region]. Describe how salt draws water out of food, why germs struggle to grow without water, and how to store pickles in a dry place." },
  { id: "science-394", title: "Why eggs float in salty water", category: "science", text: "Explain in simple words why a fresh egg sinks in plain water but floats in salty water. Describe how salt makes water heavier, why a floating egg may be old, and how to test an egg before cooking [an omelette / curry]." },
  { id: "science-395", title: "Why bananas ripen faster in paper", category: "science", text: "Explain in simple words why bananas ripen faster when wrapped in paper with [an apple]. Describe the natural gas fruits release, why the paper traps it, and how to slow ripening by keeping bananas apart in the fridge." },
  { id: "science-396", title: "Why dosa batter ferments overnight", category: "science", text: "Explain in simple words why dosa batter ferments overnight in [your city]. Describe how friendly bacteria and yeast make gas, why warm weather helps, and how to tell when the batter is ready to cook." },
  { id: "science-397", title: "Why tea changes colour with milk", category: "science", text: "Explain in simple words why tea changes colour when milk is added to [a cup of chai]. Describe how milk proteins and fats scatter light, why strong tea turns light brown, and how the amount of milk changes the colour and taste." },
  { id: "science-398", title: "Why sugar helps preserve jam", category: "science", text: "Explain why sugar helps preserve jam made from [mango / mixed fruit] in [my home]. Describe how sugar draws water out, why germs cannot grow easily, and how to store jam in a clean dry jar." },
  { id: "science-399", title: "Why chapati puffs up on flame", category: "science", text: "Explain in simple words why a chapati puffs up on the flame. Describe how steam forms inside the dough, why the layers separate, and how rolling the chapati evenly helps it puff up in [my kitchen]." },
  { id: "science-400", title: "Why oil floats on top of sambar", category: "science", text: "Explain in simple words why oil floats on top of sambar and rasam. Describe how oil is lighter than water, why it does not mix, and how the tadka oil carries the flavour of [mustard / curry leaves] on top." },
  { id: "science-401", title: "Why ice cream melts and refreezes badly", category: "science", text: "Explain in simple words why ice cream tastes icy after it melts and refreezes in [my home]. Describe how large ice crystals form, why the creamy texture is lost, and how to store ice cream at a steady cold temperature." },
  { id: "science-402", title: "Why chopping onions makes eyes water", category: "science", text: "Explain in simple words why chopping onions makes our eyes water in [a kitchen]. Describe the gas that comes out of the cut onion, why it stings the eyes, and three simple tricks to cry less while cutting." },
  { id: "science-403", title: "Why salt draws water from vegetables", category: "science", text: "Explain in simple words why salt draws water out of vegetables like [cucumber / brinjal]. Describe how water moves towards the salt, why the vegetable turns soft, and when this step helps before cooking a curry." },
  { id: "science-404", title: "Why milk forms a skin when boiled", category: "science", text: "Explain in simple words why boiled milk forms a thin skin on top. Describe how milk proteins join together as the milk heats, why stirring stops the skin forming, and how to remove it before serving [tea / payasam]." },
  { id: "science-405", title: "Why spices release flavour in oil", category: "science", text: "Explain in simple words why spices release more flavour when fried in oil for a tadka. Describe how oil carries flavour chemicals, why [cumin / mustard] crackle first, and how burning them changes the taste of [a dal / curry]." },
  { id: "science-406", title: "Why rice water turns starchy white", category: "science", text: "Explain in simple words why water turns white when rice is washed in [my kitchen]. Describe the starch that washes off the grains, why rinsing twice helps, and whether the starchy water can be used for [plants / cleaning]." },
  { id: "science-407", title: "Why honey thickens in cold weather", category: "science", text: "Explain in simple words why honey thickens and turns cloudy in cold weather in [your city]. Describe how sugar crystals form, why gentle warming in warm water helps, and why I should never boil honey directly." },
  { id: "science-408", title: "Why curd turns sour when kept out", category: "science", text: "Explain in simple words why curd turns sour when it is kept outside the fridge in [your city]. Describe how bacteria keep making acid, why warm weather speeds it up, and how to store curd so it stays fresh longer." },
  { id: "science-409", title: "Why popcorn pops in hot oil", category: "science", text: "Explain in simple words why popcorn pops in hot oil. Describe how water inside the corn kernel turns to steam, why pressure builds up, and how the kernel bursts open into a fluffy white piece in [a kadai / a cooker]." },
  { id: "science-410", title: "Why vinegar makes beetroot stay red", category: "science", text: "Explain in simple words why vinegar helps beetroot stay bright red in [a pickle / a salad]. Describe how acid keeps the natural colour strong, why plain water can dull it, and how much vinegar to add for the best colour." },
  { id: "science-411", title: "Why coffee tastes bitter when overbrewed", category: "science", text: "Explain in simple words why coffee tastes bitter when it is brewed for too long. Describe how hot water pulls out bitter chemicals after the good flavour, and how to brew [filter coffee / instant coffee] for a balanced taste." },
  { id: "science-412", title: "Why salt melts ice on a freezer", category: "science", text: "Explain in simple words why salt helps melt thick ice in a freezer in [my home]. Describe how salt lowers the freezing point, why the ice loosens, and how to switch off the freezer and wipe it dry afterwards." },
  { id: "science-413", title: "Why tomatoes soften when cooked", category: "science", text: "Explain in simple words why tomatoes soften when they are cooked for [a curry / rasam]. Describe how heat breaks down the cell walls, why the juice comes out, and how cooking time changes the taste from tangy to sweet." },
  { id: "science-414", title: "Why baking soda makes besan fluffy", category: "science", text: "Explain why a pinch of baking soda makes besan batter light and fluffy for [pakoras / dhokla]. Describe the gas released in hot oil or steam, why the batter must be used quickly, and what happens if I add too much." },
  { id: "science-415", title: "Why oil splutters with water drops", category: "science", text: "Explain in simple words why hot oil splutters when water drops fall into it in [my kitchen]. Describe how water turns to steam at once, why the steam throws oil up, and how drying vegetables first keeps cooking safer." },
  { id: "science-416", title: "Why green vegetables lose colour", category: "science", text: "Explain in simple words why green vegetables lose their bright colour when overcooked. Describe how heat and acid break down the green pigment, why [spinach / beans] turn dull, and how to cook them briefly in [my kitchen]." },
  { id: "science-417", title: "Why sugar caramel turns brown", category: "science", text: "Explain in simple words why sugar turns brown when it is heated for [payasam / caramel]. Describe how heat changes sugar into new flavour chemicals, why the colour deepens, and when to stop before it turns bitter." },
  { id: "science-418", title: "Why curd helps soften paneer dishes", category: "science", text: "Explain why marinating paneer in curd makes it soft for [a curry / tikka]. Describe how the mild acid relaxes the protein, why [30 minutes] is often enough, and how over-marinating can make paneer break apart." },
  { id: "science-419", title: "Why vinegar softens tough meat", category: "science", text: "Explain why a little vinegar in a marinade helps soften tough meat for [a curry / kebab]. Describe how acid loosens the fibres, how long to marinate, and why too much vinegar can make the meat dry and sour." },
  { id: "science-420", title: "Why lemon makes fish taste fresh", category: "science", text: "Explain in simple words why lemon juice makes fish taste fresh in [a curry / a fry]. Describe how its acid balances the strong fish smell, when to add it during cooking, and how much is enough for [4 pieces]." },
  { id: "science-421", title: "Why salt keeps ice cream cold", category: "science", text: "Explain in simple words why salt and ice are used together to keep ice cream cold in [an old hand churn / a cooler box]. Describe how salt lowers the freezing point, why the mixture gets colder than plain ice, and how it freezes the cream." },
  { id: "science-422", title: "Why chillies feel hot on tongue", category: "science", text: "Explain in simple words why chillies feel hot on the tongue even though they are not really hot. Describe the chemical that tricks heat sensors, why milk helps more than water, and how to handle [green chillies] safely." },
  { id: "science-423", title: "Why baking soda helps clean burnt milk", category: "science", text: "Explain how baking soda helps clean burnt milk from a steel vessel in [my kitchen]. Describe soaking it in warm soda water, how long to wait, and how to scrub gently and rinse well before using the vessel again." },
  { id: "science-424", title: "Why oil and lemon make a dressing", category: "science", text: "Explain in simple words why oil and lemon juice make a simple salad dressing for [a cucumber salad]. Describe how the sour juice balances the oil, why shaking mixes them briefly, and how much lemon to use for a fresh taste." },
  { id: "science-425", title: "Why food smells stronger when hot", category: "science", text: "Explain in simple words why food smells stronger when it is hot in [my kitchen]. Describe how heat releases more smell particles into the air, why [sambar / biryani] smells best when fresh, and why cold food smells less." },
  { id: "science-426", title: "How the human heart works simply", category: "science", text: "Explain in simple words how the human heart works for a beginner in [your city]. Describe its four rooms, the valves, and how blood moves through the body. Use a simple pump comparison and short sentences." },
  { id: "science-427", title: "Why the heart beats faster when running", category: "science", text: "Explain in simple words why the heart beats faster when a person runs or climbs stairs in [your town]. Describe what the muscles need, how blood flow changes, and why the beat slows down after rest." },
  { id: "science-428", title: "What blood pressure numbers mean simply", category: "science", text: "Explain in simple words what the two numbers in a blood pressure reading mean for a beginner in [your city]. Describe what the top number and bottom number show, and give general information only, with no personal advice." },
  { id: "science-429", title: "How blood travels around the body", category: "science", text: "Describe in simple words the journey of blood around the body for a school student in [your city]. Start at the heart, go to the lungs, then to the body parts, and back again. Use clear steps." },
  { id: "science-430", title: "Arteries veins and capillaries compared simply", category: "science", text: "Compare arteries, veins and capillaries in simple words for a beginner in [your city]. Explain what each kind of blood vessel does, how thick its walls are, and how blood moves through each one." },
  { id: "science-431", title: "Why we can feel our pulse", category: "science", text: "Explain in simple words why we can feel a pulse at the wrist or neck in [your home]. Describe how each heartbeat pushes blood through the arteries, and why the pulse rate changes with activity, rest and age." },
  { id: "science-432", title: "What red blood cells do daily", category: "science", text: "Explain in simple words what red blood cells do in the body for a beginner in [your city]. Describe how they carry oxygen from the lungs to body parts, and how they bring carbon dioxide back. Use short sentences." },
  { id: "science-433", title: "White blood cells and body defence explained", category: "science", text: "Explain in simple words how white blood cells help defend the body for a student in [your city]. Describe how they find germs, what they do to them, and why their numbers rise during an infection in general terms." },
  { id: "science-434", title: "How the heart gets its own blood", category: "science", text: "Explain in simple words how the heart muscle gets its own blood supply for a beginner in [your city]. Describe the small vessels on the heart surface, and why the heart needs oxygen all the time to keep beating." },
  { id: "science-435", title: "Heartbeat sounds lub dub explained simply", category: "science", text: "Explain in simple words why the heart makes lub dub sounds for a child in [your city]. Describe how the heart valves open and close, and what each sound means. Keep the language simple and use one everyday comparison." },
  { id: "science-436", title: "Why exercise is good for heart science", category: "science", text: "Explain in simple words the science behind regular walking and exercise for heart health in general terms for a beginner in [your city]. Describe how the heart muscle grows stronger and how blood flow improves over time." },
  { id: "science-437", title: "What cholesterol means in simple words", category: "science", text: "Explain in simple words what cholesterol is for a beginner in [your city]. Describe the good and bad types in general terms, where cholesterol comes from, and how it travels in the blood. Give general information only." },
  { id: "science-438", title: "How salt affects blood pressure science", category: "science", text: "Explain in simple words the science of how too much salt in food can affect blood pressure in general terms for a reader in [your city]. Describe how salt and water balance in the body are linked. No personal advice." },
  { id: "science-439", title: "Heart size and shape facts simply", category: "science", text: "Describe in simple words the size, shape and place of the human heart for a school student in [your city]. Compare its size with a closed fist, explain where it sits in the chest, and why it leans slightly left." },
  { id: "science-440", title: "Why the heart never gets tired", category: "science", text: "Explain in simple words why the heart can keep beating day and night without rest for a beginner in [your city]. Describe its special muscle, its steady blood supply, and how its cells work in a repeating rhythm." },
  { id: "science-441", title: "How doctors listen to the heart", category: "science", text: "Explain in simple words how a stethoscope helps a doctor listen to the heart for a curious child in [your city]. Describe what sounds the doctor hears, and what general information those sounds can give about the heartbeat." },
  { id: "science-442", title: "Blood groups explained for Indian beginners", category: "science", text: "Explain in simple words what blood groups A, B, AB and O mean for a beginner in [your city]. Describe why matching blood groups matters in a transfusion, and why hospitals test blood before giving it to anyone." },
  { id: "science-443", title: "Why blood is red in colour", category: "science", text: "Explain in simple words why human blood looks red for a school student in [your city]. Describe the role of haemoglobin in red blood cells, how oxygen changes its colour, and why veins can look blue through skin." },
  { id: "science-444", title: "How the heart changes with age", category: "science", text: "Explain in simple words how the heart and blood vessels change as a person grows older, in general terms, for a reader in [your city]. Describe how the walls can thicken and why regular movement matters. No personal advice." },
  { id: "science-445", title: "What happens during a heart attack simply", category: "science", text: "Explain in simple words what happens inside the body during a heart attack, in general terms, for a beginner in [your city]. Describe a blocked vessel, the lack of oxygen to heart muscle, and why quick hospital care matters." },
  { id: "science-446", title: "How the heart and lungs work together", category: "science", text: "Explain in simple words how the heart and lungs work as a team for a student in [your city]. Describe how blood picks up oxygen in the lungs, how the heart pumps it out, and how carbon dioxide returns to be breathed out." },
  { id: "science-447", title: "Why we feel breathless after climbing stairs", category: "science", text: "Explain in simple words why a person feels breathless after climbing stairs in [your building]. Describe how muscles use more oxygen, how breathing and heartbeat speed up, and why the feeling passes after a short rest." },
  { id: "science-448", title: "How stress affects the heartbeat science", category: "science", text: "Explain in simple words how worry or sudden stress can change the heartbeat in general terms for a beginner in [your city]. Describe the body signals involved, why the heart speeds up, and why it settles when a person calms down." },
  { id: "science-449", title: "What an ECG tracing shows simply", category: "science", text: "Explain in simple words what an ECG tracing shows for a beginner in [your city]. Describe how small electrical signals make the heart beat, how the wavy line follows each beat, and what general information doctors read from it." },
  { id: "science-450", title: "How blood clots stop bleeding simply", category: "science", text: "Explain in simple words how blood clots stop bleeding after a small cut for a child in [your city]. Describe platelets, the sticky mesh they form, and how the clot hardens and protects the skin while it heals." },
  { id: "science-451", title: "Why the heart beats before birth", category: "science", text: "Explain in simple words how a baby heart starts beating before birth for a curious reader in [your city]. Describe the early heart cells, how the beat begins on its own, and how the heart grows with the baby." },
  { id: "science-452", title: "Heart valves and their job explained", category: "science", text: "Explain in simple words what the four heart valves do for a student in [your city]. Describe how they open to let blood through, close to stop it flowing back, and how they keep blood moving in one direction only." },
  { id: "science-453", title: "How walking helps blood circulation simply", category: "science", text: "Explain in simple words how a daily walk helps blood circulation in general terms for a beginner in [your city]. Describe how leg muscles help push blood back to the heart, and why sitting still for long hours slows this flow." },
  { id: "science-454", title: "What plasma in blood does daily", category: "science", text: "Explain in simple words what plasma does in the blood for a beginner in [your city]. Describe the pale yellow liquid, what it carries, and how it helps move food, hormones and waste around the body. Use short sentences." },
  { id: "science-455", title: "Why some people feel dizzy standing up", category: "science", text: "Explain in simple words why some people feel dizzy when they stand up quickly, in general terms, for a reader in [your city]. Describe how blood pools in the legs, how pressure changes briefly, and why sitting down helps. No personal advice." },
  { id: "science-456", title: "How the body controls heartbeat rhythm", category: "science", text: "Explain in simple words how the body controls the rhythm of the heartbeat for a student in [your city]. Describe the natural pacemaker, the electrical signals, and how nerves speed the beat up or slow it down." },
  { id: "science-457", title: "Heart and brain connection explained simply", category: "science", text: "Explain in simple words how the heart and brain send messages to each other for a beginner in [your city]. Describe how the brain senses pressure and oxygen, and how it tells the heart to beat faster or slower." },
  { id: "science-458", title: "Why cold weather affects blood vessels", category: "science", text: "Explain in simple words why cold weather makes blood vessels narrow, in general terms, for a reader in [your city]. Describe how the body keeps heat inside, why hands feel cold first, and why the heart works a little harder." },
  { id: "science-459", title: "How iron in food helps blood", category: "science", text: "Explain in simple words how iron in food helps the blood carry oxygen, in general terms, for a beginner in [your city]. Name common Indian foods rich in iron, and describe how red blood cells use iron to make haemoglobin." },
  { id: "science-460", title: "What happens to blood in the kidneys", category: "science", text: "Explain in simple words what happens to blood as it passes through the kidneys for a student in [your city]. Describe how the kidneys filter waste and extra water, and how clean blood returns to the heart." },
  { id: "science-461", title: "How the lungs fill with air", category: "science", text: "Explain in simple words how the lungs fill with air when we breathe in for a child in [your city]. Describe the diaphragm moving down, the chest expanding, and air flowing through the nose and windpipe into the lungs." },
  { id: "science-462", title: "Why we breathe out carbon dioxide", category: "science", text: "Explain in simple words why we breathe out carbon dioxide for a school student in [your city]. Describe how body cells use oxygen, make carbon dioxide as waste, and how the blood carries it to the lungs to be breathed out." },
  { id: "science-463", title: "How oxygen reaches body cells simply", category: "science", text: "Explain in simple words how oxygen travels from the air to body cells for a beginner in [your city]. Follow the path from nose to lungs, into the blood, then to muscles and organs. Use clear steps and short sentences." },
  { id: "science-464", title: "What the diaphragm does when breathing", category: "science", text: "Explain in simple words what the diaphragm does when we breathe for a student in [your city]. Describe this dome-shaped muscle under the lungs, how it flattens when we breathe in, and how it relaxes when we breathe out." },
  { id: "science-465", title: "Why we yawn and what it does", category: "science", text: "Explain in simple words why people yawn for a curious reader in [your city]. Describe how a deep yawn brings in more air, stretches the jaw and chest muscles, and why yawns often spread when others yawn nearby." },
  { id: "science-466", title: "How the nose cleans the air", category: "science", text: "Explain in simple words how the nose cleans the air we breathe for a child in [your city]. Describe the tiny hairs, the sticky mucus, and how dust and germs get trapped before the air reaches the lungs." },
  { id: "science-467", title: "Why we cough when dust enters", category: "science", text: "Explain in simple words why we cough when dust or smoke enters the airways for a beginner in [your city]. Describe how the body senses irritation, and how a strong cough pushes air out fast to clear the passage." },
  { id: "science-468", title: "What happens inside the tiny air sacs", category: "science", text: "Explain in simple words what happens inside the tiny air sacs of the lungs for a student in [your city]. Describe their thin walls, the blood vessels around them, and how oxygen and carbon dioxide swap places there." },
  { id: "science-469", title: "How breathing changes during sleep simply", category: "science", text: "Explain in simple words how breathing changes during sleep for a beginner in [your city]. Describe how breathing slows down, becomes more regular, and how the body still keeps oxygen flowing while the muscles rest." },
  { id: "science-470", title: "Why running makes us breathe faster", category: "science", text: "Explain in simple words why running makes us breathe faster for a school student in [your city]. Describe how working muscles use more oxygen, make more carbon dioxide, and how the brain tells the lungs to work harder." },
  { id: "science-471", title: "How smoke affects the lungs science", category: "science", text: "Explain in simple words how smoke affects the lungs in general terms for a reader in [your city]. Describe how tiny smoke particles irritate the airways, damage the cleaning hairs, and make breathing harder over time." },
  { id: "science-472", title: "What asthma means in simple words", category: "science", text: "Explain in simple words what asthma means in general terms for a beginner in [your city]. Describe how airways can narrow, why breathing becomes hard, and what common triggers are. Give general information only, with no personal advice." },
  { id: "science-473", title: "Why we sneeze and how it works", category: "science", text: "Explain in simple words why we sneeze for a child in [your city]. Describe how the nose senses dust or pollen, sends a signal to the brain, and how a sneeze pushes air out fast to clear the nose." },
  { id: "science-474", title: "How the voice box makes sound", category: "science", text: "Explain in simple words how the voice box makes sound for a student in [your city]. Describe the vocal cords, how air from the lungs makes them vibrate, and how the mouth and tongue shape the sound into words." },
  { id: "science-475", title: "Why deep breathing feels calming simply", category: "science", text: "Explain in simple words why slow deep breathing can feel calming in general terms for a beginner in [your city]. Describe how slow breaths change the heartbeat, relax chest muscles, and help the body feel less tense." },
  { id: "science-476", title: "How lungs grow from childhood to adulthood", category: "science", text: "Explain in simple words how the lungs grow from childhood to adulthood for a reader in [your city]. Describe how the chest grows, how lung size increases, and how breathing capacity changes as a child becomes an adult." },
  { id: "science-477", title: "What happens when we hold our breath", category: "science", text: "Explain in simple words what happens when a person holds their breath for a short time for a student in [your city]. Describe how oxygen falls, carbon dioxide builds up, and why the brain soon gives a strong urge to breathe again." },
  { id: "science-478", title: "How the body measures breathing rate", category: "science", text: "Explain in simple words how the brain measures breathing needs for a beginner in [your city]. Describe how sensors sense carbon dioxide in the blood, and how the brain adjusts breathing speed without us thinking about it." },
  { id: "science-479", title: "Why air pollution harms breathing science", category: "science", text: "Explain in simple words why air pollution harms breathing in general terms for a reader in [your city]. Describe fine dust, smoke and gases, how they irritate the lungs, and why children and elders feel the effects more." },
  { id: "science-480", title: "How the windpipe and food pipe differ", category: "science", text: "Compare the windpipe and the food pipe in simple words for a school student in [your city]. Explain where each one leads, how a small flap protects the windpipe when we swallow, and why food sometimes goes the wrong way." },
  { id: "science-481", title: "What lung capacity means simply explained", category: "science", text: "Explain in simple words what lung capacity means for a beginner in [your city]. Describe how much air the lungs can hold, how it is measured in general terms, and why regular activity can improve breathing over time." },
  { id: "science-482", title: "Why we breathe through the mouth sometimes", category: "science", text: "Explain in simple words why people sometimes breathe through the mouth for a child in [your city]. Describe a blocked nose, heavy exercise, and how mouth breathing skips the nose cleaning step, so the air is less filtered." },
  { id: "science-483", title: "How hiccups start and stop simply", category: "science", text: "Explain in simple words why hiccups start for a curious reader in [your city]. Describe how the diaphragm twitches suddenly, how the voice box closes, and why hiccups usually stop on their own after a short while." },
  { id: "science-484", title: "How the lungs clean themselves daily", category: "science", text: "Explain in simple words how the lungs clean themselves for a student in [your city]. Describe the tiny hairs that sweep mucus upward, how dust gets trapped, and why coughing helps clear what the hairs cannot move." },
  { id: "science-485", title: "Why singing helps breathing muscles", category: "science", text: "Explain in simple words how singing uses the breathing muscles for a beginner in [your city]. Describe how singers control slow breaths, use the diaphragm, and how regular singing can strengthen breath control over time." },
  { id: "science-486", title: "What happens in the lungs at high altitude", category: "science", text: "Explain in simple words what happens to breathing at high places like Ladakh for a traveller in [your city]. Describe thinner air, less oxygen in each breath, and why the body breathes faster until it adjusts over days." },
  { id: "science-487", title: "How the chest moves when breathing", category: "science", text: "Explain in simple words how the chest moves when we breathe for a child in [your city]. Describe the ribs lifting, the chest widening, and how the muscles between the ribs help the lungs fill and empty with air." },
  { id: "science-488", title: "Why cold air can make breathing harder", category: "science", text: "Explain in simple words why cold air can make breathing feel harder in general terms for a reader in [your city]. Describe how cold dry air irritates the airways, and why covering the mouth with a scarf can warm the air." },
  { id: "science-489", title: "How oxygen helps muscles work simply", category: "science", text: "Explain in simple words how oxygen helps muscles work for a school student in [your city]. Describe how muscles use oxygen to release energy from food, and what happens when muscles work faster than oxygen can reach them." },
  { id: "science-490", title: "What the lungs look like inside", category: "science", text: "Describe in simple words what the lungs look like inside for a beginner in [your city]. Explain the branching airways like a tree, the tiny air sacs at the ends, and the blood vessels that wrap around each sac." },
  { id: "science-491", title: "Why we need both lungs to breathe", category: "science", text: "Explain in simple words why having two lungs helps the body for a student in [your city]. Describe how each lung serves one side of the chest, how they share the work, and how the body can still breathe if one is smaller." },
  { id: "science-492", title: "How the body gets rid of extra carbon dioxide", category: "science", text: "Explain in simple words how the body gets rid of extra carbon dioxide for a beginner in [your city]. Describe how blood carries it to the lungs, how it passes into the air sacs, and how each breath out removes it." },
  { id: "science-493", title: "Why yawning happens when feeling sleepy", category: "science", text: "Explain in simple words why yawning often happens when a person feels sleepy for a reader in [your city]. Describe tired muscles, slower breathing, and how a big yawn stretches the face and brings in a deep breath." },
  { id: "science-494", title: "How breathing and speaking work together", category: "science", text: "Explain in simple words how breathing and speaking work together for a student in [your city]. Describe how we take a quick breath in, then control the air out slowly while the voice box makes sounds for words." },
  { id: "science-495", title: "Simple breathing science for school children", category: "science", text: "Explain the science of breathing in simple words for a school child in [your city]. Cover the nose, windpipe, lungs and diaphragm in five short steps, and finish with one simple activity to feel the chest move while breathing." },
  { id: "science-496", title: "How digestion starts in the mouth", category: "science", text: "Explain in simple words how digestion starts in the mouth for a child in [your city]. Describe teeth breaking food, saliva softening it, and how chewing makes swallowing easier. Use an example with a piece of roti." },
  { id: "science-497", title: "What saliva does to food simply", category: "science", text: "Explain in simple words what saliva does to food for a school student in [your city]. Describe how it moistens dry food, starts breaking down starch, and helps the tongue shape food into a soft ball for swallowing." },
  { id: "science-498", title: "How food travels down the food pipe", category: "science", text: "Explain in simple words how food travels down the food pipe for a beginner in [your city]. Describe the wave-like muscle squeezes that push food down, and why food can still reach the stomach even when a person lies down." },
  { id: "science-499", title: "What stomach acid does to food", category: "science", text: "Explain in simple words what stomach acid does to food for a student in [your city]. Describe how acid and stomach juices break food into a soft mix, kill many germs, and prepare the food for the next stage of digestion." },
  { id: "science-500", title: "How the stomach protects itself from acid", category: "science", text: "Explain in simple words how the stomach protects itself from its own acid for a beginner in [your city]. Describe the thick mucus lining, how it is renewed, and what happens in general terms when that lining weakens." },
  { id: "science-501", title: "What the small intestine does daily", category: "science", text: "Explain in simple words what the small intestine does for a school student in [your city]. Describe how food mixes with juices, how nutrients pass through its walls into the blood, and why its long length helps absorption." },
  { id: "science-502", title: "How nutrients enter the blood simply", category: "science", text: "Explain in simple words how nutrients enter the blood after digestion for a beginner in [your city]. Describe the tiny finger-like folds, the blood vessels inside them, and how sugar, protein parts and fats move into the blood." },
  { id: "science-503", title: "What the large intestine does simply", category: "science", text: "Explain in simple words what the large intestine does for a child in [your city]. Describe how it absorbs water, how friendly bacteria live there, and how the leftover food becomes solid waste ready to leave the body." },
  { id: "science-504", title: "How the liver helps digestion simply", category: "science", text: "Explain in simple words how the liver helps digestion for a student in [your city]. Describe how it makes bile, how bile helps break down fats, and how the liver also stores energy and filters blood in general terms." },
  { id: "science-505", title: "What bile does to fatty food", category: "science", text: "Explain in simple words what bile does to fatty food for a beginner in [your city]. Describe how bile breaks large fat drops into tiny drops, like soap breaking oil, so that digestion juices can work on them more easily." },
  { id: "science-506", title: "How the pancreas helps digest food", category: "science", text: "Explain in simple words how the pancreas helps digest food for a student in [your city]. Describe the juices it sends to the small intestine, and how those juices break down starch, protein and fat into smaller parts." },
  { id: "science-507", title: "Why we feel hungry in simple science", category: "science", text: "Explain in simple words why we feel hungry for a child in [your city]. Describe how the empty stomach sends signals, how the brain reads low energy levels, and why the feeling grows stronger when a meal is delayed." },
  { id: "science-508", title: "How the brain knows we are full", category: "science", text: "Explain in simple words how the brain knows we are full after a meal for a beginner in [your city]. Describe signals from the stomach, hormones in general terms, and why eating slowly gives the brain time to notice fullness." },
  { id: "science-509", title: "Why we chew food well science", category: "science", text: "Explain in simple words why chewing food well helps digestion for a school student in [your city]. Describe how small pieces give stomach juices more surface to work on, and how chewing mixes food with saliva from the start." },
  { id: "science-510", title: "How fibre helps the gut simply", category: "science", text: "Explain in simple words how fibre helps the gut in general terms for a reader in [your city]. Name Indian foods rich in fibre, and describe how fibre adds bulk, helps food move along, and feeds friendly gut bacteria." },
  { id: "science-511", title: "What gut bacteria do for us", category: "science", text: "Explain in simple words what friendly gut bacteria do for us for a beginner in [your city]. Describe how they help digest fibre, make some vitamins, and how a varied diet with curd and vegetables supports them in general terms." },
  { id: "science-512", title: "How water helps digestion simply explained", category: "science", text: "Explain in simple words how drinking water helps digestion for a child in [your city]. Describe how water softens food, helps juices flow, and helps the body absorb nutrients and move waste along the gut." },
  { id: "science-513", title: "Why spicy food can cause a burning feeling", category: "science", text: "Explain in simple words why spicy food can cause a burning feeling in general terms for a reader in [your city]. Describe how chilli compounds touch nerve endings, why the brain reads it as heat, and why milk can soothe it." },
  { id: "science-514", title: "How the body turns food into energy", category: "science", text: "Explain in simple words how the body turns food into energy for a school student in [your city]. Describe digestion breaking food down, nutrients entering the blood, and cells using them with oxygen to release energy for work and play." },
  { id: "science-515", title: "What happens to sugar after eating", category: "science", text: "Explain in simple words what happens to sugar after eating for a beginner in [your city]. Describe how sugar enters the blood, how insulin helps cells take it in, in general terms, and how extra sugar is stored." },
  { id: "science-516", title: "How protein helps the body grow", category: "science", text: "Explain in simple words how protein helps the body grow and repair itself for a student in [your city]. Name Indian protein foods like dal, paneer and eggs, and describe how protein parts build muscles and skin." },
  { id: "science-517", title: "Why we need fats in food science", category: "science", text: "Explain in simple words why the body needs some fat in food for a beginner in [your city]. Describe how fat stores energy, helps absorb some vitamins, and protects organs, and why too much fried food is a problem in general terms." },
  { id: "science-518", title: "How vitamins help the body simply", category: "science", text: "Explain in simple words how vitamins help the body for a school student in [your city]. Describe a few common vitamins, the Indian foods that carry them, and how they help eyes, bones, skin and the body defence system." },
  { id: "science-519", title: "What happens when food goes stale", category: "science", text: "Explain in simple words what happens when food goes stale for a child in [your city]. Describe how germs grow on old food, how taste and smell change, and why keeping food covered and cool slows this change in general terms." },
  { id: "science-520", title: "How taste buds sense sweet sour salty", category: "science", text: "Explain in simple words how taste buds sense sweet, sour, salty and bitter for a student in [your city]. Describe the tiny bumps on the tongue, how they send signals to the brain, and how smell adds to the taste of food." },
  { id: "science-521", title: "Why food tastes dull with a cold", category: "science", text: "Explain in simple words why food tastes dull when a person has a cold for a beginner in [your city]. Describe how a blocked nose stops smell signals, and how smell and taste work together to give food its full flavour." },
  { id: "science-522", title: "How the stomach churns food simply", category: "science", text: "Explain in simple words how the stomach churns food for a child in [your city]. Describe the strong muscles squeezing and mixing food with juices, turning a meal into a thick soup before it moves to the small intestine." },
  { id: "science-523", title: "Why we burp after eating fizzy drinks", category: "science", text: "Explain in simple words why we burp after drinking a fizzy drink for a student in [your city]. Describe the gas bubbles in the drink, how they gather in the stomach, and how a burp releases the extra gas." },
  { id: "science-524", title: "How the body stores extra energy", category: "science", text: "Explain in simple words how the body stores extra energy from food for a beginner in [your city]. Describe how the liver stores some energy, how fat stores the rest, and how the body uses these stores between meals." },
  { id: "science-525", title: "What enzymes do in digestion simply", category: "science", text: "Explain in simple words what enzymes do in digestion for a school student in [your city]. Describe them as helpers that speed up breaking food down, and name where different enzymes work, in the mouth, stomach and intestine." },
  { id: "science-526", title: "How babies digest milk simply explained", category: "science", text: "Explain in simple words how a baby digests milk for a new parent in [your city]. Describe how the small stomach handles liquid food, how milk enzymes work, and why a baby needs many small feeds through the day." },
  { id: "science-527", title: "Why eating too fast causes discomfort", category: "science", text: "Explain in simple words why eating too fast can cause discomfort in general terms for a reader in [your city]. Describe swallowed air, poorly chewed food, and how the stomach needs time to mix and move food along." },
  { id: "science-528", title: "How the gut and brain send messages", category: "science", text: "Explain in simple words how the gut and brain send messages to each other for a beginner in [your city]. Describe the nerves linking them, why worry can upset the stomach, and why hunger can change how a person feels." },
  { id: "science-529", title: "What happens to food we cannot digest", category: "science", text: "Explain in simple words what happens to the parts of food we cannot digest for a student in [your city]. Describe how fibre and leftovers pass to the large intestine, feed gut bacteria, and leave the body as waste." },
  { id: "science-530", title: "Simple digestion journey from plate to energy", category: "science", text: "Explain the full journey of food from plate to energy in simple words for a school child in [your city]. Follow one idli through mouth, stomach and intestines, and finish with how the body uses its nutrients for play and study." },
  { id: "science-531", title: "How many bones are in the body", category: "science", text: "Explain in simple words how many bones are in the adult human body for a school student in [your city]. Describe why babies are born with more bones, how some bones join as a child grows, and why the adult count settles near 206." },
  { id: "science-532", title: "What bones are made of simply", category: "science", text: "Explain in simple words what bones are made of for a child in [your city]. Describe the hard outer layer, the spongy inside, calcium and other minerals, and the living cells that keep bone strong and able to repair itself." },
  { id: "science-533", title: "How bones grow in children simply", category: "science", text: "Explain in simple words how bones grow in children for a parent in [your city]. Describe the soft growth areas near bone ends, how new bone forms there, and why good food, play and sleep support growth in general terms." },
  { id: "science-534", title: "How a broken bone heals itself", category: "science", text: "Explain in simple words how a broken bone heals itself for a student in [your city]. Describe how blood clots first, how new soft bone forms, and how the bone slowly hardens again over weeks with rest and care." },
  { id: "science-535", title: "What the skull protects inside simply", category: "science", text: "Explain in simple words what the skull protects for a child in [your city]. Describe the strong curved bones, how they guard the brain, and why the skull has small joints that let it grow in babies." },
  { id: "science-536", title: "How the spine holds the body upright", category: "science", text: "Explain in simple words how the spine holds the body upright for a beginner in [your city]. Describe the stack of small bones, the soft discs between them, and how the spine bends, twists and carries the weight of the head." },
  { id: "science-537", title: "What joints do and how they move", category: "science", text: "Explain in simple words what joints do for a school student in [your city]. Describe how two bones meet, how smooth cartilage and joint fluid help them slide, and why different joints allow different kinds of movement." },
  { id: "science-538", title: "How muscles pull bones to move", category: "science", text: "Explain in simple words how muscles pull bones to move the body for a child in [your city]. Describe muscles attached by tendons, how one muscle pulls while its partner relaxes, and use bending the arm as an example." },
  { id: "science-539", title: "Why calcium matters for strong bones", category: "science", text: "Explain in simple words why calcium matters for strong bones in general terms for a reader in [your city]. Name Indian foods rich in calcium, and describe how bones store calcium and release it when the body needs it." },
  { id: "science-540", title: "How vitamin D helps bones simply", category: "science", text: "Explain in simple words how vitamin D helps bones in general terms for a beginner in [your city]. Describe how sunlight on skin helps the body make vitamin D, and how vitamin D helps the gut absorb calcium from food." },
  { id: "science-541", title: "What bone marrow does every day", category: "science", text: "Explain in simple words what bone marrow does for a student in [your city]. Describe the soft tissue inside large bones, how it makes red cells, white cells and platelets, and why it works non-stop through life." },
  { id: "science-542", title: "How the ribs protect the chest", category: "science", text: "Explain in simple words how the ribs protect the chest for a child in [your city]. Describe the curved bones forming a cage, how they guard the heart and lungs, and how they move gently with every breath." },
  { id: "science-543", title: "Why good posture helps the spine", category: "science", text: "Explain in simple words why good posture helps the spine in general terms for a student in [your city]. Describe how sitting straight spreads weight evenly, and how slouching for long hours can strain back muscles and discs." },
  { id: "science-544", title: "How the knee joint bends and straightens", category: "science", text: "Explain in simple words how the knee joint bends and straightens for a beginner in [your city]. Describe the thigh bone, shin bone, kneecap and ligaments, and how muscles on the front and back of the thigh control the movement." },
  { id: "science-545", title: "What cartilage does in the joints", category: "science", text: "Explain in simple words what cartilage does in the joints for a student in [your city]. Describe the smooth covering on bone ends, how it cushions movement, and why it wears down slowly with age in general terms." },
  { id: "science-546", title: "How bones change with age simply", category: "science", text: "Explain in simple words how bones change with age in general terms for a reader in [your city]. Describe how bones lose some minerals over time, why they can become lighter, and how walking and good food help in general terms." },
  { id: "science-547", title: "Why exercise strengthens bones science", category: "science", text: "Explain in simple words why walking, running and play strengthen bones in general terms for a beginner in [your city]. Describe how the pull of muscles and the weight of the body tell bone cells to build stronger bone." },
  { id: "science-548", title: "How the hand bones help us grip", category: "science", text: "Explain in simple words how the small bones of the hand help us grip for a child in [your city]. Describe the many bones in the fingers and wrist, and how they work with muscles to hold a pencil, a cup or a cricket bat." },
  { id: "science-549", title: "What ligaments and tendons do simply", category: "science", text: "Compare ligaments and tendons in simple words for a school student in [your city]. Explain that ligaments join bone to bone, tendons join muscle to bone, and how both help the body move safely without overstretching." },
  { id: "science-550", title: "How the jaw moves when chewing", category: "science", text: "Explain in simple words how the jaw moves when chewing food for a beginner in [your city]. Describe the jaw joint, the strong chewing muscles, and how the teeth meet to crush food like idli, roti or nuts." },
  { id: "science-551", title: "Why the neck has seven small bones", category: "science", text: "Explain in simple words why the neck has seven small bones for a student in [your city]. Describe how these bones let the head turn, nod and tilt, while protecting the nerves that run from the brain down the spine." },
  { id: "science-552", title: "How the pelvis supports body weight", category: "science", text: "Explain in simple words how the pelvis supports body weight for a beginner in [your city]. Describe the wide bowl-shaped bones, how they join the spine to the legs, and how they protect organs inside the lower body." },
  { id: "science-553", title: "What happens when a muscle cramps", category: "science", text: "Explain in simple words what happens when a muscle cramps in general terms for a reader in [your city]. Describe how a muscle tightens suddenly, why it can hurt, and how gentle stretching and rest usually help it relax again." },
  { id: "science-554", title: "How the shoulder moves in many directions", category: "science", text: "Explain in simple words how the shoulder moves in many directions for a student in [your city]. Describe the ball and socket joint, the muscles around it, and why the shoulder can lift, rotate and reach behind the back." },
  { id: "science-555", title: "Why bones feel light yet strong", category: "science", text: "Explain in simple words why bones feel light yet strong for a child in [your city]. Describe the hollow centre, the spongy inside, and how this design gives strength without making the body too heavy to move." },
  { id: "science-556", title: "How the foot bones help us walk", category: "science", text: "Explain in simple words how the foot bones help us walk for a beginner in [your city]. Describe the arch, the heel and toe bones, and how the foot spreads weight with each step on the road in [your town]." },
  { id: "science-557", title: "What the collar bone does simply", category: "science", text: "Explain in simple words what the collar bone does for a student in [your city]. Describe how it joins the arm to the chest, holds the shoulder out, and why it is one of the bones that breaks most often in falls." },
  { id: "science-558", title: "How stretching helps muscles stay flexible", category: "science", text: "Explain in simple words how gentle stretching helps muscles stay flexible in general terms for a reader in [your city]. Describe how muscles lengthen, how blood flow improves, and why warming up before play matters for the body." },
  { id: "science-559", title: "Why children heal fractures faster simply", category: "science", text: "Explain in simple words why children often heal broken bones faster than adults in general terms for a parent in [your city]. Describe their growing bones, rich blood supply, and active bone cells that repair damage quickly." },
  { id: "science-560", title: "Simple skeleton science for school children", category: "science", text: "Explain the human skeleton in simple words for a school child in [your city]. Cover the skull, spine, ribs, arms and legs in five short steps, and finish with one simple activity to feel the bones in the wrist and elbow." },
  { id: "science-561", title: "How the human eye sees light", category: "science", text: "Explain in simple words how the human eye sees light for a school student in [your city]. Describe light entering through the pupil, the lens focusing it, and the back of the eye turning light into signals for the brain." },
  { id: "science-562", title: "Why the pupil gets bigger in darkness", category: "science", text: "Explain in simple words why the pupil gets bigger in darkness for a child in [your city]. Describe the coloured iris opening the pupil wide to let in more light, and how it shrinks again in bright sunlight." },
  { id: "science-563", title: "How the eye lens focuses near far", category: "science", text: "Explain in simple words how the eye lens focuses on near and far objects for a beginner in [your city]. Describe the lens changing shape, how near objects need a thicker lens, and how the brain reads the clear picture." },
  { id: "science-564", title: "What the retina does in the eye", category: "science", text: "Explain in simple words what the retina does in the eye for a student in [your city]. Describe the light-sensitive layer at the back, its millions of tiny cells, and how it sends picture signals to the brain through the optic nerve." },
  { id: "science-565", title: "How we see colours in simple science", category: "science", text: "Explain in simple words how we see colours for a child in [your city]. Describe the cone cells in the eye, how they sense red, green and blue light, and how the brain mixes these signals to show every colour." },
  { id: "science-566", title: "Why we blink and what tears do", category: "science", text: "Explain in simple words why we blink for a school student in [your city]. Describe how each blink spreads tears over the eye, washes away dust, and keeps the front of the eye smooth and moist for clear sight." },
  { id: "science-567", title: "How two eyes help judge distance", category: "science", text: "Explain in simple words how two eyes help judge distance for a beginner in [your city]. Describe how each eye sees a slightly different view, and how the brain joins the two views to tell how near or far an object is." },
  { id: "science-568", title: "Why eyes water when cutting onions", category: "science", text: "Explain in simple words why eyes water when cutting onions for a reader in [your city]. Describe the gas released from the onion, how it irritates the eye surface, and how tears wash the irritant away to protect the eye." },
  { id: "science-569", title: "What short sight means in simple words", category: "science", text: "Explain in simple words what short sight means in general terms for a beginner in [your city]. Describe how far objects look blurry, why the eye shape causes it, and how glasses help focus light correctly. No personal advice." },
  { id: "science-570", title: "What long sight means in simple words", category: "science", text: "Explain in simple words what long sight means in general terms for a student in [your city]. Describe how near objects look blurry, why the eye focuses light behind the retina, and how glasses help. Give general information only." },
  { id: "science-571", title: "How glasses help the eyes focus", category: "science", text: "Explain in simple words how glasses help the eyes focus for a child in [your city]. Describe how the glass lens bends light before it enters the eye, so the picture lands clearly on the retina instead of in front or behind it." },
  { id: "science-572", title: "Why eyes get tired after screen time", category: "science", text: "Explain in simple words why eyes feel tired after long screen time in general terms for a reader in [your city]. Describe less blinking, the eye muscles holding focus, and why looking away every twenty minutes helps the eyes rest." },
  { id: "science-573", title: "How the eye changes with age", category: "science", text: "Explain in simple words how the eye changes with age in general terms for a beginner in [your city]. Describe how the lens stiffens, why near reading becomes harder, and why regular eye checks matter. No personal advice." },
  { id: "science-574", title: "What vitamin A does for eyesight", category: "science", text: "Explain in simple words what vitamin A does for eyesight in general terms for a student in [your city]. Name Indian foods rich in vitamin A, and describe how it helps the retina sense light, especially in dim light." },
  { id: "science-575", title: "How we see in dim light simply", category: "science", text: "Explain in simple words how we see in dim light for a child in [your city]. Describe the rod cells in the eye, how they sense faint light, and why it takes a few minutes for the eyes to adjust after entering a dark room." },
  { id: "science-576", title: "Why we rub our eyes when sleepy", category: "science", text: "Explain in simple words why people rub their eyes when sleepy for a curious reader in [your city]. Describe tired eye muscles, dry eyes from less blinking, and how rubbing spreads tears but can also irritate the eye surface." },
  { id: "science-577", title: "How eyelashes protect the eyes simply", category: "science", text: "Explain in simple words how eyelashes protect the eyes for a school student in [your city]. Describe how they catch dust, block sweat, and trigger a blink when something touches them, keeping dirt away from the eye surface." },
  { id: "science-578", title: "What colour blindness means simply explained", category: "science", text: "Explain in simple words what colour blindness means in general terms for a beginner in [your city]. Describe how some cone cells work differently, why red and green can look alike, and how people learn to manage it in daily life." },
  { id: "science-579", title: "How the brain turns eye signals into pictures", category: "science", text: "Explain in simple words how the brain turns eye signals into pictures for a student in [your city]. Describe the optic nerve carrying signals, the brain joining both eyes, and how memory helps us recognise faces and objects quickly." },
  { id: "science-580", title: "Why bright light makes us squint", category: "science", text: "Explain in simple words why bright light makes us squint for a child in [your city]. Describe how the pupil shrinks, the eyelids narrow, and how squinting protects the sensitive retina from too much light at once." },
  { id: "science-581", title: "How tears are made and drained", category: "science", text: "Explain in simple words how tears are made and drained for a beginner in [your city]. Describe the tear glands above the eye, how tears wash the surface, and how tiny drains near the nose carry extra tears away." },
  { id: "science-582", title: "What the cornea does for clear vision", category: "science", text: "Explain in simple words what the cornea does for clear vision for a student in [your city]. Describe the clear front window of the eye, how it bends most of the incoming light, and why a scratch on it can blur sight." },
  { id: "science-583", title: "Why reading in dim light strains eyes", category: "science", text: "Explain in simple words why reading in dim light strains the eyes in general terms for a reader in [your city]. Describe how the eye muscles work harder to focus, and why good light and breaks help the eyes feel more comfortable." },
  { id: "science-584", title: "How eye colour is decided simply", category: "science", text: "Explain in simple words how eye colour is decided for a curious child in [your city]. Describe the pigment in the iris, how brown, black and lighter shades form, and why eye colour is decided by family traits." },
  { id: "science-585", title: "What happens when dust enters the eye", category: "science", text: "Explain in simple words what happens when dust enters the eye for a beginner in [your city]. Describe how tears flush it out, why blinking helps, and why rubbing can push the dust deeper and scratch the eye surface." },
  { id: "science-586", title: "How the eyes move together smoothly", category: "science", text: "Explain in simple words how the eyes move together smoothly for a school student in [your city]. Describe the six small muscles on each eye, how the brain moves both eyes as a pair, and why they follow a moving cricket ball together." },
  { id: "science-587", title: "Why we close our eyes when sneezing", category: "science", text: "Explain in simple words why we close our eyes when sneezing for a curious reader in [your city]. Describe the reflex that shuts the eyelids, how it protects the eyes from the strong air burst, and why it happens without thinking." },
  { id: "science-588", title: "How contact lenses sit on the eye", category: "science", text: "Explain in simple words how contact lenses sit on the eye in general terms for a beginner in [your city]. Describe the thin lens floating on tears, how it moves with the eye, and why clean hands matter when handling it." },
  { id: "science-589", title: "Why good sleep helps tired eyes", category: "science", text: "Explain in simple words why good sleep helps tired eyes in general terms for a reader in [your city]. Describe how sleep lets eye muscles rest, how tears refresh the eye surface, and why late nights can leave eyes dry and sore." },
  { id: "science-590", title: "Simple eye science for school children", category: "science", text: "Explain the science of the eye in simple words for a school child in [your city]. Cover the pupil, lens, retina and brain in five short steps, and finish with one simple activity to watch the pupil shrink in bright light." },
  { id: "science-591", title: "How medicines travel through the body", category: "science", text: "Explain in simple words how a swallowed medicine travels through the body for a beginner in [your city]. Describe how it dissolves in the stomach, enters the blood, and reaches the parts where it acts. Give general information only." },
  { id: "science-592", title: "Why medicines have a dose and timing", category: "science", text: "Explain in simple words why medicines have a dose and timing in general terms for a reader in [your city]. Describe how the amount and gap between doses keep the medicine level steady, and why the label instructions matter. No personal advice." },
  { id: "science-593", title: "How pain relief medicines work simply", category: "science", text: "Explain in simple words how common pain relief medicines work in general terms for a beginner in [your city]. Describe how they block pain signals, reduce swelling, and why they do not fix the cause of the pain. No personal advice." },
  { id: "science-594", title: "How antibiotics fight bacteria simply explained", category: "science", text: "Explain in simple words how antibiotics fight bacteria in general terms for a student in [your city]. Describe how they stop bacteria growing or break their walls, and why they do not work on colds caused by viruses. No personal advice." },
  { id: "science-595", title: "Why antibiotics do not cure a cold", category: "science", text: "Explain in simple words why antibiotics do not cure a common cold in general terms for a reader in [your city]. Describe how colds come from viruses, how antibiotics target bacteria only, and why rest and fluids help in general terms." },
  { id: "science-596", title: "How vaccines train the body defence", category: "science", text: "Explain in simple words how vaccines train the body defence for a beginner in [your city]. Describe how a vaccine shows the body a harmless part of a germ, and how memory cells learn to act fast if the real germ arrives." },
  { id: "science-597", title: "Why some medicines are taken before food", category: "science", text: "Explain in simple words why some medicines are taken before food in general terms for a reader in [your city]. Describe how an empty stomach helps absorption, and why other medicines need food to protect the stomach. No personal advice." },
  { id: "science-598", title: "How the liver breaks down medicines", category: "science", text: "Explain in simple words how the liver breaks down medicines for a student in [your city]. Describe how liver enzymes change a medicine into smaller parts, how the body then removes them, and why the dose depends on this process." },
  { id: "science-599", title: "What side effects mean in simple words", category: "science", text: "Explain in simple words what medicine side effects mean in general terms for a beginner in [your city]. Describe how a medicine can affect other body parts, why leaflets list common effects, and why a doctor should be told about them." },
  { id: "science-600", title: "How medicines are tested before sale", category: "science", text: "Explain in simple words how medicines are tested before sale for a curious reader in [your city]. Describe lab tests, small human trials, larger trials, and how safety checks continue even after a medicine reaches shops in India." },
  { id: "science-601", title: "Why children need different medicine doses", category: "science", text: "Explain in simple words why children need different medicine doses in general terms for a parent in [your city]. Describe how body weight, age and growing organs change how a medicine works, and why adult doses are never used for children." },
  { id: "science-602", title: "How syrups tablets and injections differ", category: "science", text: "Compare syrups, tablets and injections in simple words for a beginner in [your city]. Explain how fast each one acts, why children often get syrups, and why some medicines must reach the blood quickly through an injection." },
  { id: "science-603", title: "What expiry dates on medicines mean", category: "science", text: "Explain in simple words what expiry dates on medicines mean for a reader in [your city]. Describe how a medicine can lose strength over time, why storing it in heat or damp speeds this up, and why expired medicines should not be used." },
  { id: "science-604", title: "How the body builds resistance to antibiotics", category: "science", text: "Explain in simple words how bacteria can build resistance to antibiotics in general terms for a student in [your city]. Describe how stopping a course early lets strong bacteria survive, and why full courses matter in general terms." },
  { id: "science-605", title: "Why medicines must be stored safely", category: "science", text: "Explain in simple words why medicines must be stored safely at home in [your city]. Describe how heat, light and damp can spoil them, why they must stay away from children, and how to read the storage line on the pack." },
  { id: "science-606", title: "How fever medicines lower body temperature", category: "science", text: "Explain in simple words how fever medicines lower body temperature in general terms for a beginner in [your city]. Describe how they act on the brain temperature control centre, and why fever itself is the body fighting germs. No personal advice." },
  { id: "science-607", title: "What a generic medicine means simply", category: "science", text: "Explain in simple words what a generic medicine means for a reader in [your city]. Describe how it holds the same active part as a branded medicine, why it often costs less, and how the price in ₹ can differ between brands." },
  { id: "science-608", title: "How insulin helps control blood sugar", category: "science", text: "Explain in simple words how insulin helps control blood sugar in general terms for a beginner in [your city]. Describe how insulin helps cells take in sugar from the blood, and what happens when the body makes too little of it." },
  { id: "science-609", title: "Why some medicines cause sleepiness simply", category: "science", text: "Explain in simple words why some medicines cause sleepiness in general terms for a reader in [your city]. Describe how they calm brain signals, why driving after taking them is risky, and why the leaflet warns about drowsiness. No personal advice." },
  { id: "science-610", title: "How eye drops reach the eye simply", category: "science", text: "Explain in simple words how eye drops work in general terms for a beginner in [your city]. Describe how a drop spreads over the eye surface, how it is absorbed, and why pressing the corner of the eye can slow it draining away." },
  { id: "science-611", title: "What happens if a dose is missed", category: "science", text: "Explain in simple words what happens in general terms if a medicine dose is missed for a reader in [your city]. Describe how the medicine level falls, why doubling the next dose is usually wrong, and why the leaflet or doctor guidance matters." },
  { id: "science-612", title: "How inhalers deliver medicine to lungs", category: "science", text: "Explain in simple words how an inhaler delivers medicine to the lungs in general terms for a student in [your city]. Describe the fine mist, how breathing it in carries it deep into the airways, and why it acts faster there." },
  { id: "science-613", title: "Why medicines and alcohol do not mix", category: "science", text: "Explain in simple words why medicines and alcohol do not mix in general terms for a reader in [your city]. Describe how alcohol changes how the liver handles a medicine, and why the mix can raise side effects. No personal advice." },
  { id: "science-614", title: "How the kidney removes old medicines", category: "science", text: "Explain in simple words how the kidney removes old medicines from the body for a student in [your city]. Describe how the blood carries medicine leftovers to the kidneys, how they filter them out, and how they leave in urine." },
  { id: "science-615", title: "What a medicine leaflet tells you simply", category: "science", text: "Explain in simple words how to read a medicine leaflet for a beginner in [your city]. Cover the use, dose, timing, storage and common side effects sections, and explain why the leaflet is general information, not personal advice." },
  { id: "science-616", title: "How skin creams work on the surface", category: "science", text: "Explain in simple words how skin creams work in general terms for a reader in [your city]. Describe how a cream stays on the skin surface, how its active part sinks into the top layers, and why it acts mainly where it is applied." },
  { id: "science-617", title: "Why some medicines need a prescription", category: "science", text: "Explain in simple words why some medicines need a prescription in India in general terms for a beginner in [your city]. Describe how stronger medicines need a doctor check, and why selling them without one can be unsafe for the buyer." },
  { id: "science-618", title: "How the body gets used to a medicine", category: "science", text: "Explain in simple words how the body can get used to a medicine over time in general terms for a reader in [your city]. Describe how the same dose can feel weaker, and why a doctor may change the dose or medicine. No personal advice." },
  { id: "science-619", title: "What placebos are in medicine trials", category: "science", text: "Explain in simple words what a placebo is in medicine trials for a curious student in [your city]. Describe a harmless dummy pill, how trials compare it with a real medicine, and why this helps show whether the medicine truly works." },
  { id: "science-620", title: "How oral rehydration salts help the body", category: "science", text: "Explain in simple words how oral rehydration salts help the body in general terms for a reader in [your city]. Describe how they replace water and salts lost in loose motions, and why clean water and the right mix matter. No personal advice." },
  { id: "science-621", title: "Why medicines come in different strengths", category: "science", text: "Explain in simple words why the same medicine comes in different strengths in general terms for a beginner in [your city]. Describe how age, weight and the illness change the dose needed, and why the pack shows the strength clearly." },
  { id: "science-622", title: "How the body reacts to a new medicine", category: "science", text: "Explain in simple words how the body reacts to a new medicine in general terms for a reader in [your city]. Describe how the body absorbs it, how effects build over days, and why new rashes or swelling should be reported to a doctor." },
  { id: "science-623", title: "What happens to medicines after swallowing", category: "science", text: "Explain in simple words what happens to a tablet after swallowing for a student in [your city]. Describe how it dissolves in stomach juices, how its parts enter the blood, and how the liver and kidneys later clear the leftovers." },
  { id: "science-624", title: "How first aid creams protect a cut", category: "science", text: "Explain in simple words how a first aid cream protects a small cut in general terms for a beginner in [your city]. Describe how it forms a barrier, keeps germs out, and helps the skin heal, and why deep cuts need a doctor." },
  { id: "science-625", title: "Simple medicines science for school children", category: "science", text: "Explain how medicines work in simple words for a school child in [your city]. Cover swallowing a tablet, how it travels in blood, how vaccines train defence, and finish with why medicines are always taken only as a doctor says." },
  { id: "science-626", title: "Explain a lunar eclipse to a child", category: "science", text: "Explain a lunar eclipse in simple words a [10-year-old] can understand. Tell me why the moon turns red, when it happens, and how to watch it safely from [your home]. Add a small drawing task to show the Sun, Earth, and moon in a line." },
  { id: "science-627", title: "How the moon causes tides", category: "science", text: "Explain in simple words how the moon pulls the sea and causes high tide and low tide. Use an example from [a beach city / Chennai / Mumbai] and tell me why tides are stronger on full moon and new moon days." },
  { id: "science-628", title: "Why we see only one side of the moon", category: "science", text: "Explain why we always see the same face of the moon from Earth. Use a simple spinning and walking example a [school student] can try at home, and tell me what the far side of the moon is like." },
  { id: "science-629", title: "Full moon and new moon explained", category: "science", text: "Explain to [my 10-year-old child] the difference between a full moon and a new moon in simple words. Tell me how many days apart they are, why the moon looks bright on a full moon night, and why we cannot see it on a new moon night." },
  { id: "science-630", title: "Why we see only one moon face", category: "science", text: "Explain in simple words why we always see the same face of the moon from Earth. Tell me how the moon spins once for each trip around us, what the far side looks like, and why [astronauts] were the first people to see it." },
  { id: "science-631", title: "Moon phases calendar for a month", category: "science", text: "Make a simple moon phases calendar for [this month / next month] for [your city]. For each week, tell me the moon phase, the date it changes, and one easy thing to look for in the sky that week." },
  { id: "science-632", title: "Why the moon looks bigger near the horizon", category: "science", text: "Explain why the moon looks bigger when it is low near the horizon and smaller when it is high in the sky. Tell me if it really changes size, and give a simple test I can do with [my thumb / a coin] to check." },
  { id: "science-633", title: "How people first landed on the moon", category: "science", text: "Tell me the story of the first moon landing in simple words. Who went, in which year, how long the journey took, and what the astronauts did on the moon. Keep it short and easy for a [school student] to retell." },
  { id: "science-634", title: "Why there is no air on the moon", category: "science", text: "Explain to [a Class 6 student] why the moon has almost no air to breathe. Tell me what that means for sound, for walking, and for the footprints left by astronauts, and why the sky looks black on the moon even in the daytime." },
  { id: "science-635", title: "Moon and the Hindu calendar", category: "science", text: "Explain how the moon is used in the Indian lunar calendar. Tell me what amavasya and pournami mean, how festival dates like [Diwali / Karthigai Deepam] are fixed, and why the same festival falls on a different English date each year." },
  { id: "science-636", title: "Why the moon has craters", category: "science", text: "Explain to [a 9-year-old school child] why the moon has so many round craters on its surface. Tell me what made them, why they never fade away like marks on Earth, and what we can see in the biggest craters with a simple pair of binoculars." },
  { id: "science-637", title: "How far is the moon from Earth", category: "science", text: "Tell me how far the moon is from Earth in kilometres, and help me picture that distance with everyday examples like train journeys and [flights from Chennai to Delhi]. Also tell me how long light and a rocket take to reach the moon." },
  { id: "science-638", title: "Why the sun rises in the east", category: "science", text: "Explain why the sun always rises in the east and sets in the west. Use the spinning Earth to explain it in simple words, and tell me why sunrise time changes through the year in [your city]." },
  { id: "science-639", title: "Why the sun looks red at sunset", category: "science", text: "Explain why the sun looks red or orange at sunset but white at noon. Use simple words about sunlight travelling through the air, and tell me why the sky looks most colourful just after sunset on a [dusty / cloudy] evening." },
  { id: "science-640", title: "How the sun gives us heat and light", category: "science", text: "Explain in simple words to [my younger brother] how the sun makes heat and light. Tell me what is burning inside the sun, how far its light travels to reach us, and why a cloudy day still feels bright even when we cannot see the sun." },
  { id: "science-641", title: "Why we should not look at the sun directly", category: "science", text: "Explain why looking directly at the sun can hurt our eyes, even for a few seconds. Tell me what part of sunlight is harmful, and list safe ways to watch the sun, like using [certified solar glasses / a pinhole projector]." },
  { id: "science-642", title: "Solar energy for my home explained", category: "science", text: "Explain how solar panels turn sunlight into electricity for a home in [your city]. Tell me in simple words how the panels work, what happens on a cloudy day, and what a family should check before installing them." },
  { id: "science-643", title: "Why summer days are longer than winter days", category: "science", text: "Explain why days are longer in summer and shorter in winter in India. Use the tilt of the Earth to explain it simply, and tell me how much the daylight changes between June and December in [your city]." },
  { id: "science-644", title: "How shadows change through the day", category: "science", text: "Explain why shadows are long in the morning, short at noon, and long again in the evening. Give me a simple activity to measure my shadow at [8 am / 12 noon / 5 pm] and record what changes and why." },
  { id: "science-645", title: "What are sunspots and solar flares", category: "science", text: "Explain to [a beginner in [your city]] sunspots and solar flares in simple words. Tell me what they are, why they appear on the sun, whether they affect life on Earth, and why scientists watch them with special telescopes." },
  { id: "science-646", title: "Why the sun is a star", category: "science", text: "Explain to [my daughter in Class 5] why the sun is a star just like the ones we see at night. Tell me why it looks so much bigger and brighter than other stars, and how far away the next nearest star is from us." },
  { id: "science-647", title: "How old is the sun", category: "science", text: "Tell me, for [a school project], how old the sun is and how scientists worked that out. Explain in simple words what will happen to the sun over a very long time, and why we do not need to worry about it in our lifetime." },
  { id: "science-648", title: "Why the sky is blue in daytime", category: "science", text: "Explain to [my 12-year-old nephew] why the sky looks blue during the day. Use simple words about sunlight and tiny bits in the air, and tell me why the sky looks darker blue high up in the hills and pale near the sea." },
  { id: "science-649", title: "Why seasons change through the year", category: "science", text: "Explain why we have summer, rain, and winter in India in simple words for a [10-year-old]. Tell me how the tilt of the Earth changes the sunlight, why days are longer in summer, and one simple activity to track the seasons at home." },
  { id: "science-650", title: "Why different countries have different times", category: "science", text: "Explain time zones in simple words. Tell me why it is morning in India when it is night in [America / London], and how to work out the time in [another country] when it is [10 am] here." },
  { id: "science-651", title: "Why we have seasons on Earth", category: "science", text: "Explain to [my 10-year-old child] why Earth has seasons. Tell me how the tilt of the Earth causes summer and winter, why seasons are opposite in Australia and India, and why places near the equator have almost the same weather all year." },
  { id: "science-652", title: "Summer in India explained", category: "science", text: "Explain why Indian summers are so hot, especially in [Delhi / Chennai / Nagpur]. Tell me which months are hottest, why the sun feels stronger at noon, and give [five] simple tips to stay cool and safe in the heat." },
  { id: "science-653", title: "Why winters are colder in North India", category: "science", text: "Explain why North India feels much colder in winter than South India. Tell me about the sun's angle, cold winds, and fog, and why [Delhi] gets foggy mornings while [Chennai] stays warm in December." },
  { id: "science-654", title: "What is the spring equinox", category: "science", text: "Explain what an equinox is in simple words. Tell me what happens on the spring equinox, why day and night are almost equal that day, and on which dates equinoxes fall in [this year]." },
  { id: "science-655", title: "What is the summer solstice", category: "science", text: "Explain to [a Class 6 student] the summer solstice in simple words. Tell me why it is the longest day of the year in India, on which date it falls, and why the sun rises earliest and sets latest around that day." },
  { id: "science-656", title: "What is the winter solstice", category: "science", text: "Explain to [a 9-year-old school child] the winter solstice in simple words. Tell me why it is the shortest day of the year, on which date it falls in India, and why days slowly start getting longer after that date." },
  { id: "science-657", title: "Six seasons in India explained", category: "science", text: "Explain the six traditional Indian seasons in simple words: vasant, grishma, varsha, sharad, hemant and shishir. Tell me which months each one covers and what the weather is like in [your state] during each season." },
  { id: "science-658", title: "Why monsoon season matters to India", category: "science", text: "Explain why the monsoon is so important for India. Tell me how it helps farmers, fills our rivers and wells, and what happens when the monsoon is weak or late in [your state]." },
  { id: "science-659", title: "How seasons change what we wear and eat", category: "science", text: "Explain how seasons change our food and clothes in India. Give examples of what people eat and wear in summer, monsoon and winter in [your city], and why seasonal fruits like mangoes come only in summer." },
  { id: "science-660", title: "Why leaves change colour in autumn", category: "science", text: "Explain why leaves turn yellow, orange and red in autumn in cold countries. Tell me why most Indian trees stay green all year, and which Indian trees do change colour or shed their leaves in [winter / summer]." },
  { id: "science-661", title: "What is the water cycle", category: "science", text: "Explain the water cycle in simple words: how water from the sea, rivers and land rises as vapour, forms clouds, falls as rain, and flows back to the sea. Draw it out in words a [school student] can copy into a notebook." },
  { id: "science-662", title: "Why does it rain", category: "science", text: "Explain to [my younger brother] why it rains in simple words. Tell me how clouds form, why tiny water drops join together and fall, and why some clouds give heavy rain while others pass by without a single drop." },
  { id: "science-663", title: "Why the monsoon comes to India every year", category: "science", text: "Explain why the southwest monsoon reaches India every June. Tell me about the winds from the sea, why Kerala gets rain first, and how the monsoon slowly moves up to [Delhi / Rajasthan] over the following weeks." },
  { id: "science-664", title: "Why some places get more rain than others", category: "science", text: "Explain why [Cherrapunji / Mawsynram] gets very heavy rain while [Rajasthan / Ladakh] gets very little. Tell me how hills, sea winds and location decide rainfall, and give two more examples from India." },
  { id: "science-665", title: "What are clouds made of", category: "science", text: "Explain to [a beginner in [your city]] what clouds are made of in simple words. Tell me why clouds float in the sky, why some are white and fluffy while others are dark and heavy, and what a dark cloud tells us about coming rain." },
  { id: "science-666", title: "Different types of clouds explained", category: "science", text: "Explain the main types of clouds in simple words: cirrus, cumulus, stratus and nimbus. Tell me what each one looks like, how high it floats, and which type brings rain, using examples a [school student] can spot from a window." },
  { id: "science-667", title: "Why it rains more in the hills", category: "science", text: "Explain why hill places like [Ooty / Munnar / Darjeeling] get more rain than nearby plains. Tell me how moist air rises over hills, cools down and forms rain, and why the other side of a hill often stays dry." },
  { id: "science-668", title: "What is a thunderstorm", category: "science", text: "Explain to [my daughter in Class 5] what a thunderstorm is in simple words. Tell me how thunder and lightning are made, why lightning comes before thunder, and what to do to stay safe when a thunderstorm starts while you are outside." },
  { id: "science-669", title: "Why lightning strikes and how to stay safe", category: "science", text: "Explain why lightning strikes the ground during a storm. Tell me which places are dangerous, like tall trees and open fields, and give [five] simple safety rules to follow at home and outside during lightning." },
  { id: "science-670", title: "How rain is measured in India", category: "science", text: "Explain how rainfall is measured in millimetres. Tell me what a rain gauge is, how the weather office uses it, and what it means when the news says [your city] received [50 mm] of rain in a day." },
  { id: "science-671", title: "Why rainwater is good for plants", category: "science", text: "Explain why plants grow well after rain. Tell me what rainwater carries from the air, how it softens dry soil, and why farmers in [your state] wait for the first monsoon rain before sowing seeds." },
  { id: "science-672", title: "How to collect rainwater at home", category: "science", text: "Explain how rainwater harvesting works for a home in [your city]. Tell me in simple words how roof water is collected, filtered and stored or sent into the ground, and why it helps when wells run low in summer." },
  { id: "science-673", title: "Why floods happen after heavy rain", category: "science", text: "Explain why heavy rain causes floods in cities like [Chennai / Mumbai]. Tell me how blocked drains, concrete roads and full lakes make flooding worse, and what families should keep ready during the rainy season." },
  { id: "science-674", title: "What is a cyclone", category: "science", text: "Explain to [a Class 5 student] what a cyclone is in simple words. Tell me how it forms over the warm sea, why it brings strong winds and heavy rain, and what people living near the coast should do when a cyclone warning is given." },
  { id: "science-675", title: "Why the Bay of Bengal gets more cyclones", category: "science", text: "Explain why the Bay of Bengal sees more cyclones than the Arabian Sea. Tell me about warm sea water, wind patterns and the shape of the coast, and name [two] cyclones that affected [Tamil Nadu / Odisha / Andhra Pradesh]." },
  { id: "science-676", title: "How weather forecasts are made", category: "science", text: "Explain to [my 12-year-old nephew] how the weather office predicts rain and temperature. Tell me about satellites, radars and weather balloons in simple words, and why forecasts are sometimes wrong even with all this technology." },
  { id: "science-677", title: "Why the weather changes so fast", category: "science", text: "Explain why the weather can change from sunny to rainy in one hour. Tell me how moving air, clouds and wind cause quick changes, and why mornings in [your city] feel different from afternoons in the monsoon." },
  { id: "science-678", title: "What is humidity and why we feel sticky", category: "science", text: "Explain humidity in simple words. Tell me why we feel sticky and sweaty on a humid day in [Chennai / Mumbai / Kolkata], why sweat dries slowly, and how a fan or cooler helps us feel better." },
  { id: "science-679", title: "Why mornings are foggy in winter", category: "science", text: "Explain why fog forms on cold winter mornings. Tell me how tiny water drops hang in the air, why fog is thick near rivers and fields, and why trains and flights get delayed on foggy days in [North India]." },
  { id: "science-680", title: "What is dew and how it forms", category: "science", text: "Explain what dew is and how it forms on grass and leaves overnight. Tell me why dew appears on clear cold nights and not on cloudy nights, and give a simple morning activity to find dew in [your garden / a park]." },
  { id: "science-681", title: "Why hail falls during a storm", category: "science", text: "Explain to [my 10-year-old child] what hail is and why balls of ice fall from the sky during a storm. Tell me how they grow inside a cloud, why hail can damage crops and cars, and how farmers protect their fields from hail." },
  { id: "science-682", title: "Rain in the desert explained", category: "science", text: "Explain to [a Class 6 student] why deserts like the Thar get so little rain. Tell me how dry air and wind patterns keep rain away, how desert plants and animals survive, and what happens on the rare day when it does rain there." },
  { id: "science-683", title: "Why rain smells fresh", category: "science", text: "Explain why the first rain after a dry spell smells so fresh and earthy. Tell me in simple words what causes that smell, why we notice it most after summer, and why the smell is stronger in [a village / a garden] than on a busy road." },
  { id: "science-684", title: "How rain fills our lakes and wells", category: "science", text: "Explain how rain fills lakes, rivers and underground water. Tell me why some rain flows away while some soaks into the ground, and why saving rainwater matters for a city like [your city] in summer." },
  { id: "science-685", title: "Why the northeast monsoon matters for Tamil Nadu", category: "science", text: "Explain the northeast monsoon and why it matters so much for Tamil Nadu. Tell me when it arrives, how it is different from the southwest monsoon, and which months bring the most rain to [Chennai / Madurai / Coimbatore]." },
  { id: "science-686", title: "What causes an earthquake", category: "science", text: "Explain to [a 9-year-old school child] what causes an earthquake in simple words. Tell me about the giant rock plates under the Earth, how they slowly move and suddenly slip, and why that shaking reaches the surface where we live." },
  { id: "science-687", title: "What is the Richter scale", category: "science", text: "Explain to [my younger brother] the Richter scale in simple words. Tell me how it measures the strength of an earthquake, what the numbers mean from small to big, and why a small rise in the number means a much stronger shake." },
  { id: "science-688", title: "Why some places have more earthquakes", category: "science", text: "Explain why places like [Japan / Nepal / the Himalayas] have more earthquakes than [South India]. Tell me how the edges of rock plates cause quakes, and why some parts of India are marked as higher risk zones." },
  { id: "science-689", title: "What to do during an earthquake", category: "science", text: "Give me simple steps to stay safe during an earthquake at home, at school and outside. Tell me what to do in the first few seconds, where to take cover, and what not to do, like running to a lift or standing near windows, to share with [my children]." },
  { id: "science-690", title: "How scientists detect earthquakes early", category: "science", text: "Explain to [my daughter in Class 5] how scientists detect earthquakes with instruments called seismographs. Tell me in simple words how the machines feel the shaking, how warnings are sent, and why we still cannot predict the exact day of a quake." },
  { id: "science-691", title: "What is a tsunami", category: "science", text: "Explain to [a Class 5 student] what a tsunami is in simple words. Tell me how an earthquake under the sea can push up a giant wave, why the sea sometimes pulls back before it arrives, and what people near the coast should do on a warning." },
  { id: "science-692", title: "Why buildings fall in earthquakes", category: "science", text: "Explain to [my 12-year-old nephew] why some buildings fall during an earthquake while others stay standing. Tell me about shaking, weak walls and soft ground in simple words, and what makes a building safer in an earthquake zone." },
  { id: "science-693", title: "Earthquake safety kit for my home", category: "science", text: "Help me make a simple earthquake safety kit for my home in [your city]. List what to keep in it, where to store it, and what each family member should know, so we are ready even if a quake happens at night." },
  { id: "science-694", title: "Why aftershocks follow a big earthquake", category: "science", text: "Explain to [my 10-year-old child] what aftershocks are and why they follow a big earthquake. Tell me how long they can go on, why they are usually weaker, and why people should still stay careful after the main shaking stops." },
  { id: "science-695", title: "How the Earth is made inside", category: "science", text: "Explain to [a Class 6 student] the inside of the Earth in simple words: the crust, the mantle and the core. Tell me what each layer is like, which one is hottest, and how the moving layers below us cause earthquakes and volcanoes." },
  { id: "science-696", title: "What are tectonic plates", category: "science", text: "Explain to [a 9-year-old school child] tectonic plates in simple words. Tell me that the Earth's surface is made of giant moving pieces, how slowly they move each year, and how their pushing and pulling builds mountains and causes earthquakes." },
  { id: "science-697", title: "Why volcanoes erupt", category: "science", text: "Explain why volcanoes erupt in simple words. Tell me about hot melted rock under the ground, how pressure builds up, and what comes out during an eruption, using [a famous volcano] as an example." },
  { id: "science-698", title: "Why the Himalayas are still growing", category: "science", text: "Explain why the Himalayas are still growing taller every year. Tell me how two rock plates pushing together raised the mountains, how fast they grow, and why the same pushing causes earthquakes in [Nepal / North India]." },
  { id: "science-699", title: "How old is the Earth", category: "science", text: "Tell me, for [a beginner in my town], how old the Earth is and how scientists found out. Explain in simple words how rocks and fossils give clues about the Earth's age, and what the Earth looked like when it was very young." },
  { id: "science-700", title: "Why the Earth is round", category: "science", text: "Explain why the Earth is round and not flat. Give me simple proofs a [school student] can understand, like ships disappearing over the horizon, the round shadow during a lunar eclipse, and photos from space." },
  { id: "science-701", title: "What is at the North and South Poles", category: "science", text: "Explain to [a beginner in [your city]] what the North Pole and South Pole are like. Tell me about ice, cold, polar days and polar nights, which animals live there, and why the South Pole has land under the ice but the North Pole does not." },
  { id: "science-702", title: "Why the equator is hot all year", category: "science", text: "Explain why places near the equator stay hot all year. Tell me how the sun shines straight down there, why there is little change between seasons, and name [two] countries that lie on the equator." },
  { id: "science-703", title: "How the planets got their names", category: "science", text: "Tell me, for [a school science project], how the planets got their names in simple words. Explain which planets are named after Roman gods, what the Indian names like Mangal and Shukra mean, and which planet is named after the god of war." },
  { id: "science-704", title: "The eight planets in order", category: "science", text: "List the eight planets in order from the sun and give one easy fact about each that a [school student] can remember. Include a simple trick to remember the order, and tell me why Pluto is no longer called a planet." },
  { id: "science-705", title: "Why Mercury is so hot and cold", category: "science", text: "Explain to [a Class 5 student] why Mercury is boiling hot in the daytime and freezing cold at night. Tell me how its closeness to the sun and its lack of air cause this, and why a day on Mercury lasts so long." },
  { id: "science-706", title: "Why Venus is the hottest planet", category: "science", text: "Explain to [my 12-year-old nephew] why Venus is the hottest planet even though Mercury is closer to the sun. Tell me about its thick cloudy air that traps heat, why its surface is too hot for rain, and why we call Venus the morning star." },
  { id: "science-707", title: "Why Mars looks red", category: "science", text: "Explain to [my 10-year-old child] why Mars looks red in the night sky. Tell me about the rusty dust on its surface, its deserts and tall volcanoes, and why scientists are so interested in finding water on Mars." },
  { id: "science-708", title: "Could people live on Mars one day", category: "science", text: "Explain to [a Class 6 student] what people would need to live on Mars. Tell me about its thin air, cold nights and lack of water, and what kind of homes, food and clothes settlers would need to survive there." },
  { id: "science-709", title: "Why Jupiter is the biggest planet", category: "science", text: "Explain to [a 9-year-old school child] why Jupiter is the biggest planet in our solar system. Tell me how many Earths could fit inside it, what its giant storm called the Great Red Spot is, and why it has so many moons." },
  { id: "science-710", title: "Why Saturn has rings", category: "science", text: "Explain to [my younger brother] why Saturn has beautiful rings around it. Tell me what the rings are made of, how wide and thin they are, and why the other big planets have rings too, even though we cannot see them easily." },
  { id: "science-711", title: "Uranus the planet that rolls on its side", category: "science", text: "Explain to [a beginner in [your city]] why Uranus is called the sideways planet. Tell me how it spins on its side, why it looks blue-green, and how its strange tilt gives each pole very long days and nights." },
  { id: "science-712", title: "Neptune the farthest planet", category: "science", text: "Explain to [my daughter in Class 5] what Neptune is like, the farthest planet from the sun. Tell me why it looks deep blue, how strong its winds are, and how long one year lasts on Neptune compared with one year on Earth." },
  { id: "science-713", title: "How big is the solar system", category: "science", text: "Help me, for [a Class 6 student], picture how big the solar system is. Use everyday examples like a football ground to show the distances between planets, and tell me how long light from the sun takes to reach Neptune." },
  { id: "science-714", title: "What is the difference between a planet and a star", category: "science", text: "Explain to [my 12-year-old nephew] the difference between a planet and a star in simple words. Tell me why planets shine with borrowed light while stars make their own, and how to tell them apart when looking at the night sky." },
  { id: "science-715", title: "Why planets do not twinkle like stars", category: "science", text: "Explain why stars twinkle but planets shine steadily in the night sky. Tell me how the air above us bends starlight, and give a simple way to spot a planet on a clear night in [your city]." },
  { id: "science-716", title: "What is an asteroid", category: "science", text: "Explain to [my 10-year-old child] what asteroids are in simple words. Tell me where most of them float between Mars and Jupiter, what they are made of, and why scientists watch the ones that come near Earth." },
  { id: "science-717", title: "What is a comet", category: "science", text: "Explain to [a Class 6 student] what a comet is and why it has a glowing tail. Tell me what it is made of, why the tail appears only near the sun, and how often a famous comet like Halley's comet visits us." },
  { id: "science-718", title: "What is a shooting star", category: "science", text: "Explain to [a 9-year-old school child] what a shooting star really is. Tell me why we see a bright streak in the sky, what burns up in the air, and why we see more of them during a meteor shower on certain nights of the year." },
  { id: "science-719", title: "How many moons does each planet have", category: "science", text: "Tell me, for [my child's science homework], how many moons each planet has, from Mercury with none to Saturn with over a hundred. Explain in simple words why big planets have more moons, and name the biggest moon in our solar system." },
  { id: "science-720", title: "Why the Earth is the only planet with life", category: "science", text: "Explain to [a beginner in [your city]] why Earth is the only planet we know that has life. Tell me about water, air and the right temperature, and why the other planets are too hot, too cold or too dry for living things." },
  { id: "science-721", title: "How long is a year on each planet", category: "science", text: "Tell me, for [a beginner in my town], how long a year lasts on each planet, from 88 days on Mercury to 165 years on Neptune. Explain why planets farther from the sun take longer to go around it, using a simple race track example." },
  { id: "science-722", title: "How long is a day on each planet", category: "science", text: "Tell me, for [my younger brother], how long a day lasts on each planet, from about 10 hours on Jupiter to 243 Earth days on Venus. Explain why planets spin at different speeds and what that means for their weather and temperature." },
  { id: "science-723", title: "What is the Milky Way galaxy", category: "science", text: "Explain to [my 12-year-old nephew] what the Milky Way galaxy is in simple words. Tell me that our sun is one star among billions, what the milky band in the night sky is, and where we can see it best away from city lights in India." },
  { id: "science-724", title: "How many stars are in the sky", category: "science", text: "Explain to [my 10-year-old child] how many stars we can see with our eyes on a clear night and how many are in our galaxy. Tell me why city lights hide most stars, and where in India the night sky is darkest and clearest." },
  { id: "science-725", title: "What is a constellation", category: "science", text: "Explain what a constellation is in simple words. Tell me how people joined stars into pictures like the Great Bear and Orion, and give a simple guide to finding [Orion / the Plough] in the sky this month." },
  { id: "science-726", title: "How to find the Pole Star", category: "science", text: "Give me simple steps to find the Pole Star on a clear night. Tell me how to use the Great Bear to point to it, why it stays in the same place all night, and how travellers used it to find north, to share with [my class]." },
  { id: "science-727", title: "Why the stars come out only at night", category: "science", text: "Explain to [a 9-year-old school child] why we see stars only at night even though they shine all day. Tell me how sunlight hides them, why they appear slowly after sunset, and why the moon and bright planets appear first." },
  { id: "science-728", title: "What is a solar eclipse", category: "science", text: "Explain to [my younger brother] what a solar eclipse is in simple words. Tell me how the moon comes between the Earth and the sun, why the day turns dark for a few minutes, and why a solar eclipse does not happen every month." },
  { id: "science-729", title: "What is a lunar eclipse", category: "science", text: "Explain to [a beginner in [your city]] what a lunar eclipse is in simple words. Tell me how the Earth comes between the sun and the moon, why the moon turns red, and why a lunar eclipse can be seen from many places at once." },
  { id: "science-730", title: "Why the moon turns red during an eclipse", category: "science", text: "Explain to [my daughter in Class 5] why the moon looks red during a total lunar eclipse. Tell me how sunlight bends through the Earth's air to reach the moon, and why people call it a blood moon." },
  { id: "science-731", title: "How to watch a solar eclipse safely", category: "science", text: "Give me safe ways to watch a solar eclipse. Tell me why we must never look at the sun directly, how to use certified eclipse glasses and a pinhole projector, and what to check before the eclipse day in [your city]." },
  { id: "science-732", title: "When is the next eclipse in India", category: "science", text: "Tell me when the next solar and lunar eclipses will be visible from India. Give the dates, whether each one is total or partial, and simple tips to plan watching it with family in [your city]." },
  { id: "science-733", title: "Why eclipses do not happen every month", category: "science", text: "Explain to [a Class 5 student] why we do not get an eclipse every month even though the moon goes around the Earth each month. Tell me about the tilted path of the moon and why the sun, moon and Earth line up only sometimes." },
  { id: "science-734", title: "Solar eclipse myths and facts", category: "science", text: "Separate myths from facts about solar eclipses. Tell me which common beliefs are wrong, like food turning poisonous, and what science really says, so I can explain it simply to [my family / my children]." },
  { id: "science-735", title: "What happens to animals during an eclipse", category: "science", text: "Explain to [my 12-year-old nephew] what animals do during a solar eclipse. Tell me why birds go quiet, why cows may head home, and what scientists have noticed about animal behaviour when the sky suddenly turns dark in the daytime." },
  { id: "science-736", title: "How ancient Indians predicted eclipses", category: "science", text: "Tell me, for [a Class 6 student], how ancient Indian astronomers like Aryabhata understood and predicted eclipses. Explain in simple words what they knew about the Earth, moon and sun, and why their work was so remarkable for that time." },
  { id: "science-737", title: "Why the sun and moon look the same size", category: "science", text: "Explain to [a Class 6 student] why the sun and moon look almost the same size in the sky even though the sun is much bigger. Tell me how distance makes this happen, and why this perfect match makes a total solar eclipse possible." },
  { id: "science-738", title: "How long does a total solar eclipse last", category: "science", text: "Explain to [a 9-year-old school child] why a total solar eclipse lasts only a few minutes. Tell me how the moon's shadow moves across the Earth, why some places see it longer than others, and what people see during those few minutes." },
  { id: "science-739", title: "What is the diamond ring effect", category: "science", text: "Explain to [my younger brother] the diamond ring effect seen during a total solar eclipse. Tell me why a bright ring of light appears just before and after totality, and why it is one of the most beautiful moments of an eclipse." },
  { id: "science-740", title: "How to photograph a lunar eclipse", category: "science", text: "Give me simple tips to photograph a lunar eclipse with a phone. Tell me when to start, how to keep the phone steady, which settings to use, and how to take a few good shots without missing the eclipse itself, to share with [my family]." },
  { id: "science-741", title: "Why we get high tide during full moon", category: "science", text: "Explain why tides are higher on full moon and new moon days. Tell me how the sun and moon pull together on those days, what a spring tide is, and why fishermen in [a coastal town] plan around the tides." },
  { id: "science-742", title: "How the moon helps farmers in India", category: "science", text: "Explain how farmers in India use the moon to plan sowing and harvesting. Tell me about lunar phases, traditional farming wisdom, and why some farmers still check the moon calendar before planting [paddy / vegetables]." },
  { id: "science-743", title: "Why the moon looks yellow sometimes", category: "science", text: "Explain to [my daughter in Class 5] why the moon sometimes looks yellow, orange or even red. Tell me how dust and smoke in the air change its colour, and why a harvest moon low in the sky looks bigger and more golden." },
  { id: "science-744", title: "What is a supermoon", category: "science", text: "Explain what a supermoon is in simple words. Tell me why the moon looks bigger and brighter on that night, how often it happens, and when the next supermoon will be visible from [your city]." },
  { id: "science-745", title: "What is a blue moon", category: "science", text: "Explain to [a Class 5 student] what a blue moon is and why it is not really blue. Tell me how two full moons can fall in one month, how often it happens, and why people say once in a blue moon." },
  { id: "science-746", title: "How astronauts live on the space station", category: "science", text: "Explain to [my 12-year-old nephew] how astronauts live on the International Space Station. Tell me how they eat, sleep and exercise without gravity, how they get water and air, and what a normal day looks like for them up in space." },
  { id: "science-747", title: "Why astronauts float in space", category: "science", text: "Explain to [my 10-year-old child] why astronauts float inside a space station. Tell me in simple words that they are falling around the Earth, why there is no up or down for them, and how they move from one room to another." },
  { id: "science-748", title: "How rockets escape Earth", category: "science", text: "Explain to [a Class 6 student] how a rocket escapes the Earth's pull in simple words. Tell me how burning fuel pushes the rocket up, why rockets are so big, and how many stages a rocket uses before it reaches space." },
  { id: "science-749", title: "What is a satellite and how it helps us", category: "science", text: "Explain what a satellite is and how it helps our daily life. Tell me how satellites bring TV, maps, weather news and phone signals, and give examples of Indian satellites like [INSAT / Cartosat] in simple words." },
  { id: "science-750", title: "How ISRO launches satellites from India", category: "science", text: "Tell me, for [a school project], how ISRO launches satellites from Sriharikota in simple words. Explain the steps from countdown to orbit, why the east coast is a good place to launch, and what the PSLV and GSLV rockets do." },
  { id: "science-751", title: "Chandrayaan and the moon mission explained", category: "science", text: "Explain to [my younger brother] India's Chandrayaan missions in simple words. Tell me what Chandrayaan-3 did on the moon, why landing near the south pole was special, and what the rover Pragyan found there." },
  { id: "science-752", title: "Mangalyaan and the Mars mission explained", category: "science", text: "Explain to [a beginner in [your city]] India's Mangalyaan Mars mission in simple words. Tell me when it launched, how it reached Mars on the first try, what it studied, and why the whole world praised this low-cost mission." },
  { id: "science-753", title: "Why space is black even in daytime", category: "science", text: "Explain to [my daughter in Class 5] why space looks black even though the sun is shining. Tell me how air spreads sunlight to make our sky blue, why there is no air in space to spread the light, and why astronauts see stars all the time." },
  { id: "science-754", title: "How far away are the stars", category: "science", text: "Explain to [a Class 5 student] how far away stars are using light years in simple words. Tell me what a light year means, how far the nearest star is, and why the starlight we see tonight left its star years ago." },
  { id: "science-755", title: "What is the sun made of", category: "science", text: "Explain to [my 12-year-old nephew] what the sun is made of in simple words. Tell me about hydrogen and helium, how they join together to make heat and light, and why the sun is a ball of hot gas and not a solid ball of fire." },
  { id: "science-756", title: "Why the sun will not burn out soon", category: "science", text: "Explain to [my 10-year-old child] why the sun will keep shining for billions of years. Tell me how much fuel it still has, how slowly it uses that fuel, and why the sun is only halfway through its long life." },
  { id: "science-757", title: "How the Earth spins and moves around the sun", category: "science", text: "Explain to [a Class 6 student] how the Earth spins once a day and goes around the sun once a year. Use a simple spinning top and walking example to show both movements, and tell me why we do not feel the Earth moving." },
  { id: "science-758", title: "Why the Earth is tilted", category: "science", text: "Explain to [a 9-year-old school child] why the Earth is tilted and how that tilt gives us seasons. Tell me how much it leans, why it always leans the same way, and what our weather would be like if the Earth stood straight up." },
  { id: "science-759", title: "What causes the wind", category: "science", text: "Explain to [my younger brother] what causes wind in simple words. Tell me how warm air rises and cool air moves in to take its place, why wind is stronger near the sea, and how wind helps sailboats and windmills." },
  { id: "science-760", title: "Why sea breeze cools the coast in the evening", category: "science", text: "Explain why a cool sea breeze blows in the evening in coastal cities like [Chennai / Kochi]. Tell me how land and sea heat up differently, why the wind changes direction between day and night, and how fishermen use it." },
  { id: "science-761", title: "How mountains change the weather", category: "science", text: "Explain how mountains change the weather around them. Tell me why it is colder on top of a mountain, why clouds gather there, and why [Ooty / Shimla] feels cool even when the plains below are hot." },
  { id: "science-762", title: "Why deserts are hot by day and cold at night", category: "science", text: "Explain to [a beginner in [your city]] why deserts are very hot in the day and cold at night. Tell me how dry air and sand heat up and cool down fast, why there are no clouds to hold the heat, and how desert animals cope with the change." },
  { id: "science-763", title: "What is a heatwave", category: "science", text: "Explain what a heatwave is in simple words. Tell me why temperatures stay very high for many days, which parts of India face heatwaves, and give [five] simple ways to stay safe during a heatwave." },
  { id: "science-764", title: "Why winters feel colder near water", category: "science", text: "Explain to [my daughter in Class 5] why places near lakes and rivers feel colder and damper in winter. Tell me about fog, moisture and cold wind in simple words, and why mornings near water feel chillier than mornings in a dry town." },
  { id: "science-765", title: "How snow forms in the mountains", category: "science", text: "Explain how snow forms in cold mountains. Tell me why water vapour turns into soft snowflakes instead of rain, why snow is white, and why places like [Kashmir / Himachal Pradesh] get snow while the plains do not." },
  { id: "science-766", title: "Why it snows in Kashmir but not in Kerala", category: "science", text: "Explain to [a Class 5 student] why Kashmir gets snow in winter but Kerala never does. Tell me about latitude, height and cold winds in simple words, and why the same country can have snow in one place and summer heat in another." },
  { id: "science-767", title: "What is a rainbow and how it forms", category: "science", text: "Explain to [my 12-year-old nephew] how a rainbow forms after rain. Tell me how sunlight bends through raindrops to split into colours, why we see it only when the sun is behind us, and why we can never reach the end of a rainbow." },
  { id: "science-768", title: "Why rainbows have seven colours", category: "science", text: "Explain to [my 10-year-old child] why a rainbow shows seven colours in a fixed order. Tell me the colours from red to violet, why sunlight splits into colours, and give a simple way to remember the order using the word VIBGYOR." },
  { id: "science-769", title: "How to read a weather report", category: "science", text: "Teach me to read a weather report for [your city] in simple words. Explain what temperature, humidity, wind speed and rain chance mean, and how to use them to plan what to wear and whether to carry an umbrella." },
  { id: "science-770", title: "Why the weather office issues colour warnings", category: "science", text: "Explain to [a Class 6 student] the weather office colour warnings in simple words: green, yellow, orange and red. Tell me what each colour means, when they are used for rain or heat, and what a family should do on a red alert day." },
  { id: "science-771", title: "How clouds help predict rain", category: "science", text: "Teach me to read clouds and guess the weather in [my town]. Tell me which cloud shapes mean fair weather, which mean rain is coming soon, and how farmers and fishermen have used cloud signs for hundreds of years." },
  { id: "science-772", title: "Why the monsoon sometimes arrives late", category: "science", text: "Explain why the monsoon sometimes arrives late in India. Tell me about slow winds, warm sea water and weather patterns over the ocean, and what a late monsoon means for farmers waiting to sow in [your state]." },
  { id: "science-773", title: "What is El Nino and how it affects India", category: "science", text: "Explain to [my younger brother] El Nino in simple words. Tell me how warm water in the Pacific Ocean changes winds around the world, why it can weaken the Indian monsoon, and what it means for rain and crops in a dry year." },
  { id: "science-774", title: "How climate is different from weather", category: "science", text: "Explain the difference between weather and climate in simple words. Tell me why a rainy day does not mean the climate changed, and give examples of the climate of [Chennai / Delhi / Bengaluru] over a whole year." },
  { id: "science-775", title: "Why the Earth is warming up", category: "science", text: "Explain global warming in simple words. Tell me how smoke and gases trap heat around the Earth, why temperatures are rising, and give [five] simple things a family in India can do to help." },
  { id: "science-776", title: "How melting ice affects sea levels", category: "science", text: "Explain to [a beginner in [your city]] how melting ice in the Arctic and Antarctic raises sea levels. Tell me in simple words why coastal cities should care, which Indian coastal areas are at risk, and what happens when the sea slowly rises." },
  { id: "science-777", title: "Why the ozone layer matters", category: "science", text: "Explain the ozone layer in simple words. Tell me how it shields us from harmful sun rays, what damaged it, and how the world worked together to repair it, so a [school student] can understand why it matters." },
  { id: "science-778", title: "How the moon affects the calendar of festivals", category: "science", text: "Explain how moon phases fix the dates of Indian festivals. Tell me why [Eid / Guru Nanak Jayanti / Buddha Purnima] follow the moon, and how the lunar calendar and the solar calendar stay in step over the years." },
  { id: "science-779", title: "Why we see the moon in the daytime sometimes", category: "science", text: "Explain to [my daughter in Class 5] why we can sometimes see the moon in the daytime. Tell me how its position and the bright sunlight allow it, which phases are easiest to spot in the day, and the best time to look for it." },
  { id: "science-780", title: "How the sun helps plants grow", category: "science", text: "Explain to [a Class 5 student] how sunlight helps plants make food and grow. Tell me in simple words what leaves do with sunlight, water and air, and why plants kept in a dark room grow weak and pale." },
  { id: "science-781", title: "Why the sun feels stronger at noon", category: "science", text: "Explain why the sun feels strongest around noon. Tell me how sunlight travels a shorter path through the air at noon, why the sun is highest then, and why shade and hats matter most between [11 am and 3 pm]." },
  { id: "science-782", title: "What is ultraviolet light from the sun", category: "science", text: "Explain to [my 12-year-old nephew] ultraviolet light in simple words. Tell me how this invisible part of sunlight can burn skin, why it is stronger near noon and in summer, and how sunscreen, hats and shade protect us from it." },
  { id: "science-783", title: "Why the Earth has an atmosphere", category: "science", text: "Explain to [my 10-year-old child] why the Earth has a blanket of air around it. Tell me how gravity holds the air, what the air does for us, and why the moon and Mars cannot hold a thick blanket of air like Earth does." },
  { id: "science-784", title: "How the atmosphere protects us", category: "science", text: "Explain to [a Class 6 student] how the atmosphere protects life on Earth. Tell me how it blocks harmful sun rays, burns up small space rocks, and keeps our temperature steady, so we can understand why clean air matters." },
  { id: "science-785", title: "Why space rockets launch near the equator", category: "science", text: "Explain to [a 9-year-old school child] why rockets are often launched near the equator. Tell me how the Earth spins fastest there and gives rockets a free push, and why Sriharikota in India is a good place to launch satellites." },
  { id: "science-786", title: "What is space junk", category: "science", text: "Explain to [my younger brother] what space junk is in simple words. Tell me about old satellites and broken rocket parts circling the Earth, why they are a danger to new missions, and how scientists try to clean them up." },
  { id: "science-787", title: "How astronauts drink water in space", category: "science", text: "Explain to [a beginner in [your city]] how astronauts get drinking water in space. Tell me how they recycle water from sweat and breath, why every drop is precious, and what happens to water when there is no gravity to pour it." },
  { id: "science-788", title: "Why the moon has no weather", category: "science", text: "Explain to [my daughter in Class 5] why the moon has no rain, wind or clouds. Tell me how its lack of air stops weather from forming, what the temperature is like in sunlight and shadow, and why astronauts need special suits there." },
  { id: "science-789", title: "How tides help fishermen and ports", category: "science", text: "Explain how tides help fishermen and big ships. Tell me why boats leave with the high tide, how ports use tide charts, and why a low tide is the best time to collect shells on a beach in [your state]." },
  { id: "science-790", title: "Why the sea is salty", category: "science", text: "Explain to [a Class 5 student] why sea water is salty. Tell me how rivers carry tiny bits of salt from rocks into the sea, why the salt stays behind when water dries up, and why we cannot drink sea water even when we are thirsty." },
  { id: "science-791", title: "How the Earth got its water", category: "science", text: "Explain to [my 12-year-old nephew] where the Earth's water came from in simple words. Tell me about ice from space and water trapped in rocks long ago, and how the oceans formed as the young Earth slowly cooled down." },
  { id: "science-792", title: "Why the sky turns pink before rain", category: "science", text: "Explain to [my 10-year-old child] why the sky sometimes turns pink or orange before rain. Tell me how dust, clouds and low sunlight mix to colour the sky, and what old sayings about a red sky in the morning really mean." },
  { id: "science-793", title: "What is a dust storm", category: "science", text: "Explain what a dust storm is in simple words. Tell me how strong winds pick up dry soil in places like [Rajasthan / Delhi], why the sky turns brown, and what to do to stay safe when a dust storm hits." },
  { id: "science-794", title: "Why the wind blows stronger at night near the sea", category: "science", text: "Explain to [a Class 6 student] why the wind near the sea feels stronger at night. Tell me how land cools faster than water after sunset, how the air moves from land to sea, and why fishermen watch this wind before going out." },
  { id: "science-795", title: "How the monsoon winds change direction", category: "science", text: "Explain to [a 9-year-old school child] how monsoon winds change direction between summer and winter. Tell me why winds blow from the sea in summer and from the land in winter, and how this change brings rain to different parts of India." },
  { id: "science-796", title: "Why Chennai gets rain in November", category: "science", text: "Explain to [my younger brother] why Chennai gets most of its rain in October and November, not in June like the rest of India. Tell me about the northeast monsoon winds, the warm Bay of Bengal, and why this rain matters for the city." },
  { id: "science-797", title: "How farmers use weather forecasts", category: "science", text: "Explain how farmers use weather forecasts to plan their work. Tell me how a rain forecast helps them decide when to sow, spray or harvest, and where a farmer in [your state] can get a simple daily forecast." },
  { id: "science-798", title: "Why the soil smells after first rain", category: "science", text: "Explain why dry soil smells sweet after the first rain. Tell me about the tiny living things in soil and the oils plants leave behind, and why the smell is strongest after a long hot summer in [your village / town]." },
  { id: "science-799", title: "What is a glacier", category: "science", text: "Explain to [a beginner in [your city]] what a glacier is in simple words. Tell me how snow piles up and turns into slow-moving ice in the Himalayas, why glaciers are called the water towers of India, and which rivers begin from them." },
  { id: "science-800", title: "Why rivers start in the mountains", category: "science", text: "Explain why most Indian rivers start in the mountains. Tell me how rain and melting snow gather into streams, why rivers flow downhill to the sea, and name [three] rivers that begin in the Himalayas." },
  { id: "science-801", title: "How the sun sets at different times", category: "science", text: "Explain why sunset time changes through the year. Tell me how the Earth's tilt and its path around the sun shift sunset by minutes each week, and how much sunset time changes between June and December in [your city]." },
  { id: "science-802", title: "Why the moon rises later each night", category: "science", text: "Explain why the moon rises about 50 minutes later each night. Tell me how the moon moves along its path around the Earth, and give a simple way to watch the moonrise time change over [one week]." },
  { id: "science-803", title: "What is the dark side of the moon", category: "science", text: "Explain to [my daughter in Class 5] what people mean by the dark side of the moon. Tell me that it is not always dark, why we never see it from Earth, and what photos from space probes showed us about its hills and craters." },
  { id: "science-804", title: "How the Earth looks from the moon", category: "science", text: "Describe to [a Class 5 student] how the Earth looks from the moon in simple words. Tell me about its blue oceans, white clouds and green land, why it hangs in a black sky, and what astronauts felt when they saw it for the first time." },
  { id: "science-805", title: "Why planets stay in orbit around the sun", category: "science", text: "Explain to [my 12-year-old nephew] why planets keep going around the sun instead of flying away. Tell me in simple words how the sun's pull and the planet's speed balance each other, using a simple ball on a string example." },
  { id: "science-806", title: "What is gravity on the moon", category: "science", text: "Explain to [my 10-year-old child] gravity on the moon in simple words. Tell me why it is much weaker than on Earth, why astronauts could jump high and move slowly there, and what would happen if you dropped a hammer and a feather on the moon." },
  { id: "science-807", title: "How long would it take to fly to Mars", category: "science", text: "Tell me, for [a beginner in my town], how long a journey to Mars would take with today's rockets. Explain why the trip lasts many months, why the launch window opens only every two years, and what astronauts would do during the long journey." },
  { id: "science-808", title: "Why we send robots to other planets", category: "science", text: "Explain to [a 9-year-old school child] why we send robots and rovers to other planets instead of people. Tell me about cost, danger and distance, and what robots like the Mars rovers have found that people could not have found so soon." },
  { id: "science-809", title: "What is the asteroid belt", category: "science", text: "Explain to [my younger brother] the asteroid belt in simple words. Tell me where it floats between Mars and Jupiter, what it is made of, and why scientists think it is made of rocks that never joined together to form a planet." },
  { id: "science-810", title: "How the solar system formed", category: "science", text: "Explain to [a beginner in [your city]] how the solar system formed in simple words. Tell me about a huge cloud of gas and dust that slowly spun together, how the sun lit up in the middle, and how the planets grew from leftover bits." },
  { id: "science-811", title: "Why the Earth is called the blue planet", category: "science", text: "Explain to [my daughter in Class 5] why Earth is called the blue planet. Tell me how much of its surface is covered by water, why oceans look blue from space, and what the blue colour tells us about life on Earth." },
  { id: "science-812", title: "What is a leap year and why we need it", category: "science", text: "Explain to [a Class 5 student] what a leap year is in simple words. Tell me why the Earth takes a little more than 365 days to go around the sun, how one extra day in February fixes the calendar, and when the next leap year falls." },
  { id: "science-813", title: "Why February has 28 days", category: "science", text: "Explain to [my 12-year-old nephew] why February has 28 days while other months have 30 or 31. Tell me the simple story of the Roman calendar, how the months were arranged, and why February gets the extra day in a leap year." },
  { id: "science-814", title: "How the calendar follows the sun and moon", category: "science", text: "Explain to [my 10-year-old child] how our calendar follows the sun while some Indian calendars follow the moon. Tell me why the two calendars drift apart, how an extra month fixes the gap, and why festival dates shift each year." },
  { id: "science-815", title: "Why the days get longer after Makar Sankranti", category: "science", text: "Explain to [a Class 6 student] why days start getting longer after Makar Sankranti in mid-January. Tell me how the sun's path slowly rises again, why this festival marks the sun moving north, and how people celebrate it across India." },
  { id: "science-816", title: "What is Uttarayan and Dakshinayan", category: "science", text: "Explain to [a 9-year-old school child] Uttarayan and Dakshinayan in simple words. Tell me how the sun appears to move north for six months and south for six months, and why these two halves of the year feel different in India." },
  { id: "science-817", title: "How to make a simple sundial", category: "science", text: "Give me steps to make a simple sundial at home with [a stick, a paper plate and a marker]. Tell me how to place it in sunlight, how to mark the hours, and why the shadow moves as the sun crosses the sky." },
  { id: "science-818", title: "Why the stars move across the sky", category: "science", text: "Explain why stars seem to move across the sky at night. Tell me that the stars stay still and the Earth is turning, and give a simple way to watch one bright star move over [two hours] on a clear night." },
  { id: "science-819", title: "How to spot planets with the naked eye", category: "science", text: "Give me a simple guide to spotting planets without a telescope. Tell me which planets are visible this month, what time to look, and how to tell a steady shining planet from a twinkling star, to share with [my class]." },
  { id: "science-820", title: "Why the night sky looks different in summer and winter", category: "science", text: "Explain to [a beginner in [your city]] why we see different stars in summer and winter. Tell me how the Earth's journey around the sun changes which stars face us at night, and name one star group to look for in each season." },
  { id: "science-821", title: "What is a meteor shower", category: "science", text: "Explain to [my daughter in Class 5] what a meteor shower is in simple words. Tell me how the Earth passes through dust left by a comet, why many shooting stars appear on one night, and when the next big meteor shower will be visible from India." },
  { id: "science-822", title: "How to watch a meteor shower", category: "science", text: "Give me simple tips to watch a meteor shower with family. Tell me the best time of night, where to go away from city lights, what to carry, and how long to wait before the first shooting stars appear, to share with [my class]." },
  { id: "science-823", title: "Why the moon is important for the sea", category: "science", text: "Explain why the moon matters so much for the sea. Tell me how its pull moves the tides, why sea animals follow the moon, and how the moon's cycle affects fishing in coastal villages in [your state]." },
  { id: "science-824", title: "What is the greenhouse effect", category: "science", text: "Explain to [my 12-year-old nephew] the greenhouse effect in simple words. Tell me how some gases in the air trap heat like the glass of a greenhouse, why a little of it keeps us warm, and why too much of it makes the Earth hotter." },
  { id: "science-825", title: "Simple weather diary for a school student", category: "science", text: "Help me keep a simple weather diary for [one month] in [your city]. Tell me what to record each day, like rain, clouds, wind and temperature, and how to spot a pattern in the weather by the end of the month." },
  { id: "science-826", title: "Explain photosynthesis to a 9-year-old", category: "science", text: "Explain photosynthesis to a 9-year-old child in very simple words. Use the example of [a mango tree / a tulsi plant in a pot] and show how sunlight, water and air help it make food. End with three easy questions the child can answer at home." },
  { id: "science-827", title: "Why leaves are green in sunlight", category: "science", text: "Explain in simple words why most leaves look green. Talk about [a leaf from your garden / a spinach leaf] and the green colour inside it. Say how this colour helps the leaf catch sunlight and make food for the plant." },
  { id: "science-828", title: "Plant food making step by step", category: "science", text: "Describe photosynthesis step by step for a school child aged [8 / 10]. Start with sunlight falling on a leaf, then water from the roots and air from outside. Explain what the plant makes and what it gives out, in short simple sentences." },
  { id: "science-829", title: "Sunlight test with two potted plants", category: "science", text: "Plan a simple test for kids using two small potted plants of [the same type]. Keep one plant in bright sunlight and one in a dark cupboard for [7 days]. Tell us what to watch each day and what the result will show." },
  { id: "science-830", title: "What plants need to grow well", category: "science", text: "List what a plant needs to grow well, using [a tomato plant / a money plant] as the example. Explain sunlight, water, air and soil in simple words. Add one common mistake children make when they water a plant too much." },
  { id: "science-831", title: "How roots drink water from soil", category: "science", text: "Explain how roots take water from the soil and carry it up to the leaves. Use the example of [a tall banana plant / a small rose plant] and compare the roots to straws. Keep the words simple for a child aged [7 / 9]." },
  { id: "science-832", title: "Why plants give out oxygen for us", category: "science", text: "Explain in simple words why plants give out oxygen and why we need it to breathe. Use the example of [one big tree near your school / a park with many trees] and end with two reasons to protect trees in our area." },
  { id: "science-833", title: "Grow a seed in a glass jar", category: "science", text: "Give step-by-step instructions to grow [a moong / a chana] seed in a clear glass jar with wet cotton. Say how much water to add, where to keep the jar, and what changes to look for each day for one week." },
  { id: "science-834", title: "Leaf colour change in autumn season", category: "science", text: "Explain why some leaves change colour and fall off in some seasons. Use simple words for a child in [your city] and give two examples of trees whose leaves change colour. Add one question the child can ask a gardener." },
  { id: "science-835", title: "Parts of a plant and their jobs", category: "science", text: "Name the main parts of a plant and explain the job of each part in simple words. Use [a hibiscus plant / a sunflower] as the example. Cover roots, stem, leaves, flowers and fruit, and finish with a short matching game for kids." },
  { id: "science-836", title: "Why flowers need bees and butterflies", category: "science", text: "Explain why flowers need bees and butterflies to visit them. Use the example of [a marigold / a jasmine flower] and describe how pollen travels from one flower to another. Keep the language simple for a child aged [6 / 8]." },
  { id: "science-837", title: "Make a leaf collection for school", category: "science", text: "Help a child make a simple leaf collection for a school project. Suggest [5 / 8] different leaves to collect near home, how to press and dry them safely, and what to write under each leaf, like its name and shape." },
  { id: "science-838", title: "How seeds travel to new places", category: "science", text: "Explain how seeds travel to new places in simple words. Give examples of seeds that travel by wind, by water, by animals and by bursting open. Use [a dandelion / a coconut / a mango seed] and ask the child to find one example near home." },
  { id: "science-839", title: "What happens if a plant gets no water", category: "science", text: "Explain what happens to a plant if it gets no water for many days. Use the example of [a potted tulsi plant / a coriander plant] and describe the changes in the leaves and stem. End with how to save a dry plant." },
  { id: "science-840", title: "Compare a cactus and a lotus plant", category: "science", text: "Compare a cactus and a lotus plant in simple words for a school child. Explain where each one grows, how it stores or gets water, and why its shape suits its home. End with a table of [3 / 4] differences." },
  { id: "science-841", title: "Why do plants bend towards light", category: "science", text: "Explain why a plant near a window bends towards the light. Suggest a simple test with [a small plant in a pot] kept near a window for one week. Tell the child what to note each day and why the plant moves." },
  { id: "science-842", title: "Grow coriander on a kitchen windowsill", category: "science", text: "Give easy steps to grow coriander seeds in a small pot on a kitchen windowsill. Say what soil to use, how often to water, how much sunlight it needs, and after how many days the first green leaves will appear in [your kitchen]." },
  { id: "science-843", title: "Trees help clean the air around us", category: "science", text: "Explain how trees help clean the air in [your town / your school area]. Talk about dust, smoke and fresh air in simple words. Suggest three easy things children can do to look after the trees near their home." },
  { id: "science-844", title: "Make a plant diary for one month", category: "science", text: "Help a child keep a plant diary for one month for [a money plant / a tomato seedling]. Give a simple daily table for height, leaf count, water given and sunlight. Add one drawing task each week to show how the plant changes." },
  { id: "science-845", title: "Why do some plants have thorns", category: "science", text: "Explain why some plants, like [a rose / a cactus], have thorns. Tell a child how thorns protect the plant from animals that want to eat it. Give two more examples of plants with thorns found in India." },
  { id: "science-846", title: "Fruits come from flowers first", category: "science", text: "Explain how a flower turns into a fruit, using [a mango / a guava / a brinjal] as the example. Describe the steps in simple words, from flower to small fruit to ripe fruit. Add one question for the child to ask at home." },
  { id: "science-847", title: "Soil types for a home garden", category: "science", text: "Explain three types of soil in simple words for a beginner gardener in [your city]. Say which soil suits vegetables, which suits flowers, and how to make soil better with compost from kitchen waste at home." },
  { id: "science-848", title: "Why leaves have veins like lines", category: "science", text: "Explain why leaves have thin lines called veins. Compare them to small pipes that carry water and food around the leaf. Ask the child to look at [a peepal leaf / a mango leaf] and draw the veins they see." },
  { id: "science-849", title: "Plants that grow without soil in water", category: "science", text: "Explain how some plants can grow in water without soil. Use [a money plant cutting / a sweet potato in a bottle] as the example. Give simple steps to set it up at home and say when to change the water." },
  { id: "science-850", title: "A fun plant quiz for class 4", category: "science", text: "Make a fun plant quiz for class 4 with [10] simple questions about photosynthesis, roots, leaves, flowers and seeds. Give four options for each question and an answer key at the end, with one-line simple explanations." },
  { id: "science-851", title: "How a seed wakes up and sprouts", category: "science", text: "Explain how a dry seed wakes up and starts to sprout. Use the example of [a rajma / a moong seed] soaked in water overnight. Describe the first root, the first shoot and the first leaves in short, simple sentences for a child." },
  { id: "science-852", title: "Why do plants need carbon dioxide", category: "science", text: "Explain in simple words what carbon dioxide is and why plants need it to make food. Say where it comes from in the air and how leaves take it in through tiny holes. Use an example from [your kitchen garden / your school garden]." },
  { id: "science-853", title: "Compare trees shrubs and herbs for kids", category: "science", text: "Explain the difference between trees, shrubs and herbs in simple words. Give two Indian examples of each, like [a mango tree / a hibiscus shrub / a tulsi herb]. End with a game where the child sorts plants near home into three groups." },
  { id: "science-854", title: "Make compost from kitchen waste at home", category: "science", text: "Give simple steps to make compost from kitchen waste like vegetable peels and fruit skins. Say what to put in a [bucket / clay pot], how often to stir it, and when the compost is ready to feed plants in a home garden." },
  { id: "science-855", title: "Why do leaves fall from trees", category: "science", text: "Explain why leaves fall from some trees in simple words for a child aged [7 / 9]. Talk about saving water and energy, and what happens to fallen leaves on the ground. Add one activity to collect and press a fallen leaf." },
  { id: "science-856", title: "Grow a sunflower and measure it weekly", category: "science", text: "Help a child grow a sunflower in a pot and measure it every week. Give steps for sowing the seed, watering and sunlight, plus a simple chart for height in centimetres. Say how tall it may grow in [6 / 8] weeks." },
  { id: "science-857", title: "Plants that eat insects in nature", category: "science", text: "Explain how some plants catch and eat insects, using the pitcher plant as the example. Keep the words simple and gentle for a child, and say why these plants grow in places where the soil has very little food, in [a warm wet place]." },
  { id: "science-858", title: "Why is the stem strong and upright", category: "science", text: "Explain what the stem does for a plant, using [a banana plant / a sunflower stem] as the example. Say how it holds up the leaves and flowers and carries water from the roots. Add a simple test with a celery stalk in coloured water." },
  { id: "science-859", title: "How do plants make new plants", category: "science", text: "Explain three ways plants make new plants: from seeds, from cuttings and from bulbs. Give one Indian example of each, like [mango seeds / money plant cuttings / onion bulbs]. Keep the language simple for a class 5 child." },
  { id: "science-860", title: "A garden walk to spot ten plants", category: "science", text: "Plan a garden walk for a child in [a park / your school garden] to spot ten different plants. Give a simple checklist with plant name, leaf shape, flower colour and height. Add two questions to ask after the walk." },
  { id: "science-861", title: "Why do flowers smell sweet and bright", category: "science", text: "Explain why many flowers have bright colours and a sweet smell. Say how colour and smell invite bees and butterflies to visit, using [a rose / a jasmine flower] as the example. Keep it simple for a child aged [6 / 8]." },
  { id: "science-862", title: "Water travel inside a plant stem", category: "science", text: "Describe a simple home test that shows water travelling up a plant stem. Use [a white flower / a celery stalk] in a glass of water with a few drops of food colour. Say what to watch after [4 / 6] hours." },
  { id: "science-863", title: "Plants in the desert and in water", category: "science", text: "Compare how plants live in a desert and in water, using [a cactus] and [a lotus] as examples. Explain in simple words how each plant saves water or floats, and why it could not live in the other place." },
  { id: "science-864", title: "Why do we need to water plants daily", category: "science", text: "Explain why plants need water every day, but not too much water. Use the example of [a potted plant on a balcony] in hot summer weather. Say how to check if the soil is dry by touching it with a finger." },
  { id: "science-865", title: "Make a simple herb garden at home", category: "science", text: "Help a family start a small herb garden with [tulsi, mint and coriander] in three small pots. Give steps for soil, seeds, sunlight and watering, and say how each herb can be used in cooking at home." },
  { id: "science-866", title: "How do plants help animals live", category: "science", text: "Explain how plants help animals live, in simple words for a child. Talk about food, shelter, shade and clean air, using [a big tree in a park] as the example. Name three animals that live on or under that tree." },
  { id: "science-867", title: "Why do some leaves feel rough or smooth", category: "science", text: "Ask a child to touch and compare [a mango leaf, a rose leaf and a curry leaf]. Explain in simple words why leaves feel different, and how their surface helps them catch light or save water. Add a leaf-rubbing art activity." },
  { id: "science-868", title: "Grow beans in cotton for a class", category: "science", text: "Give class-friendly steps to grow beans in wet cotton in a small cup. Say how many beans to use, where to keep the cup, and what the children should draw each day for [7] days to show the root and shoot growing." },
  { id: "science-869", title: "What do plants do at night time", category: "science", text: "Explain what plants do at night when there is no sunlight. Say in simple words that they stop making food but keep breathing, like us. Use the example of [a plant in your bedroom / a tree outside your window]." },
  { id: "science-870", title: "Why are fruits different colours and tastes", category: "science", text: "Explain why fruits have different colours, tastes and smells, using [a mango, a banana and a lemon] as examples. Say in simple words how colour and taste help animals carry seeds to new places." },
  { id: "science-871", title: "A plant life cycle poster for school", category: "science", text: "Help a child make a plant life cycle poster with [5] stages, from seed to flower to fruit to seed again. Give a short simple line for each stage and ideas for drawings, using [a tomato plant / a sunflower] as the example." },
  { id: "science-872", title: "How do farmers grow rice in fields", category: "science", text: "Explain in simple words how farmers grow rice in fields in India. Cover sowing seeds, transplanting seedlings, water in the field and harvest time. Use [a village near your town / Tamil Nadu] as the setting for the story." },
  { id: "science-873", title: "Why do plants need space to grow", category: "science", text: "Explain why plants need space to grow well. Use the example of [two tomato plants in one small pot] and say how they fight for sunlight, water and food. Suggest how far apart to plant seedlings in a garden bed." },
  { id: "science-874", title: "Spot photosynthesis in your own kitchen", category: "science", text: "Show a child where photosynthesis happens in foods we eat, like [spinach, methi and curry leaves]. Explain that the green leaves made food using sunlight. Add a simple task to sort green vegetables in the kitchen by leaf shape." },
  { id: "science-875", title: "Why do we say plants are living things", category: "science", text: "Explain why plants count as living things, just like animals and people. List the signs of life in a plant, like growing, making food, breathing and making seeds, using [a plant in your home] as the example." },
  { id: "science-876", title: "Why do dogs wag their tails", category: "science", text: "Explain in simple words why dogs wag their tails and what different tail moves can mean. Use the example of [a pet dog / a street dog near your home] and say how to tell if a dog is happy, excited or scared." },
  { id: "science-877", title: "How do cats see in the dark", category: "science", text: "Explain how cats can see better than us in dim light. Talk about their big eyes, wide pupils and whiskers in simple words. Use the example of [a cat at home / a cat in your street] and add one safe watching activity at dusk." },
  { id: "science-878", title: "Why do elephants have big ears", category: "science", text: "Explain why elephants have such big ears in simple words for a child. Say how the ears help them stay cool in hot weather and hear sounds from far away. Add two more facts about elephants in [Kerala / Tamil Nadu]." },
  { id: "science-879", title: "How do birds fly in the sky", category: "science", text: "Explain how birds fly, using [a crow / a sparrow] as the example. Talk about wings, light bones and feathers in simple words. Ask the child to watch a bird take off and note how its wings move." },
  { id: "science-880", title: "Why do cows eat grass all day", category: "science", text: "Explain why cows eat grass and chew it again and again. Describe their four stomach parts in very simple words, without hard terms. Use the example of [a cow in your village / a cow in a dairy farm]." },
  { id: "science-881", title: "How do fish breathe under water", category: "science", text: "Explain how fish breathe under water using gills. Compare gills to our lungs in simple words, using [a goldfish in a tank / a fish in a pond] as the example. End with why a fish cannot live out of water." },
  { id: "science-882", title: "Why do snakes shed their skin", category: "science", text: "Explain why snakes shed their old skin as they grow. Describe the process in simple, gentle words for a child aged [7 / 9]. Add a note on what to do if you see a snake skin in a garden." },
  { id: "science-883", title: "How do bees make honey in hives", category: "science", text: "Explain how bees collect nectar from flowers and turn it into honey in a hive. Use simple words and the example of [a sunflower / a mustard field]. Say what job the queen bee, worker bees and drones do." },
  { id: "science-884", title: "Why do monkeys live in groups", category: "science", text: "Explain why monkeys live in groups and help each other. Talk about food, safety and looking after babies in simple words. Use the example of [monkeys near a temple / monkeys in a forest in India]." },
  { id: "science-885", title: "How do camels live in the desert", category: "science", text: "Explain how a camel lives in a hot desert without much water. Talk about its hump, long eyelashes and wide feet in simple words. Use the example of [a camel in Rajasthan] and ask the child to name two more desert animals." },
  { id: "science-886", title: "Why do frogs live near water", category: "science", text: "Explain why frogs need water and damp places to live. Describe their life from tadpole to frog in simple words, using [a pond near your home / a garden after rain] as the setting for the story." },
  { id: "science-887", title: "How do butterflies change from caterpillars", category: "science", text: "Explain the life cycle of a butterfly, from egg to caterpillar to pupa to butterfly. Use simple words for a child aged [6 / 8] and suggest a safe way to watch a caterpillar on [a curry leaf plant] without touching it." },
  { id: "science-888", title: "Why do owls stay awake at night", category: "science", text: "Explain why owls are active at night and sleep in the day. Talk about their big eyes, silent wings and sharp hearing in simple words. Add one question for the child to ask about other night animals in [your town]." },
  { id: "science-889", title: "How do ants carry heavy food home", category: "science", text: "Explain how ants work together and carry food much heavier than their own bodies. Describe the line of ants and the scent trail in simple words. Suggest watching ants near [a sugar spill / a garden path] for ten minutes." },
  { id: "science-890", title: "Why do peacocks spread their feathers", category: "science", text: "Explain why a male peacock spreads its bright feathers. Say in simple words how it shows off to attract a mate and scare away rivals. Use the example of [a peacock in a park / a peacock near a temple in India]." },
  { id: "science-891", title: "How do penguins keep warm in cold", category: "science", text: "Explain how penguins stay warm in very cold places. Talk about thick feathers, fat under the skin and huddling together in simple words. Ask the child to compare a penguin with [a sparrow in your city]." },
  { id: "science-892", title: "Why do tigers have stripes on fur", category: "science", text: "Explain why tigers have stripes and how the stripes help them hide in tall grass. Say that each tiger has a different stripe pattern, like a fingerprint. Add two facts about tigers in [Ranthambore / Bandipur] forests." },
  { id: "science-893", title: "How do squirrels store food for later", category: "science", text: "Explain how squirrels collect nuts and seeds and hide them for later. Describe their quick movements and good memory in simple words. Suggest watching a squirrel in [your garden / a park] and noting what it carries." },
  { id: "science-894", title: "Why do dogs have a strong sense of smell", category: "science", text: "Explain why a dog can smell things we cannot smell at all. Compare a dog nose with a human nose in simple words. Give two examples of how people use a dog strong sense of smell, like finding lost things in [a park / a home]." },
  { id: "science-895", title: "How do spiders make webs to catch food", category: "science", text: "Explain how a spider makes a web from silk and waits for insects to fly into it. Keep the words simple and gentle for a child. Suggest watching a web in [a garden corner] early in the morning without touching it." },
  { id: "science-896", title: "Why do whales live in the sea", category: "science", text: "Explain why whales live in the sea even though they are mammals like us. Talk about breathing through a blowhole and swimming with a tail in simple words. Add one fact about the blue whale, the largest animal on Earth, for a child aged [8]." },
  { id: "science-897", title: "How do chameleons change their colour", category: "science", text: "Explain how a chameleon changes its skin colour to hide and to show its mood. Use simple words for a child aged [8 / 10] and say why it is not magic. Add a drawing task to colour a chameleon in two settings." },
  { id: "science-898", title: "Why do rabbits have long ears", category: "science", text: "Explain why rabbits have long ears and how the ears help them hear danger and stay cool. Use the example of [a pet rabbit / a rabbit in a field] and add two facts about what rabbits eat in India." },
  { id: "science-899", title: "How do ducks swim and stay dry", category: "science", text: "Explain how ducks swim well and why water rolls off their feathers. Talk about webbed feet and oily feathers in simple words. Suggest watching ducks in [a pond / a lake near your town] and noting how they move." },
  { id: "science-900", title: "A fun animal quiz for class 3", category: "science", text: "Make a fun animal quiz for class 3 with [10] simple questions about pets, birds, insects and wild animals in India. Give four options for each question and an answer key at the end, with one-line simple explanations." },
  { id: "science-901", title: "Why do horses run so fast", category: "science", text: "Explain why horses can run so fast, using simple words about long legs, strong muscles and hooves. Compare a horse with [a cow / a goat] and ask the child to name two jobs horses do in India today." },
  { id: "science-902", title: "How do baby animals learn from mothers", category: "science", text: "Explain how baby animals learn from their mothers, using [a puppy / a kitten / a baby monkey] as the example. Talk about feeding, playing and staying safe in simple words for a child aged [6 / 8]." },
  { id: "science-903", title: "Why do bears sleep through winter", category: "science", text: "Explain why some bears sleep for a long time in winter, in simple words. Say how they eat a lot before winter, then rest and use stored fat. Add a note that bears in [India] do not sleep this way." },
  { id: "science-904", title: "How do bats fly at night", category: "science", text: "Explain how bats fly at night and find their way in the dark. Talk about wings like hands and sound echoes in very simple words. Use the example of [bats near an old tree / bats in a temple town]." },
  { id: "science-905", title: "Why do kangaroos hop instead of walking", category: "science", text: "Explain why kangaroos hop on strong back legs and carry babies in a pouch. Keep the words simple for a child and compare a kangaroo hop with a rabbit hop. Add one fact about where kangaroos live, in [Australia]." },
  { id: "science-906", title: "How do earthworms help the soil", category: "science", text: "Explain how earthworms help soil stay soft and rich for plants. Describe how they eat dead leaves and make tunnels in simple words. Suggest a safe way to spot an earthworm in [a garden after rain]." },
  { id: "science-907", title: "Why do crocodiles have strong jaws", category: "science", text: "Explain why crocodiles have strong jaws and sharp teeth, in simple words for a child. Say what they eat and how they wait quietly in water. Add a safety note about staying away from river banks in [your state] where crocodiles live." },
  { id: "science-908", title: "How do snails carry their homes", category: "science", text: "Explain how a snail carries its shell like a home on its back. Talk about how it moves slowly, eats leaves and hides inside when scared. Suggest watching a snail in [a garden after rain] without picking it up." },
  { id: "science-909", title: "Why do parrots copy human words", category: "science", text: "Explain why parrots can copy words and sounds they hear. Say in simple words that they learn by listening and repeating, not by understanding like us. Use the example of [a pet parrot / a parrot in a park]." },
  { id: "science-910", title: "How do bees find flowers far away", category: "science", text: "Explain how bees find flowers and tell other bees where to go. Talk about smell, colour and a special dance in very simple words. Use the example of [a garden with marigolds / a mustard field] in India." },
  { id: "science-911", title: "Why do deer run in a herd", category: "science", text: "Explain why deer live and run together in a herd. Talk about safety from tigers and leopards, and how many eyes spot danger faster. Use the example of [deer in a forest / deer in a national park in India]." },
  { id: "science-912", title: "How do crabs walk sideways on sand", category: "science", text: "Explain why crabs walk sideways on the beach. Talk about their legs, claws and hard shell in simple words. Suggest watching crabs at [Marina Beach / a beach near your town] and noting how they dig holes in the sand." },
  { id: "science-913", title: "Why do fireflies glow in the dark", category: "science", text: "Explain why fireflies glow at night in simple words. Say that the light helps them find mates and warn other animals. Suggest a safe evening watch in [a garden / a village field] and remind the child not to catch them." },
  { id: "science-914", title: "How do turtles live on land and water", category: "science", text: "Explain how turtles live both on land and in water. Talk about their shell, strong legs and slow walk in simple words. Use the example of [a turtle in a pond / a sea turtle on a beach in India]." },
  { id: "science-915", title: "Why do cats clean themselves with tongues", category: "science", text: "Explain why cats lick their fur to clean it. Talk about their rough tongue, like a small brush, in simple words. Use the example of [a pet cat at home] and add two more ways cats keep themselves clean." },
  { id: "science-916", title: "How do elephants use their trunks", category: "science", text: "Explain how an elephant uses its trunk like a hand, a nose and a shower. Give examples like picking leaves, drinking water and spraying dust. Use simple words for a child aged [7 / 9] in India." },
  { id: "science-917", title: "Why do birds migrate in winter season", category: "science", text: "Explain why some birds fly far away in winter and return in summer. Talk about food, warmth and safe nesting in simple words. Use the example of [birds visiting a lake near your town] in winter." },
  { id: "science-918", title: "How do starfish regrow a lost arm", category: "science", text: "Explain how a starfish can grow back a lost arm, in very simple words for a child. Say where starfish live and what they eat on the sea floor. Add a drawing task to show a starfish with five arms, using [orange / pink] colours." },
  { id: "science-919", title: "Why do goats climb steep rocky hills", category: "science", text: "Explain why goats are good at climbing steep hills and rocks. Talk about strong legs, balance and hooves in simple words. Use the example of [goats in a hill village / goats near a temple in Tamil Nadu]." },
  { id: "science-920", title: "How do hens look after their chicks", category: "science", text: "Explain how a hen looks after her chicks, keeping them warm under her wings and showing them food. Use simple words for a child aged [6 / 8] and suggest watching hens in [a village / a farm near your town]." },
  { id: "science-921", title: "Why do lions live in groups called prides", category: "science", text: "Explain why lions live in groups called prides and hunt together. Talk about the roles of lionesses and male lions in simple words. Add two facts about Asiatic lions in the Gir forest, for a child aged [9]." },
  { id: "science-922", title: "How do dolphins talk under water", category: "science", text: "Explain how dolphins make clicks and whistles to talk and find food under water. Keep the words simple for a child and compare dolphin sounds with human speech. Add one fact about dolphins in [the Ganga river]." },
  { id: "science-923", title: "Why do pandas eat only bamboo", category: "science", text: "Explain why giant pandas eat mostly bamboo, even though they are bears. Talk about their strong jaws, extra thumb and bamboo forests in simple words. Ask the child to name two animals in [Assam] that eat bamboo." },
  { id: "science-924", title: "How do ladybirds protect garden plants", category: "science", text: "Explain how ladybirds help gardeners by eating tiny insects that harm plants. Describe their red shell with black spots in simple words. Suggest spotting a ladybird on [a rose plant / a vegetable plant] at home." },
  { id: "science-925", title: "Animal homes matching game for kids", category: "science", text: "Make a matching game for kids with [10] animals and their homes, like a nest, a burrow, a hive and a den. Give the animal list, the home list and the answers, using animals found in India, in simple words." },
  { id: "science-926", title: "Make a rainbow with water and sunlight", category: "science", text: "Give simple steps to make a small rainbow at home using a glass of water and sunlight from a window. Say what to place where, what the child will see on [a white paper / a wall], and why the colours appear." },
  { id: "science-927", title: "Float and sink test with kitchen things", category: "science", text: "Plan a float and sink test for kids using [a spoon, a cork, a coin, a leaf and a plastic bottle cap] in a tub of water. Ask the child to guess first, then test each item and write the result in a simple table." },
  { id: "science-928", title: "Grow salt crystals in a jar at home", category: "science", text: "Give safe steps to grow salt crystals in a jar using hot water, salt and a string. Say how much salt to stir in, where to keep the jar, and what changes to watch each day for [5 / 7] days." },
  { id: "science-929", title: "Make a simple sundial in your garden", category: "science", text: "Help a child make a sundial in the garden using a stick, a flat stone and chalk marks. Explain how to place the stick, mark the shadow at [9 am, 12 noon and 4 pm], and why the shadow moves." },
  { id: "science-930", title: "Test which paper towel soaks most water", category: "science", text: "Plan a fair test to find which paper towel soaks up the most water. Use [two / three] brands or types, the same amount of water and the same size pieces. Tell the child how to measure and record the result." },
  { id: "science-931", title: "Make invisible ink with lemon juice", category: "science", text: "Give safe steps to write a secret message with lemon juice and a cotton bud on white paper. Explain how to reveal it by holding the paper near [a warm bulb / a sunny window], with an adult helping at every step." },
  { id: "science-932", title: "Build a paper bridge that holds coins", category: "science", text: "Challenge a child to build a paper bridge between two books that can hold [5 / 10] coins. Suggest folding the paper in different shapes and testing each one. Explain in simple words why a folded shape is stronger." },
  { id: "science-933", title: "Make a rain gauge with a plastic bottle", category: "science", text: "Give steps to make a rain gauge from a cut plastic bottle and a ruler. Say where to place it in [a garden / a balcony], how to read the water level after rain, and how to record the result for one week." },
  { id: "science-934", title: "Test ice melting in sun and shade", category: "science", text: "Plan a simple test with two equal ice cubes, one in sunlight and one in shade. Ask the child to guess which melts first, then time both with [a clock / a phone timer]. Explain in simple words why the sunny cube melts faster." },
  { id: "science-935", title: "Make a volcano with baking soda at home", category: "science", text: "Give safe steps to make a small volcano model with baking soda, vinegar and a plastic bottle in a tray. Say what to add first, what fizzing the child will see, and why the mixture bubbles up, using [red / orange] food colour." },
  { id: "science-936", title: "Grow a potato plant from a sprouting potato", category: "science", text: "Help a child grow a new potato plant from a sprouting potato in a pot of soil. Give steps for cutting, planting, watering and sunlight, and say after how many weeks green shoots will appear above the soil in [your balcony pot]." },
  { id: "science-937", title: "Make a simple water filter with sand", category: "science", text: "Give steps to make a simple water filter using a cut bottle, cotton, sand and small stones. Pour muddy water through it and describe what changes. Remind the child that filtered water from [a river / a pond] is still not safe to drink." },
  { id: "science-938", title: "Test shadows with a torch at night", category: "science", text: "Plan a shadow game at night with a torch and [a toy, a spoon and a book]. Ask the child to move the torch near and far and note how the shadow grows and shrinks. Explain in simple words why shadows change size." },
  { id: "science-939", title: "Make a balloon rocket with a string", category: "science", text: "Give steps to make a balloon rocket that zooms along a string across a room. Use a balloon, a straw, tape and a long string. Explain in simple words how the air rushing out pushes the balloon forward across [your living room]." },
  { id: "science-940", title: "Test which soil holds the most water", category: "science", text: "Plan a fair test with [sandy soil, garden soil and clay soil] in three cups with holes. Pour the same amount of water into each and measure what drains out. Tell the child what the result means for plants." },
  { id: "science-941", title: "Make a simple periscope from cardboard", category: "science", text: "Give steps to make a simple periscope from a cardboard tube and two small mirrors. Explain how to place the mirrors at an angle, and how the periscope helps you see over [a wall / a fence] without standing up." },
  { id: "science-942", title: "Watch a bean seed grow in a bag", category: "science", text: "Help a child grow a bean seed in a clear plastic bag with wet paper towel stuck on a window. Say what to watch each day for [7] days, from the first root to the first green shoot, and what to draw." },
  { id: "science-943", title: "Make music with glasses of water", category: "science", text: "Show a child how to make music with [5] glasses filled with different levels of water. Tap each glass gently with a spoon and note the sound. Explain in simple words why more water makes a lower sound." },
  { id: "science-944", title: "Test a paper aeroplane with three designs", category: "science", text: "Plan a test with three paper aeroplane designs made from the same paper size. Fly each one [3] times from the same spot and measure how far it goes. Tell the child how to record the best design and why it flew farthest." },
  { id: "science-945", title: "Make a compass with a needle and water", category: "science", text: "Give safe steps to make a simple compass with a needle, a leaf and a bowl of water, with an adult helping. Explain how the needle turns to point north and south, and how to test it by turning the bowl in [your garden]." },
  { id: "science-946", title: "See how water climbs up a paper towel", category: "science", text: "Show a child how water climbs up a paper towel dipped in a glass of coloured water. Ask them to watch the colour rise for [10] minutes and draw what they see. Explain in simple words how plants use the same trick." },
  { id: "science-947", title: "Make a weather chart for two weeks", category: "science", text: "Help a child make a weather chart for two weeks in [your city]. Give a simple daily table for sunny, cloudy, rainy or windy, plus morning and evening temperature. Add one line each day about what clothes felt right." },
  { id: "science-948", title: "Test an egg in salty and plain water", category: "science", text: "Plan a simple test with an egg in a glass of plain water and an egg in a glass of salty water. Ask the child to guess what happens, then watch which egg floats. Explain in simple words why salt water in [a steel glass] lifts the egg." },
  { id: "science-949", title: "Build a tower with newspaper and tape", category: "science", text: "Challenge a child to build the tallest tower they can using only newspaper and tape. Suggest rolling the paper into tubes for strength and testing the tower with [a small book] on top. Explain why a wide base helps." },
  { id: "science-950", title: "Make a simple kaleidoscope for kids", category: "science", text: "Give steps to make a simple kaleidoscope from a cardboard tube, shiny paper and coloured bits. Explain how to look through it and turn it slowly to see new patterns. Keep the steps safe and easy for a child aged [7 / 9]." },
  { id: "science-951", title: "Test which materials block sunlight best", category: "science", text: "Plan a test with [a cloth, a cardboard piece, a plastic sheet and a leaf] held over a torch in a dark room. Ask the child to guess which blocks the most light, then check the shadow each one makes and record the result." },
  { id: "science-952", title: "Make a simple pulley to lift a toy", category: "science", text: "Give steps to make a simple pulley with a string, a spool and a small toy. Show how pulling down lifts the toy up, and explain in simple words how a pulley makes lifting easier. Suggest testing with [two / three] toy weights." },
  { id: "science-953", title: "Watch sugar dissolve in hot and cold water", category: "science", text: "Plan a test with one spoon of sugar in hot water and one spoon in cold water. Stir both the same way and time how long each takes to vanish. Explain in simple words why sugar dissolves faster in hot water from [a kettle / a stove]." },
  { id: "science-954", title: "Make a mini greenhouse in a bottle", category: "science", text: "Help a child make a mini greenhouse from a clear plastic bottle cut in half, with soil and [a small seedling] inside. Say where to keep it, how often to water, and what changes to watch over two weeks." },
  { id: "science-955", title: "Test a lemon battery with a small bulb", category: "science", text: "Give safe steps, with an adult helping, to make a lemon battery using [a lemon, two coins of different metals and wires] to light a tiny bulb. Explain in simple words where the power comes from and why it is weak." },
  { id: "science-956", title: "Make a wind vane to show wind direction", category: "science", text: "Give steps to make a wind vane from cardboard, a straw and a pin, fixed on a stick in [a garden / a balcony]. Explain how to read which way the wind blows and how to record it morning and evening for one week." },
  { id: "science-957", title: "See air take up space in a glass", category: "science", text: "Show a child that air takes up space using a glass, a bowl of water and a tissue. Push the glass upside down into the water and ask why the tissue stays dry. Explain the answer in simple words for a child aged [7 / 9]." },
  { id: "science-958", title: "Make a simple telephone with paper cups", category: "science", text: "Give steps to make a telephone with two paper cups and a long string. Show how to hold the string tight and speak into one cup while a friend listens at the other. Explain in simple words how sound travels along the string between [two rooms]." },
  { id: "science-959", title: "Test which fruit has the most seeds", category: "science", text: "Plan a counting test with [an orange, a guava, a papaya and a pomegranate]. Ask the child to guess which has the most seeds, then cut each one with an adult and count. Record the results in a simple table." },
  { id: "science-960", title: "Make a dancing raisin in soda water", category: "science", text: "Give steps to drop a few raisins into a glass of clear soda water and watch them dance up and down. Explain in simple words how tiny bubbles in [a clear glass] lift the raisins and then pop, making them sink again." },
  { id: "science-961", title: "Build a simple catapult with ice cream sticks", category: "science", text: "Give safe steps to build a small catapult from ice cream sticks, rubber bands and a spoon. Test it with a soft pom-pom and measure how far it flies. Explain in simple words how the bent stick stores energy, for a child aged [8 / 10]." },
  { id: "science-962", title: "Watch a candle need air to burn", category: "science", text: "Give safe steps, with an adult doing the lighting, to cover a small candle with a glass jar and watch the flame go out. Explain in simple words why the flame needs air, and why it stops when the air in [the jar] runs out." },
  { id: "science-963", title: "Make a colour mixing chart with paints", category: "science", text: "Help a child make a colour mixing chart using red, yellow and blue paints. Ask them to mix pairs and name the new colours they make. Explain in simple words how two colours blend to make a third colour on [white paper]." },
  { id: "science-964", title: "Test how fast a toy car rolls downhill", category: "science", text: "Plan a test with a toy car rolling down a ramp made from a book and a board. Change the ramp height [3] times and measure how far the car rolls. Tell the child how to record each run in a simple table." },
  { id: "science-965", title: "Make a simple bird feeder for your balcony", category: "science", text: "Give steps to make a bird feeder from a plastic bottle, sticks and seeds like millet and rice. Say where to hang it on [a balcony / a tree], how to keep it clean, and which birds may visit in your area." },
  { id: "science-966", title: "See how a sponge soaks and squeezes water", category: "science", text: "Show a child how a sponge soaks up water and how squeezing it pushes the water out. Use [a kitchen sponge and a bowl] and ask the child to count how many spoonfuls it holds. Explain in simple words where the water hides." },
  { id: "science-967", title: "Make a shadow puppet show at home", category: "science", text: "Help a child make shadow puppets from cardboard and sticks, then put on a show with a torch and a white bedsheet. Give ideas for [3] animal shapes and explain in simple words how the torch makes big shadows." },
  { id: "science-968", title: "Test melting chocolate in sun and shade", category: "science", text: "Plan a simple test with two equal pieces of chocolate, one in sunlight and one in shade. Ask the child to guess which melts first, then check both after [10] minutes. Explain in simple words why heat melts chocolate." },
  { id: "science-969", title: "Make a simple model of a plant cell", category: "science", text: "Help a child make a simple model of a plant cell using a box, clay and labels for [the nucleus, the green parts and the cell wall]. Keep the words simple and give one line to explain the job of each part." },
  { id: "science-970", title: "Watch mould grow on bread safely", category: "science", text: "Plan a safe watch of mould growing on bread kept in a sealed bag, without opening the bag. Use [a dry piece and a damp piece] and note changes over [7] days. Explain in simple words why damp bread grows mould faster." },
  { id: "science-971", title: "Make a simple balance scale with a hanger", category: "science", text: "Give steps to make a balance scale from a coat hanger, string and two small cups. Show how to compare [a stone and a fruit / two toys] and tell which is heavier. Explain in simple words how a balance works." },
  { id: "science-972", title: "Test which cup keeps water warm longest", category: "science", text: "Plan a fair test with warm water in [a steel glass, a plastic cup and a clay cup]. Measure the warmth after [10 / 20] minutes by touching the outside safely. Tell the child how to record which cup kept water warmest." },
  { id: "science-973", title: "Make a paper spinner and watch it fall", category: "science", text: "Give steps to make a paper spinner from a strip of paper and a paper clip. Drop it from [a chair / a balcony with an adult] and watch it spin down slowly. Explain in simple words how air slows its fall." },
  { id: "science-974", title: "Grow mould free sprouts in a jar", category: "science", text: "Give safe steps to grow moong sprouts in a jar at home, rinsing them twice a day. Say how long to soak the seeds, where to keep the jar, and after how many days the sprouts are ready to eat in [a salad / a chaat]." },
  { id: "science-975", title: "A home science quiz for class 5", category: "science", text: "Make a home science quiz for class 5 with [10] simple questions about plants, animals, magnets and home tests. Give four options for each question and an answer key at the end, with one-line simple explanations." },
  { id: "science-976", title: "What is a magnet in simple words", category: "science", text: "Explain what a magnet is in simple words for a child aged [7 / 9]. Use the example of [a fridge magnet / a magnet on a cupboard door] and say what a magnet can do. End with two things a magnet can pick up at home." },
  { id: "science-977", title: "Test which things a magnet picks up", category: "science", text: "Plan a magnet test for kids using [a coin, a nail, a spoon, a key, a pencil and a plastic toy]. Ask the child to guess first which items the magnet will pick up, then test each one and record the result in a simple table." },
  { id: "science-978", title: "Why do magnets stick to a fridge", category: "science", text: "Explain why a magnet sticks to a fridge door but falls off a wooden door. Talk about iron and steel in simple words, using [a fridge magnet and a wooden cupboard] as the example. Add one more place magnets stick at home." },
  { id: "science-979", title: "North and south poles of a magnet", category: "science", text: "Explain the north and south poles of a bar magnet in simple words. Show how two north poles push each other away and a north and south pole pull together. Suggest a safe test with [two bar magnets] on a table." },
  { id: "science-980", title: "Make a magnet pick up paper clips", category: "science", text: "Give steps to make a paper clip chain with one magnet. Show how the magnet can hold [3 / 5] paper clips in a line and how the chain falls when the magnet is taken away. Explain in simple words why this happens, for a child aged [8]." },
  { id: "science-981", title: "Can a magnet work through paper", category: "science", text: "Plan a simple test to see if a magnet can pull a paper clip through paper, cloth and cardboard. Place the clip under each material and move the magnet on top. Tell the child what the result shows about magnets, using [a fridge magnet]." },
  { id: "science-982", title: "Why do two magnets push each other away", category: "science", text: "Explain why two magnets sometimes push each other away and will not touch. Use the idea of like poles pushing apart, in very simple words. Suggest a game where the child tries to push two magnets together on [a wooden table]." },
  { id: "science-983", title: "Make a magnet fishing game for kids", category: "science", text: "Help a child make a fishing game with a stick, string, a magnet and paper fish with paper clips on them. Give steps to build it and rules to play it. Explain in simple words why the magnet catches the fish in [a tub of water]." },
  { id: "science-984", title: "Where do we use magnets at home", category: "science", text: "List [8] places where magnets are used at home, like fridge doors, cupboard catches, phone covers and toy trains. Explain each use in one simple line, using examples a child can find in [your kitchen / your bedroom]." },
  { id: "science-985", title: "Test a magnet in water with a coin", category: "science", text: "Plan a test to see if a magnet still works under water. Drop [a steel coin / a paper clip] into a glass of water and try to lift it with a magnet from outside the glass. Tell the child what to note." },
  { id: "science-986", title: "How does a compass needle find north", category: "science", text: "Explain how a compass needle finds north, in simple words for a child. Say that the Earth acts like a giant magnet and the needle lines up with it. Suggest testing a compass in [your garden / a park] with an adult." },
  { id: "science-987", title: "Make a magnet maze game on cardboard", category: "science", text: "Help a child make a magnet maze on cardboard, with a paper clip on top and a magnet under the board. Give steps to draw the maze path and rules to finish it without lifting the clip. Explain why the clip follows the magnet under [a cardboard board]." },
  { id: "science-988", title: "Which magnet is stronger in a test", category: "science", text: "Plan a fair test to compare two magnets, like [a fridge magnet and a bar magnet]. Count how many paper clips each one can hold in a chain. Tell the child how to record the winner and why one magnet is stronger." },
  { id: "science-989", title: "Why do magnets lose power when heated", category: "science", text: "Explain in simple words why a magnet becomes weak if it is heated or dropped again and again. Keep the language gentle for a child aged [8 / 10] and add a safety note never to heat a magnet at home." },
  { id: "science-990", title: "Magnets in a train that floats above track", category: "science", text: "Explain in simple words how a maglev train floats above its track using magnets. Say how pushing magnets apart lifts the train and helps it move fast without wheels touching the track. Add one fact about fast trains in [Japan / China]." },
  { id: "science-991", title: "Make a magnet car race on a table", category: "science", text: "Help two children race toy cars with magnets under a table, moving each car by sliding a magnet below. Give steps to set it up and rules to race fairly. Explain in simple words how the magnet moves the car on [a dining table]." },
  { id: "science-992", title: "Test magnets with sand and iron filings", category: "science", text: "Plan a safe test where a magnet pulls tiny iron bits out of a tray of sand, with an adult helping. Say what to use, how to move the magnet slowly, and what the child will see. Remind them to wash hands after, using [soap and water]." },
  { id: "science-993", title: "Why do some metals not stick to magnets", category: "science", text: "Explain why a magnet sticks to iron and steel but not to aluminium, copper or plastic. Use the example of [a steel spoon, an aluminium vessel and a plastic bottle] and ask the child to test each one at home." },
  { id: "science-994", title: "Make a hanging magnet mobile for kids", category: "science", text: "Help a child make a hanging mobile with magnets, string and light paper shapes. Show how the shapes hang in the air under a magnet and swing gently. Explain in simple words how the magnet holds them up in [a bedroom]." },
  { id: "science-995", title: "How do magnets help doctors in hospitals", category: "science", text: "Explain in simple words how doctors use a big magnet machine to take pictures inside the body. Say that it is safe, painless and helps doctors see bones and organs. Keep the words gentle for a child aged [8 / 10]." },
  { id: "science-996", title: "Test a magnet through your hand", category: "science", text: "Show a child that a magnet can pull a paper clip even with a hand in between. Hold the clip in one hand, move the magnet under the hand, and watch the clip move. Explain in simple words that magnets work through skin, for a child aged [7]." },
  { id: "science-997", title: "Why do fridge magnets fall off sometimes", category: "science", text: "Explain why a heavy fridge magnet falls off when you stick too many papers under it. Talk about weight and magnet strength in simple words. Suggest a test with [1, 3 and 5] sheets of paper under one magnet." },
  { id: "science-998", title: "Make a magnet powered doorbell model", category: "science", text: "Help a child build a simple model of a doorbell using a magnet, a battery, wires and a bell, with an adult helping. Explain in simple words how pressing the button on [a toy doorbell] makes the magnet pull a hammer to ring the bell." },
  { id: "science-999", title: "Magnets in phones and earphones for kids", category: "science", text: "Explain in simple words where magnets hide inside a phone and earphones. Say how a tiny magnet in an earphone makes sound by moving quickly. Use the example of [your family phone / a pair of earphones] at home." },
  { id: "science-1000", title: "A fun magnet quiz for class 4", category: "science", text: "Make a fun magnet quiz for class 4 with [10] simple questions about poles, fridge magnets, compasses and metals. Give four options for each question and an answer key at the end, with one-line simple explanations." },
  { id: "science-1001", title: "How to make a temporary magnet at home", category: "science", text: "Give safe steps to turn a steel nail into a temporary magnet by rubbing it with a bar magnet in one direction many times. Show how to test it with paper clips and explain why the nail loses its power after a while, for a child aged [9]." },
  { id: "science-1002", title: "Why do magnets attract from a distance", category: "science", text: "Explain why a magnet can pull a paper clip even before it touches it. Talk about the unseen force around a magnet in simple words. Suggest a test to find how far away a magnet on [a ruler] can still pull a clip." },
  { id: "science-1003", title: "Test a magnet on a bicycle and gate", category: "science", text: "Ask a child to test a magnet on [a bicycle frame, a steel gate and an aluminium window frame] at home. Tell them to record which parts attract the magnet and which do not, and explain the result in simple words." },
  { id: "science-1004", title: "Make a magnet treasure hunt in sand", category: "science", text: "Help a child set up a treasure hunt by hiding steel coins and nails in a tray of sand. Give steps to find them with a magnet, plus rules to play with a friend. Explain why the magnet finds only metal treasure in [a sand tray]." },
  { id: "science-1005", title: "How do magnets close a handbag flap", category: "science", text: "Explain how a small magnet inside a handbag flap keeps the bag closed. Use the example of [a school bag / a purse at home] and say why a magnet catch is easier than a button for children to open and close." },
  { id: "science-1006", title: "Why is the Earth like a giant magnet", category: "science", text: "Explain why scientists say the Earth acts like a giant magnet. Talk about the north and south poles and how compasses use them, in simple words for a child aged [8 / 10]. Add one question to ask a teacher." },
  { id: "science-1007", title: "Test how many coins a magnet lifts", category: "science", text: "Plan a test to see how many coins one magnet can lift in a stack. Use [₹1, ₹2 and ₹5] coins and try them one by one. Tell the child how to record the number and why the stack falls when it gets too heavy." },
  { id: "science-1008", title: "Make a floating magnet with two ring magnets", category: "science", text: "Give steps to float one ring magnet above another on a pencil, with the like poles facing each other. Explain in simple words why the top magnet floats and does not fall down. Ask an adult to help with the setup on [a study table]." },
  { id: "science-1009", title: "Why do toy trains use magnets to join", category: "science", text: "Explain why many toy trains use magnets to join the coaches together. Say how the magnets snap together easily and come apart with a gentle pull. Use the example of [a toy train set / a magnetic building toy] at home." },
  { id: "science-1010", title: "How do magnets sort scrap metal pieces", category: "science", text: "Explain how a big magnet at a scrap yard lifts iron and steel pieces but leaves other metals behind. Keep the words simple for a child and say why sorting metal this way helps recycling in [your city]." },
  { id: "science-1011", title: "Test a magnet with a glass of water", category: "science", text: "Show a child that a magnet can pull a steel paper clip through the side of a glass of water. Give steps to place the clip inside, move the magnet outside, and watch the clip follow. Explain the result in simple words, for a child aged [7 / 8]." },
  { id: "science-1012", title: "Why do magnets need care and safe storage", category: "science", text: "Explain how to look after magnets at home, like keeping them away from phones, bank cards and TVs. Say why strong magnets can harm these things, in simple words, and where to store magnets safely in [a plastic box]." },
  { id: "science-1013", title: "Make a magnet wand to tidy small pins", category: "science", text: "Help a child make a magnet wand from a stick and a strong magnet to pick up fallen pins and paper clips from the floor. Give steps to use it safely and explain why the wand is handy in a sewing or craft box at [home]." },
  { id: "science-1014", title: "How does a magnet hold a knife strip", category: "science", text: "Explain how a magnetic strip on a kitchen wall holds knives safely in place. Use the example of [a kitchen in your home] and say why the knives stay up but come off with a gentle pull. Add a safety note for children." },
  { id: "science-1015", title: "Test a magnet on coins from different years", category: "science", text: "Ask a child to test a magnet on [₹1, ₹2, ₹5 and ₹10] coins and note which ones stick. Explain in simple words that coins are made from different metals, so some attract a magnet and some do not." },
  { id: "science-1016", title: "Why do magnets spin freely on a string", category: "science", text: "Explain what happens when you hang a bar magnet from a string and let it spin freely. Say that it stops pointing north and south, like a compass. Suggest a safe test with [a bar magnet and a thread] at home." },
  { id: "science-1017", title: "Make a magnet board for school notes", category: "science", text: "Help a child make a magnet board from a steel tray and colourful magnets to pin school notes and drawings. Give steps to set it up on [a study table / a bedroom wall] and ideas for what to pin each week." },
  { id: "science-1018", title: "How do magnets help in a wind turbine", category: "science", text: "Explain in simple words how magnets inside a wind turbine help make electricity. Say how wind turns the blades, the blades spin a magnet, and the moving magnet makes power for homes in [your state / your town]." },
  { id: "science-1019", title: "Test a magnet after dropping it many times", category: "science", text: "Plan a careful test to see if dropping a magnet again and again makes it weaker. Count how many paper clips it holds before and after [10] gentle drops onto a soft cloth. Tell the child what the result shows." },
  { id: "science-1020", title: "Why do some cupboards use magnetic catches", category: "science", text: "Explain why cupboard doors use a small magnet catch to stay shut. Use the example of [a kitchen cupboard / a bedroom cupboard] and say how the magnet holds the door but lets it open with a gentle pull." },
  { id: "science-1021", title: "Make a magnet powered spinning top toy", category: "science", text: "Help a child make a spinning top that balances on a magnet base, with an adult helping. Give steps to build it from a pencil, a disc and a magnet. Explain in simple words why the magnet holds the top up while it spins on [a table]." },
  { id: "science-1022", title: "How do magnets keep a fridge door shut", category: "science", text: "Explain how a strip of magnet inside a fridge door seal keeps cold air inside. Use the example of [your kitchen fridge] and say what happens if the seal is weak. Add one tip to check if a fridge door closes well." },
  { id: "science-1023", title: "Test a magnet with a compass nearby", category: "science", text: "Show a child how a bar magnet makes a compass needle turn when it comes close. Place the compass on a table, bring the magnet near slowly, and note how the needle moves. Explain in simple words why this happens, for a child aged [8]." },
  { id: "science-1024", title: "Why do scientists use magnets in labs", category: "science", text: "Explain in simple words how scientists use magnets in labs to lift, sort and test materials. Give two easy examples a child can understand, like separating iron from sand and holding tools in place. Keep the language simple, for a child aged [9 / 10]." },
  { id: "science-1025", title: "Magnet discoveries matching game for kids", category: "science", text: "Make a matching game for kids with [8] magnet facts and their uses, like compass, fridge door, toy train and hospital scan. Give the fact list, the use list and the answers, in simple words for class 4." },
];
